/* テキストの「さらに深く」拡充(担当:高校 物理・化学・生物・地学) */
(function (L) {
  function add(id, o) {
    var x = L[id]; if (!x) return;
    ['secs', 'drill', 'faq'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); });
  }

  /* ===================== 物理 ===================== */
  add('p4_mech', {
    secs: [
      { h: 'さらに深く:重心から見ると、衝突で失われるエネルギーが一発で分かる', t: '2物体の衝突を、地面に立った人ではなく、【重心といっしょに動く人】から見てみましょう。外力がなければ重心の速度 v_G は衝突の前後で変わらないので、この人はずっと等速で動く、正しい観測者です。\nこの人から見ると、2物体の運動量の和はいつも0です。つまり、2物体は重心に向かって「近づき」、衝突後は重心から「遠ざかる」だけに見えます。\nここで大事な事実があります。2物体の運動エネルギーの和は、次の2つに分けられます。\n【K＝(1/2)(m₁＋m₂)v_G²＋(1/2)μ u²】\nu は相対速度(v₁−v₂)、μ＝m₁m₂/(m₁＋m₂) は【換算質量】とよばれる量です。前の項は「重心の運動のエネルギー」で、外力がないかぎり衝突でも変わりません。変わりうるのは後ろの項、「相対運動のエネルギー」だけです。\nはね返り係数 e の衝突では、相対速度の大きさが e 倍になるので、相対運動のエネルギーは e² 倍になります。したがって、衝突で失われる運動エネルギーは\n【ΔK＝(1/2)μ u²(1−e²)】\nとなります。完全弾性衝突(e＝1)なら失われず、完全非弾性衝突(e＝0)なら相対運動のエネルギーがすべて失われます。完全非弾性衝突で一体になったあとも物体が動いているのは、重心の運動のエネルギーが残るからです。\nこの式を使うと、衝突後の速度をいちいち求めなくても、失われたエネルギーをすぐに計算でき、検算にも使えます。', key: '運動エネルギー＝重心の運動の分＋相対運動の分。衝突で変わるのは相対運動の分だけで、失われる量は (1/2)μu²(1−e²)。', ex: [{ q: 'なめらかな水平面上で、質量 2.0 kg の物体Aが 3.0 m/s で進み、静止している質量 1.0 kg の物体Bに正面衝突した。はね返り係数は 0.50 である。衝突で失われた運動エネルギーを、(1)換算質量の式で (2)衝突後の速度を求めて、の2通りで求めよ。', hint: 'μ＝m₁m₂/(m₁＋m₂)、u は衝突前の相対速度です。', steps: ['(1) 換算質量は μ＝2.0×1.0/(2.0＋1.0)＝2/3 kg。衝突前の相対速度は u＝3.0−0＝3.0 m/s。', '失われるエネルギーは ΔK＝(1/2)×(2/3)×3.0²×(1−0.50²)＝3.0×0.75＝2.25 J。', '(2) 衝突後の速度を v_A、v_B とする。運動量保存:2.0×3.0＝2.0v_A＋1.0v_B。はね返り係数:v_B−v_A＝0.50×3.0＝1.5。', '2式を解くと v_A＝1.5 m/s、v_B＝3.0 m/s。衝突前の運動エネルギーは (1/2)×2.0×3.0²＝9.0 J、衝突後は (1/2)×2.0×1.5²＋(1/2)×1.0×3.0²＝2.25＋4.5＝6.75 J。', '差は 9.0−6.75＝2.25 J で、(1)と一致する。'], a: '約 2.3 J(2.25 J)', check: '重心の速度は (2.0×3.0)/3.0＝2.0 m/s で、衝突後も (2.0×1.5＋1.0×3.0)/3.0＝2.0 m/s と変わらない。重心の運動のエネルギー (1/2)×3.0×2.0²＝6.0 J は衝突の前後で共通で、相対運動の分が 3.0 J→0.75 J に減ったと読める。' }] },
      { h: '実戦演習:動ける台の上をすべる小球', t: '台が床の上を自由に動ける問題は、入試の定番です。台が固定されていれば「力学的エネルギー保存」だけで解けますが、台が動くと、小球が台を押し、台も動きだします。\n戦略は次の2本立てです。\n①【水平方向の運動量保存】:小球と台をひとまとめにすると、水平方向には外力がありません(床はなめらか、重力と垂直抗力は鉛直)。鉛直方向は床からの力があるので保存しません。\n②【力学的エネルギー保存】:面がなめらかなら摩擦熱が出ないので、小球と台の運動エネルギーと位置エネルギーの和が保存します。\nよくある落とし穴は、(a)運動量を「鉛直方向も」保存させてしまう、(b)小球だけでエネルギー保存の式を立ててしまう(台のエネルギーを忘れる)、の2つです。また、台の移動距離は、水平方向の【重心が動かない】ことから求めるのが速い方法です。', key: '保存するのは「水平方向」の運動量と「系全体」の力学的エネルギー。移動距離は重心の位置が動かないことで決める。', ex: [{ q: 'なめらかな水平な床の上に、質量 M＝3.0 kg の台が置かれている。台には半径 R＝0.50 m の4分の1円の、なめらかな曲面があり、曲面の下端は水平になっている。質量 m＝1.0 kg の小球を、曲面の上端(下端より R だけ高い点)から静かにはなした。(1)小球が曲面の下端に達したときの、小球と台の速さを求めよ。(2)その間に台が動いた距離を求めよ。(g＝9.8 m/s²)', hint: '下端では小球も台も水平に動いています。運動量は水平方向だけ保存します。', steps: ['小球と台をひとまとめにした系では、水平方向に外力がないので、水平方向の運動量が保存する。はじめは静止しているので、下端での小球の速度を v(右向き)、台の速度を V とすると、mv＋MV＝0、つまり V＝−v/3。台は小球と逆向きに動く。', '面はなめらかなので力学的エネルギーが保存する:mgR＝(1/2)mv²＋(1/2)MV²。V＝−v/3 を代入して、1.0×9.8×0.50＝(1/2)×1.0×v²＋(1/2)×3.0×v²/9。', '右辺は (1/2)v²×(1＋1/3)＝(2/3)v²。よって v²＝4.9×3/2＝7.35、v≒2.7 m/s。台の速さは V≒0.90 m/s。', '(2) 水平方向の重心の位置は動かない(重心の速度がずっと0だから)。小球が台に対して水平に R＝0.50 m 動く間に、床に対して小球が x、台が −X 動いたとすると、mx＝MX、x＋X＝R。', 'X＝mR/(m＋M)＝1.0×0.50/4.0＝0.125 m。台は小球と逆向きに約 0.13 m 動く。'], a: '(1)小球 約 2.7 m/s、台 約 0.90 m/s(逆向き) (2)約 0.13 m', check: 'エネルギーの検算:(1/2)×1.0×7.35＋(1/2)×3.0×(2.711/3)²≒3.68＋1.22＝4.9 J＝mgR。台が固定なら v＝√(2gR)≒3.1 m/s で、台が動くぶん小球が遅くなるのは、位置エネルギーの一部を台が受け取るからと説明できる。' }] }
    ],
    drill: [
      { lv: 2, q: 'なめらかな直線上を、質量 6.0 kg の物体Aが右向きに 2.0 m/s、質量 2.0 kg の物体Bが左向きに 4.0 m/s で進んでいる。2物体の重心の速度を求めよ。また、2物体が衝突して一体になったあとの速度を求めよ。', a: 'どちらも右向きに 0.50 m/s', exp: '重心の速度は「運動量の和÷質量の和」です。右向きを正とすると、運動量の和は 6.0×2.0＋2.0×(−4.0)＝12−8＝4.0 kg·m/s、質量の和は 8.0 kg なので、v_G＝4.0/8.0＝0.50 m/s。一体になった物体は、その重心とともに動くので、衝突後の速度も同じ 0.50 m/s になります。一体になる衝突では「衝突後の速度＝重心の速度」と覚えておくと、運動量保存の式を立てる前に答えが予想できます。左向きの速度に負号をつけ忘れると (12＋8)/8＝2.5 m/s というまちがいになるので、向きの符号に注意しましょう。' },
      { lv: 3, q: 'なめらかな水平面上で、質量 1.0 kg の物体Aが 4.0 m/s で進み、静止している質量 3.0 kg の物体Bに完全弾性衝突(e＝1)した。衝突後のA、Bの速度を求め、運動エネルギーの和が保存されていることを確かめよ。', a: 'A は逆向きに 2.0 m/s、B は 4.0 m/s の向きに 2.0 m/s。運動エネルギーの和は前後とも 8.0 J', exp: '進む向きを正とします。運動量保存は 1.0×4.0＝1.0v_A＋3.0v_B、はね返り係数 e＝1 から v_B−v_A＝4.0。2式を足して整理すると 4.0v_B＝8.0、v_B＝2.0 m/s、v_A＝−2.0 m/s です。A は軽いので、重いBにぶつかってはね返されます。衝突前の運動エネルギーは (1/2)×1.0×4.0²＝8.0 J、衝突後は (1/2)×1.0×2.0²＋(1/2)×3.0×2.0²＝2.0＋6.0＝8.0 J で保存しています。重心の速度は (1.0×4.0)/4.0＝1.0 m/s で、重心から見るとAは 3.0 m/s で近づき 3.0 m/s で遠ざかる(相対速度の大きさが同じ)ことも確かめられます。' },
      { lv: 3, q: '水平な円板が鉛直な軸のまわりに回転している。軸から 0.10 m の位置に小物体をのせ、円板の回転を少しずつ速くしていくと、ある角速度をこえたところで小物体がすべり出した。小物体と円板の間の静止摩擦係数を 0.40 として、すべり出す直前の角速度を求めよ。(g＝9.8 m/s²)', a: '約 6.3 rad/s', exp: '円板の上で小物体が円運動するとき、中心向きの力(向心力)を出しているのは【静止摩擦力】です。必要な向心力は mrω² で、角速度が大きくなるほど大きくなります。静止摩擦力の最大値は最大摩擦力 μmg なので、すべらない条件は mrω²≦μmg です。等号のときがすべり出す直前で、ω＝√(μg/r)＝√(0.40×9.8/0.10)＝√39.2≒6.3 rad/s です。質量 m は両辺から消えるので、答えに関係しません。まちがえやすいのは、「遠心力が摩擦力に勝つ」と考えて力の向きを外向きにしてしまうことです。円板の上から見れば遠心力を使ってもよいのですが、その場合は回転する観測者の立場だと明記して、遠心力 mrω² と摩擦力のつり合いとして式を立てます。' }
    ],
    faq: [
      ['内力は運動量を変えないのに、運動エネルギーは変えられるのはなぜ?', '内力(物体どうしがおよぼし合う力)は、作用・反作用で同じ大きさ・逆向き・同じ時間だけはたらくので、力積は打ち消し合い、運動量の和は変わりません。ところが仕事は「力×移動距離」で、衝突中の2物体の移動距離は同じではありません。そのため2つの仕事は打ち消し合わず、運動エネルギーの和は変わりえます。ばねの場合は縮んだ分だけ弾性エネルギーにため、物体が変形する場合は熱や音に変わります。'],
      ['重心系(重心とともに動く立場)で考えると、何が楽になるの?', '重心系では運動量の和がいつも0なので、2物体の速度はいつも逆向きで、大きさの比が質量の逆比になります。衝突は「近づいてきて、はね返って遠ざかる」だけの左右対称な現象に見え、はね返り係数 e の衝突では両方の速さがそのまま e 倍になります。最後に重心の速度を足せば、地面から見た速度にもどせます。計算の見通しがよくなり、検算にも便利です。']
    ]
  });

  add('p4_heat', {
    secs: [
      { h: 'さらに深く:断熱変化で pV^γ が一定になる理由', t: '断熱変化では熱の出入りがないので、熱力学第一法則は【ΔU＝W】(W は気体がされた仕事)だけになります。気体が少し膨張して体積が ΔV ふえると、気体は外へ pΔV の仕事をするので、内部エネルギーはその分だけ減ります。単原子分子の理想気体なら、(3/2)nRΔT＝−pΔV です。\nここに状態方程式 p＝nRT/V を入れると、(3/2)ΔT/T＝−ΔV/V となります。これは「温度の変化の割合」と「体積の変化の割合」が比例することを表していて、少しずつの変化を積み重ねると【TV^(2/3)＝一定】という関係が得られます。さらに T＝pV/(nR) を代入すると【pV^(5/3)＝一定】になります。5/3 が比熱比 γ＝Cₚ/Cᵥ です。二原子分子なら Cᵥ＝(5/2)R なので γ＝7/5 になります。\n具体例:単原子分子の理想気体を断熱圧縮して体積を 1/8 にすると、TV^(2/3)＝一定 から温度は 8^(2/3)＝4 倍、pV^(5/3)＝一定 から圧力は 8^(5/3)＝32 倍になります。等温圧縮なら圧力は8倍にしかなりません。断熱では、押し縮めた仕事がすべて内部エネルギー(温度)になるので、その分だけ圧力がよけいに上がるのです。ディーゼルエンジンが点火プラグなしで燃料に火をつけられるのは、この断熱圧縮による温度上昇を利用しているからです。\n分子の立場で見ると、ピストンが近づいてくるとき、分子は動く壁にはね返されて速さを増します(ボールをバットで打ち返すのと同じ)。逆に断熱膨張では、遠ざかる壁にはね返って速さが減るので、温度が下がります。', key: '断熱では ΔU＝W だけ。そこから TV^(γ−1)＝一定、pV^γ＝一定 が出る。単原子分子は γ＝5/3、体積 1/8 で温度4倍・圧力32倍。', ex: [{ q: '単原子分子の理想気体 1.0 mol が、300 K、体積 V₀ の状態にある。これを断熱的に圧縮して体積を V₀/8 にした。(1)圧縮後の温度 (2)この間に気体がされた仕事 を求めよ。(R＝8.3 J/(mol·K))', hint: 'TV^(2/3)＝一定 を使い、仕事は ΔU から求めます(断熱なので Q＝0)。', steps: ['断熱変化なので TV^(γ−1)＝一定。単原子分子では γ−1＝2/3 である。', 'T×(V₀/8)^(2/3)＝300×V₀^(2/3) より、T＝300×8^(2/3)＝300×4＝1200 K。', '断熱では Q＝0 なので、第一法則から気体がされた仕事 W＝ΔU。', 'ΔU＝(3/2)nRΔT＝(3/2)×1.0×8.3×(1200−300)＝1.5×8.3×900≒1.1×10⁴ J。'], a: '(1)1200 K (2)約 1.1×10⁴ J(11205 J)', check: '圧力は pV^(5/3)＝一定 から 32 倍になる。状態方程式で確かめると、体積 1/8・温度4倍なら p は 4×8＝32 倍で一致する。仕事を p-V グラフの面積として積分しても同じ値になるが、ΔU から出す方がはるかに速い。' }] },
      { h: '実戦演習:2つの容器の気体をつなぐ', t: '断熱容器どうしをコックでつなぐ問題は、「何が保存するか」を見抜く力が試されます。\n戦略:①コックを開けて気体が混ざるとき、気体はまわりに仕事をしない(真空や相手の気体の中へ広がるだけで、ピストンを押していない)、容器が断熱なので熱も出入りしない。よって【内部エネルギーの和が保存】します。②物質量の和も保存します。③最後に状態方程式で圧力を出します。\n落とし穴は、「温度の平均」を物質量で重みをつけずに単純平均してしまうことです。内部エネルギーは nT に比例するので、単原子分子どうしなら最終温度は (n₁T₁＋n₂T₂)/(n₁＋n₂) という【物質量の重みつき平均】になります。種類のちがう気体(単原子と二原子)を混ぜるときは、Cᵥ の重みもつくので注意しましょう。\nまた、「膨張したのだから仕事をした」と考えてしまうのもよくあるまちがいです。仕事は、気体が動く物体(ピストンなど)を押して動かしたときにだけ生じます。', key: '断熱容器をつなぐだけなら Q＝0、W＝0 なので内部エネルギーの和が保存。最終温度は nCᵥ の重みつき平均。', ex: [{ q: '断熱材でおおわれた容器A(容積 2.0×10⁻² m³)と容器B(容積 3.0×10⁻² m³)が、細い管とコックでつながれている。はじめコックは閉じていて、A には単原子分子の理想気体 1.0 mol が 300 K で、B には同じ気体 2.0 mol が 400 K で入っている。コックを開けて十分に時間がたったあとの (1)温度 (2)圧力 を求めよ。管の容積と、容器の熱容量は無視する。(R＝8.3 J/(mol·K))', hint: '内部エネルギーの和 (3/2)nRT の合計が変わりません。', steps: ['コックを開けたとき、気体は外部(ピストンなど)を押していないので W＝0、断熱なので Q＝0。よって内部エネルギーの和が保存する。', 'はじめの和は (3/2)R(1.0×300＋2.0×400)＝(3/2)R×1100、あとの和は (3/2)R×3.0×T。', 'これらが等しいので T＝1100/3.0≒367 K。', '最後は全体の容積 5.0×10⁻² m³ に 3.0 mol が入っているので、p＝nRT/V＝3.0×8.3×(1100/3)/(5.0×10⁻²)。', 'nT＝1100 なので p＝8.3×1100/0.050≒1.8×10⁵ Pa。'], a: '(1)約 3.7×10² K(367 K) (2)約 1.8×10⁵ Pa', check: 'はじめの圧力は A が 1.0×8.3×300/0.020≒1.2×10⁵ Pa、B が 2.0×8.3×400/0.030≒2.2×10⁵ Pa。最終の圧力 1.8×10⁵ Pa はその間にあり、もっともらしい。最終温度も 300 K と 400 K の間で、物質量の多い B 寄りになっている。' }] }
    ],
    drill: [
      { lv: 2, q: '単原子分子の理想気体 1.0 mol が断熱膨張し、温度が 400 K から 300 K に下がった。気体が外部にした仕事を求めよ。(R＝8.3 J/(mol·K))', a: '約 1.2×10³ J(1245 J)', exp: '断熱変化では熱の出入りがない(Q＝0)ので、第一法則 ΔU＝Q＋W より、気体がされた仕事 W は ΔU に等しくなります。ΔU＝(3/2)nRΔT＝(3/2)×1.0×8.3×(300−400)＝−1245 J。気体がされた仕事が −1245 J なので、気体が外部にした仕事は ＋1245 J です。つまり、断熱膨張で気体がする仕事は、すべて内部エネルギーを使って生み出されています。温度が下がるのはそのためです。「W の符号」は教科書によって「した仕事」「された仕事」のどちらで書くかが違うので、式を立てる前に定義を確かめることが大切です。' },
      { lv: 3, q: 'ばねのついたピストンで閉じこめた単原子分子の理想気体を加熱したところ、圧力 p と体積 V が p-V グラフ上で直線的に変化し、状態 (1.0×10⁵ Pa, 1.0×10⁻³ m³) から (3.0×10⁵ Pa, 3.0×10⁻³ m³) になった。気体がした仕事、内部エネルギーの変化、吸収した熱量を求めよ。', a: '仕事 400 J、内部エネルギーの変化 ＋1200 J、吸収した熱量 1600 J', exp: '気体がした仕事は p-V グラフの下の面積です。ここでは台形なので、(1.0×10⁵＋3.0×10⁵)/2×(3.0×10⁻³−1.0×10⁻³)＝2.0×10⁵×2.0×10⁻³＝400 J。内部エネルギーは単原子分子なら U＝(3/2)nRT＝(3/2)pV と書けるので、ΔU＝(3/2)(p₂V₂−p₁V₁)＝1.5×(900−100)＝1200 J です。n や T が与えられていなくても、pV の積から直接計算できるのがポイントです。第一法則より Q＝ΔU＋(した仕事)＝1200＋400＝1600 J。定圧でも定積でもない変化なので、Cₚ や Cᵥ の公式は直接使えません。「面積で仕事、pV で内部エネルギー、第一法則で熱」の順に求めるのが確実です。' },
      { lv: 3, q: '温度 600 K の高温熱源と 300 K の低温熱源の間ではたらく熱機関について、「1サイクルで高温熱源から 1.0×10³ J の熱を受け取り、600 J の仕事をする」という主張がある。これは可能か。理由とともに答えよ。', a: '不可能。この温度の組み合わせでの熱効率の上限は 50% で、主張の熱効率 60% はそれを超えている', exp: '2つの熱源の間ではたらく熱機関の熱効率には上限があり、それは理想的なカルノーサイクルの効率 1−T₂/T₁(T は絶対温度)です。ここでは 1−300/600＝0.50、つまり 50% が上限です。主張では 600/1000＝0.60 で 60% なので、熱力学第二法則に反し、実現できません。エネルギー保存(第一法則)だけを見ると、受け取った熱 1000 J のうち 600 J を仕事にして 400 J を低温熱源に捨てればよく、矛盾がないように見えるのが落とし穴です。熱効率の上限は熱源の温度で決まり、どんな工夫をしても超えられません。温度は必ず絶対温度で計算します(セルシウス温度で 1−27/327 などとするのは誤り)。' }
    ],
    faq: [
      ['真空に向かって気体が広がる(自由膨張)と、温度はどうなるの?', '理想気体なら温度は変わりません。真空中に広がるとき、気体は押し返してくる相手がいないので仕事をせず(W＝0)、断熱なら熱も出入りしない(Q＝0)ので ΔU＝0、つまり温度一定です。同じ「断熱膨張」でも、ピストンを押しながらゆっくり膨張する場合は仕事をする分だけ温度が下がります。膨張したかどうかではなく、「外へ仕事をしたかどうか」で温度変化が決まるのです。'],
      ['断熱曲線が等温曲線より急になるのはなぜ?', '同じ状態から体積を少しふやすとき、等温変化では熱が入ってきて温度が保たれます。断熱変化では熱が入らず、膨張の仕事のぶん温度が下がります。状態方程式 p＝nRT/V で、体積がふえる効果に「温度が下がる効果」が加わるので、圧力がより大きく下がります。そのため p-V グラフでは断熱曲線の傾きが急になります。式で見ると、等温は pV＝一定、断熱は pV^γ＝一定(γ＞1)のちがいです。']
    ]
  });

  add('p4_wave', {
    secs: [
      { h: 'さらに深く:斜めに動く音源のドップラー効果は「視線方向の成分」で決まる', t: 'ドップラー効果の式 f′＝V f/(V−v) で使う v は、音源の速さそのものではなく、【音源と観測者を結ぶ方向(視線方向)の速度成分】です。\nなぜでしょうか。ドップラー効果が起こるのは、音源が波を出しながら観測者との距離を変えるので、観測者に向かう波の間隔(波長)がつまったりのびたりするからでした。音源が視線に垂直に動いても、その瞬間には観測者との距離はほとんど変わらないので、波長も変わりません。距離を変えるのは視線方向の成分 v cosθ(θ は音源の速度と視線のなす角)だけです。\n具体例:まっすぐな道路を、振動数 660 Hz の音を出す車が 20 m/s で走っています。道路から離れた所にいる人に対し、車の速度と「車→人」の向きのなす角が 60° になった位置で出た音は、視線方向の成分が 20×cos60°＝10 m/s なので、f′＝340×660/(340−10)＝680 Hz で聞こえます(音速 340 m/s)。車が人のいちばん近くを通る瞬間に出た音は、θ＝90° なので 660 Hz のままです。\nこの考え方から、車が通り過ぎるときの音の高さは、真横を通る位置で急に変わるのではなく、なめらかに高い音から低い音へ移ることが分かります。また、線路の真横に立つより、線路から離れて立つほど、高さの変化はゆるやかになります。注意したいのは、「人が聞く瞬間」と「音が出た瞬間」では音源の位置がちがうことです。角度は、【音が出た瞬間の音源の位置】で考えます。', key: '式の v は「音源と観測者を結ぶ方向の速度成分」。真横向きの成分は振動数を変えない。角度は音が出た瞬間の位置で決める。', ex: [{ q: '振動数 500 Hz の音を出す音源が、一直線上を 30 m/s で動いている。静止した観測者から見て、音源の速度と「音源→観測者」の向きのなす角が 60° の位置で出た音の振動数を求めよ。また、なす角が 120° の位置で出た音の振動数を求めよ。(音速 340 m/s)', hint: '視線方向の速度成分は 30cosθ。120° では観測者から遠ざかる向きの成分になります。', steps: ['60° のとき、観測者に近づく向きの成分は 30×cos60°＝15 m/s。', '近づく音源なので f′＝340×500/(340−15)＝170000/325≒523 Hz。', '120° のとき、成分は 30×cos120°＝−15 m/s、つまり 15 m/s で遠ざかっている。', 'f′＝340×500/(340＋15)＝170000/355≒479 Hz。'], a: '60° のとき 約 523 Hz、120° のとき 約 479 Hz', check: '近づく位置では元より高く、遠ざかる位置では低いので向きは正しい。視線に垂直(90°)なら成分0で 500 Hz になり、2つの答えの間にある。速さ 30 m/s で真正面から近づく場合の 340×500/310≒548 Hz より変化が小さいことも確かめられる。' }] },
      { h: '実戦演習:ニュートンリングで波長と屈折率を測る', t: '平面ガラスの上に、曲率半径 R の大きな平凸レンズをのせて真上から単色光を当てると、同心円状のしま(ニュートンリング)が見えます。入試では、リングの半径と波長・曲率半径・屈折率の関係を式で導かせる問題がよく出ます。\n戦略:①中心から r の位置の空気層の厚さ d を、図形から求めます。三平方の定理で R²＝r²＋(R−d)²、d はとても小さいので d² を無視して【d≒r²/(2R)】。②光路差は往復分で 2d(媒質の屈折率が n なら 2nd)。③反射での位相のずれを数えます。上のレンズの下面(ガラス→空気)ではずれず、下のガラスの上面(空気→ガラス)で π ずれるので、ずれは1回。よって反射光で暗くなる条件は 2nd＝mλ(m＝0, 1, 2, …)です。\n落とし穴:中心(d＝0)は暗いことを忘れて、m を1から数えてしまうこと。中心を m＝0 として数えると、「中心から数えて k 番目の暗輪」は m＝k になります。また、すき間を液体で満たすと光路差が n 倍になり、リングの半径は 1/√n 倍に縮みます。', key: 'd≒r²/(2R) と「反射での位相のずれの回数」の2点で決まる。反射光の暗輪は 2nd＝mλ、半径 r＝√(mRλ/n)。', ex: [{ q: '曲率半径 1.5 m の平凸レンズを平面ガラスにのせ、真上から波長 6.0×10⁻⁷ m の単色光を当てて、反射光を真上から観察した。(1)中心の暗点を除いて、中心から数えて4番目の暗輪の半径を求めよ。(2)レンズとガラスのすき間を屈折率 1.33 の液体で満たすと、その暗輪の半径はいくらになるか。液体の屈折率はガラスより小さいとする。', hint: '暗輪の条件は 2nd＝mλ、d＝r²/(2R) です。', steps: ['空気層の厚さは d≒r²/(2R)。反射での位相のずれは、空気→ガラスの面での1回だけなので、反射光が暗くなる条件は 2d＝mλ。', 'd を代入すると r²/R＝mλ、r＝√(mRλ)。中心が m＝0 なので、4番目の暗輪は m＝4。', 'r＝√(4×1.5×6.0×10⁻⁷)＝√(3.6×10⁻⁶)≒1.9×10⁻³ m。', '(2) 液体中では光路差が 2nd になる。液体の屈折率がガラスより小さいので、位相のずれの回数は空気のときと同じ1回。暗輪の条件は 2nd＝mλ、r＝√(mRλ/n)。', 'r＝1.9×10⁻³/√1.33≒1.6×10⁻³ m。'], a: '(1)約 1.9 mm (2)約 1.6 mm', check: '√(3.6×10⁻⁶)＝1.897×10⁻³、1.897/√1.33＝1.645。液体中では波長が λ/n に短くなるので、しまが細かく(半径が小さく)なるのは自然。液体の屈折率がガラスより大きい場合は、位相のずれが2面とも起こるかどうかを数え直す必要があり、条件が入れかわる。' }] }
    ],
    drill: [
      { lv: 2, q: '音源が静止した観測者のいちばん近くを通り過ぎる瞬間に出した音は、観測者にどんな振動数で届くか。また、観測者が実際に「音の高さが元と同じ」と聞くのは、音源がどこにいるときか。', a: '元の振動数のまま届く。ただし観測者にその音が届くのは、音源が最接近点を少し通り過ぎたあとである', exp: '最接近点では、音源の速度は観測者との視線に垂直なので、視線方向の速度成分が0です。したがって、その瞬間に出た音の振動数は元のままです。しかし、音が観測者に届くまでには時間がかかり、その間に音源は先へ進んでいます。そのため、観測者が元の高さの音を聞いているとき、音源はすでに最接近点を通り過ぎています。ドップラー効果では、「音が出た瞬間の音源の位置」と「音を聞いた瞬間の音源の位置」を区別することが大切です。音速に比べて音源が十分おそければ、このずれは小さくなります。' },
      { lv: 3, q: '空気中にある屈折率 1.5 の薄い膜に、波長 600 nm の単色光を斜めに当てた。膜の中での屈折角 r の cos r は 0.80 である。反射光が強め合う膜の厚さのうち、最も薄いものを求めよ。', a: '125 nm', exp: '膜の上面と下面で反射した光の光路差は、斜め入射では 2nd cos r になります(2nd/cos r ではありません。膜の中を進む距離は長くなりますが、上面で反射する光も先へ進んで位相をかせぐので、その分を差し引くと cos r がかかります)。反射での位相のずれは、空気→膜(屈折率が大きくなる面)の反射で1回だけなので、強め合う条件は 2nd cos r＝(m＋1/2)λ。最も薄いのは m＝0 で、d＝λ/(4n cos r)＝600/(4×1.5×0.80)＝125 nm です。垂直入射(cos r＝1)なら 100 nm なので、斜めから見ると強め合う膜の厚さが変わり、シャボン玉の色が見る角度で変わる理由が分かります。' },
      { lv: 3, q: '1 mm あたり 500 本のすじが刻まれた回折格子に、波長 6.0×10⁻⁷ m の光を垂直に当てた。格子の向こう側のスクリーンに現れる明線は、中央の明線をふくめて最大で何本か。', a: '7 本', exp: '格子定数は d＝1 mm/500＝2.0×10⁻⁶ m です。明線の条件は d sinθ＝mλ で、sinθ は1より小さい(θ＜90°)ので、mλ＜d、つまり m＜d/λ＝2.0×10⁻⁶/6.0×10⁻⁷≒3.3 です。m は整数なので最大の次数は3。中央(m＝0)の両側に m＝1, 2, 3 の明線が1本ずつあるので、合計 1＋2×3＝7 本です。m＝3 では sinθ＝0.90 で、θ は約 64° になります。「片側だけ」数えて4本としたり、中央の明線を数え忘れたりするのがよくあるまちがいです。d/λ がちょうど整数になる場合、その次数は θ＝90° でスクリーンに届かないので数えません。' }
    ],
    faq: [
      ['ニュートンリングの中心が暗いのはなぜ?', '中心ではレンズとガラスが接していて、空気層の厚さがほぼ0です。それでも暗いのは、2つの反射光のうち、空気からガラスへ入る面で反射する光だけ位相が π(半波長分)ずれるからです。道のりの差がなくても半波長ずれているので、打ち消し合います。もし中心が明るく見えたら、それは位相のずれが2回(または0回)の組み合わせになっていることを意味します。'],
      ['救急車のサイレンが、通り過ぎるときになめらかに低くなるのはなぜ?', '振動数を変えるのは、音源の速度のうち観測者に向かう成分だけです。遠くから近づくときはほぼ真正面に向かってくるので成分が大きく高い音、真横を通るときは成分が0で元の高さ、遠ざかるときは成分が負になり低い音になります。角度は連続的に変わるので、音の高さもなめらかに変わります。道路から離れて立っているほど角度の変化がゆるやかになり、高さの変化もゆっくりに聞こえます。']
    ]
  });

  add('p4_elec', {
    secs: [
      { h: 'さらに深く:極板どうしが引き合う力は QE ではなく QE/2', t: '充電したコンデンサーの2枚の極板は、＋と−の電荷で引き合っています。その力の大きさはいくらでしょうか。極板間の電場を E、極板の電気量を Q とすると「F＝QE」と考えたくなりますが、正しくは【F＝QE/2】です。\n理由①(電場の分け方):極板間の電場 E は、＋極板がつくる電場 E/2 と、−極板がつくる電場 E/2 の和です。＋極板の電荷が受ける力は、自分以外、つまり−極板がつくる電場 E/2 からの力だけです(自分のつくる電場で自分を押すことはできません)。だから F＝Q×E/2 です。\n理由②(エネルギーで確かめる):電池を外して Q を一定にしたまま、極板間隔を x から x＋Δx に広げます。電気容量 C＝εS/x が小さくなるので、静電エネルギー U＝Q²/(2C)＝Q²x/(2εS) は Q²Δx/(2εS) だけ増えます。電池につながっていないので、このエネルギーは極板を引き離した外力の仕事 FΔx から来ています。よって F＝Q²/(2εS)。E＝Q/(εS) を使うと F＝QE/2 となり、理由①と一致します。\n具体例:面積 1.0×10⁻² m² の極板に 1.0×10⁻⁷ C を充電した真空中のコンデンサーでは、E＝Q/(ε₀S)≒1.1×10⁶ V/m、F＝QE/2≒0.056 N です。力は極板間隔によりません。\nこの「エネルギーの変化から力を求める」方法は、誘電体がコンデンサーに引きこまれる力など、直接計算しにくい力を求めるときにも使える強力な考え方です。', key: '極板が受ける力は、相手の極板がつくる電場 E/2 による。F＝QE/2＝Q²/(2εS)。エネルギーの変化÷移動距離 でも求められる。', ex: [{ q: '真空中で、面積 S＝1.0×10⁻² m² の平行板コンデンサーに Q＝1.0×10⁻⁷ C の電荷がたくわえられ、電池から切りはなされている。(1)極板間の電場の強さ (2)極板どうしが引き合う力の大きさ (3)極板間隔を 1.0 mm 広げるのに必要な仕事 を求めよ。(ε₀＝8.85×10⁻¹² F/m)', hint: '(3)は「力×距離」でも「静電エネルギーの増加」でも求められます。', steps: ['(1) 極板間の電場は E＝Q/(ε₀S)＝1.0×10⁻⁷/(8.85×10⁻¹²×1.0×10⁻²)≒1.13×10⁶ V/m。', '(2) 一方の極板の電荷は、もう一方の極板がつくる電場 E/2 から力を受けるので、F＝QE/2＝1.0×10⁻⁷×1.13×10⁶/2≒5.6×10⁻² N。', '(3) 電荷が一定なので、間隔を変えても E も F も変わらない。仕事は W＝FΔx＝5.6×10⁻²×1.0×10⁻³≒5.6×10⁻⁵ J。', '検算として、U＝Q²x/(2ε₀S) の増加分 Q²Δx/(2ε₀S)＝(1.0×10⁻⁷)²×1.0×10⁻³/(2×8.85×10⁻¹⁴)≒5.6×10⁻⁵ J と一致する。'], a: '(1)約 1.1×10⁶ V/m (2)約 5.6×10⁻² N (3)約 5.6×10⁻⁵ J', check: 'F＝QE としてしまうと 0.11 N となり、エネルギーの増加分のちょうど2倍になって矛盾する。2つの方法で一致することが、QE/2 が正しいことの確認になる。' }] },
      { h: '実戦演習:電池につないだまま極板を引き離す', t: '「電池をつないだまま」コンデンサーの形を変える問題は、エネルギーの収支が入試で最も差がつく所です。\n戦略:①電池につないだままなら【電圧 V が一定】、外していれば【電荷 Q が一定】。最初にこれを決めます。②C の変化から Q と U＝(1/2)CV² の変化を出します。③電池がした仕事は【W電池＝V×(電池を通った電気量)】。電荷が電池にもどされたときは負になります。④エネルギー保存:外力の仕事＋電池の仕事＝静電エネルギーの増加(＋ジュール熱)。ゆっくり動かすならジュール熱は無視できます。\n落とし穴は、「静電エネルギーが減ったから、外力は負の仕事をした」と早合点することです。電池につないだまま間隔を広げると、静電エネルギーは減りますが、それ以上に多くのエネルギーが電池にもどされる(電池が充電される)ので、外力は正の仕事をしています。極板は引き合っているのだから、引き離すには正の仕事が必要、という直感とも合います。', key: 'V 一定か Q 一定かを最初に決める。電池の仕事は V×ΔQ。外力の仕事＝ΔU−W電池 で求める。', ex: [{ q: '電気容量 2.0 μF の平行板コンデンサーを、起電力 10 V の電池につないだまま、極板間隔をゆっくり2倍に広げた。(1)コンデンサーの電荷の変化 (2)静電エネルギーの変化 (3)電池がした仕事 (4)外力がした仕事 を求めよ。', hint: '間隔2倍で容量は半分。電荷は電池にもどります。', steps: ['電池につないだままなので V＝10 V は一定。間隔を2倍にすると C＝εS/d は 1.0 μF になる。', '(1) 電荷は Q＝CV より 2.0×10⁻⁵ C から 1.0×10⁻⁵ C に、1.0×10⁻⁵ C 減る(電池にもどる)。', '(2) U＝(1/2)CV² は (1/2)×2.0×10⁻⁶×100＝1.0×10⁻⁴ J から 0.50×10⁻⁴ J に、5.0×10⁻⁵ J 減る。', '(3) 電池を通った電気量は −1.0×10⁻⁵ C(逆向きに押しもどされた)なので、W電池＝10×(−1.0×10⁻⁵)＝−1.0×10⁻⁴ J。電池は 1.0×10⁻⁴ J のエネルギーを受け取った。', '(4) エネルギー保存より、W外力＋W電池＝ΔU。W外力＝−5.0×10⁻⁵−(−1.0×10⁻⁴)＝＋5.0×10⁻⁵ J。'], a: '(1)1.0×10⁻⁵ C 減少 (2)5.0×10⁻⁵ J 減少 (3)−1.0×10⁻⁴ J(電池は 1.0×10⁻⁴ J 受け取る) (4)＋5.0×10⁻⁵ J', check: 'エネルギーの流れ:静電エネルギーの減少 5.0×10⁻⁵ J と外力の仕事 5.0×10⁻⁵ J の合計 1.0×10⁻⁴ J が電池に入った。極板は引き合っているので外力の仕事が正になるのも直感に合う。' }] }
    ],
    drill: [
      { lv: 2, q: '真空中の x 軸上で、原点に ＋2.0×10⁻⁹ C、x＝0.40 m の点に −2.0×10⁻⁹ C の点電荷を置いた。2つの電荷の中点(x＝0.20 m)での電場の強さと向き、電位を求めよ。(k＝9.0×10⁹ N·m²/C²、電位は無限遠を0とする)', a: '電場は 900 N/C で ＋x 向き(負電荷の向き)、電位は 0 V', exp: '中点はどちらの電荷からも 0.20 m です。＋電荷がつくる電場は、＋電荷から遠ざかる向き(＋x 向き)に k q/r²＝9.0×10⁹×2.0×10⁻⁹/0.040＝450 N/C。−電荷がつくる電場は、−電荷に向かう向き、つまりこれも ＋x 向きに 450 N/C です。電場はベクトルなので同じ向きどうし足して 900 N/C。一方、電位はスカラー(向きのない量)なので、kq/r の符号つきの和を取ります。9.0×10⁹×2.0×10⁻⁹/0.20＋9.0×10⁹×(−2.0×10⁻⁹)/0.20＝90−90＝0 V。「電位が0なら電場も0」とはならない典型例で、電場と電位のちがいがよく分かる問題です。' },
      { lv: 3, q: '電気容量 1.0 μF の空気コンデンサーを起電力 10 V の電池につないだまま、極板の間の半分の面積(極板間隔いっぱいの厚さ)を、比誘電率 3.0 の誘電体で満たした。(1)電気容量 (2)電荷の増加量 (3)静電エネルギーの増加量 (4)電池がした仕事 を求めよ。', a: '(1)2.0 μF (2)1.0×10⁻⁵ C (3)5.0×10⁻⁵ J (4)1.0×10⁻⁴ J', exp: '面積の半分に誘電体を入れると、「空気の部分」と「誘電体の部分」の2つのコンデンサーが【並列】につながったものと見なせます。それぞれの面積は S/2 なので、容量は空気部分が 0.50 μF、誘電体部分が 3.0×0.50＝1.5 μF で、合計 2.0 μF。電池につないだままなので V＝10 V 一定、電荷は 10 μC から 20 μC に 1.0×10⁻⁵ C 増えます。静電エネルギーは (1/2)CV² で 50 μJ から 100 μJ に 5.0×10⁻⁵ J 増加。電池の仕事は V×ΔQ＝10×1.0×10⁻⁵＝1.0×10⁻⁴ J です。電池の仕事の半分しかエネルギーが増えていないのは、残りが、誘電体が引きこまれる力の仕事(または、ゆっくり入れなければ熱)になったためです。厚さ方向の半分に入れる場合は直列と考える点と区別しましょう。' },
      { lv: 3, q: 'ある電池に 4.0 Ω の抵抗をつなぐと 0.50 A、9.0 Ω の抵抗につなぎかえると 0.25 A の電流が流れた。この電池の起電力と内部抵抗を求めよ。', a: '起電力 2.5 V、内部抵抗 1.0 Ω', exp: '起電力 E、内部抵抗 r の電池に外部抵抗 R をつなぐと、回路全体の抵抗は R＋r なので E＝I(R＋r) です。2つの場合について、E＝0.50×(4.0＋r)、E＝0.25×(9.0＋r) の2式が立ちます。等しいとおくと 2.0＋0.50r＝2.25＋0.25r、0.25r＝0.25 より r＝1.0 Ω、E＝0.50×5.0＝2.5 V です。検算すると、2つ目は 0.25×10＝2.5 V で一致します。端子電圧は V＝E−rI で、1つ目は 2.0 V、2つ目は 2.25 V です。電流が大きいほど内部抵抗での電圧降下が大きく、端子電圧が下がることが分かります。電圧計で測れるのは端子電圧であって起電力そのものではない、という点がこの問題の背景にあります。' }
    ],
    faq: [
      ['電池につないだまま極板間隔を広げると、静電エネルギーが減るのに、外から正の仕事が必要なのはなぜ?', '極板は＋と−で引き合っているので、引き離すには外から正の仕事をする必要があります。一方、容量が減ると電荷の一部が電池に押しもどされ、電池が充電されます。このとき電池が受け取るエネルギー(V×もどった電気量)は、静電エネルギーの減少分の2倍です。外力の仕事と静電エネルギーの減少分の両方が電池に流れこんだ、と考えるとつじつまが合います。'],
      ['平行板の電場を「片方の極板だけなら E/2」と考えてよいのはなぜ?', '広い平面に一様に電荷が分布しているとき、その平面がつくる電場は、平面の両側に同じ強さで、平面からの距離によらない一様な電場になります。＋極板は外向き、−極板は内向きの電場をつくるので、極板の間では2つが同じ向きで足し合わされて E になり、外側では打ち消し合って0になります。だから片方の極板がつくる電場は、極板の間の電場のちょうど半分なのです。']
    ]
  });

  add('p4_mag', {
    secs: [
      { h: 'さらに深く:コイルとコンデンサーの電気振動は「ばね振り子」と同じ', t: '充電したコンデンサーにコイルをつなぐと、電流が行ったり来たりする【電気振動】が起こります。これは、ばねにつけたおもりの単振動とそっくりです。\nしくみを順に見ましょう。①スイッチを入れると、コンデンサーが放電して電流が流れ始めます。しかしコイルは電流の変化を妨げる自己誘導起電力を出すので、電流は急には増えず、ゆっくり増えます。②コンデンサーの電荷が0になったとき、電流は最大です。ここでコイルは「電流を流し続けようとする」ので、電流は止まらず、コンデンサーを逆向きに充電します。③逆向きに満充電されると電流は0になり、こんどは逆向きの放電が始まります。\n対応関係:コンデンサーの電荷 q ↔ ばねの伸び x、電流 i ↔ おもりの速度 v、自己インダクタンス L ↔ 質量 m(変化に逆らう「慣性」)、1/C ↔ ばね定数 k。エネルギーも、静電エネルギー q²/(2C) ↔ 弾性エネルギー kx²/2、コイルのエネルギー Li²/2 ↔ 運動エネルギー mv²/2 と対応し、その和が保存します。\nばね振り子の周期 T＝2π√(m/k) の m を L に、k を 1/C におきかえると、電気振動の周期 【T＝2π√(LC)】 が得られます。角振動数は ω＝1/√(LC) です。\n具体例:L＝0.10 H、C＝4.0 μF、はじめの電圧 10 V なら、ω＝1/√(0.10×4.0×10⁻⁶)≒1.6×10³ rad/s、周期は約 4.0×10⁻³ s。電流の最大値は I₀＝Q₀ω＝4.0×10⁻⁵×1.58×10³≒0.063 A です。これは交流回路の共振周波数 f＝1/(2π√(LC)) と同じ値で、ラジオが特定の放送局を選べるのは、この共振を利用しているからです。', key: 'L は「慣性」、1/C は「ばね定数」。T＝2π√(LC)、エネルギー q²/(2C)＋Li²/2 が保存する。', ex: [{ q: '電気容量 4.0 μF のコンデンサーを 10 V に充電し、自己インダクタンス 0.10 H のコイルにつないで電気振動を起こした。抵抗は無視できる。(1)振動の周期 (2)電流の最大値 (3)コンデンサーの電圧が 5.0 V になった瞬間の電流の大きさ を求めよ。', hint: '(2)(3)はエネルギー保存 (1/2)CV²＋(1/2)LI²＝一定 を使います。', steps: ['(1) T＝2π√(LC)＝2×3.14×√(0.10×4.0×10⁻⁶)＝6.28×√(4.0×10⁻⁷)≒6.28×6.32×10⁻⁴≒4.0×10⁻³ s。', '(2) はじめのエネルギーはすべて静電エネルギーで、(1/2)×4.0×10⁻⁶×10²＝2.0×10⁻⁴ J。電流が最大の瞬間はコンデンサーの電荷が0で、すべてがコイルのエネルギーになる。', '(1/2)×0.10×I₀²＝2.0×10⁻⁴ より I₀²＝4.0×10⁻³、I₀≒6.3×10⁻² A。', '(3) 電圧 5.0 V のとき静電エネルギーは (1/2)×4.0×10⁻⁶×25＝5.0×10⁻⁵ J。残り 1.5×10⁻⁴ J がコイルのエネルギーなので、(1/2)×0.10×I²＝1.5×10⁻⁴、I²＝3.0×10⁻³、I≒5.5×10⁻² A。'], a: '(1)約 4.0×10⁻³ s (2)約 6.3×10⁻² A (3)約 5.5×10⁻² A', check: '(2)は I₀＝Q₀ω＝(4.0×10⁻⁵)×(1/√(4.0×10⁻⁷))≒0.063 A でも求められ一致する。(3)は電圧が半分なので静電エネルギーは 1/4、残り 3/4 がコイルにあり、I＝I₀×√(3/4)≒0.866I₀ になる。単振動で「変位が振幅の半分のとき、速さは最大の √3/2 倍」と同じ関係。' }] },
      { h: '実戦演習:磁場の中で回転する導体棒', t: '一端を軸にして磁場の中で導体棒を回転させる問題は、「棒の場所によって速さがちがう」ことにどう対処するかがポイントです。\n戦略:①起電力は「単位時間に棒が横切る磁束」で求めるのが最も確実です。長さ l の棒が角速度 ω で回ると、1秒間に扇形の面積 (1/2)l²ω を掃くので、【V＝(1/2)Bωl²】。②別の見方として、棒の各点の速さは軸からの距離 r に比例して rω なので、V＝vBl の v に「平均の速さ」lω/2 を使っても同じ結果になります。③電流が流れると、棒は磁場から力を受け、回転を妨げます(レンツの法則)。一定の角速度で回し続けるには、外から力のモーメントを加え続ける必要があります。④エネルギー保存:外力の仕事率＝抵抗の消費電力 で検算します。\n落とし穴は、V＝vBl の v に棒の先端の速さ lω をそのまま使ってしまい、答えを2倍にしてしまうことです。また、電磁力は棒の各点に一様にはたらくので、その合力は棒の【中点】にはたらくと考えて、力のモーメントを計算します。', key: '回転する棒の起電力は (1/2)Bωl²(掃く面積の速さ×B)。電磁力の合力は棒の中点にかかる。仕事率のつり合いで検算する。', ex: [{ q: '磁束密度 0.20 T の一様な磁場の中で、磁場に垂直な平面内で、長さ 0.50 m の導体棒を一端 O のまわりに角速度 40 rad/s で一定の速さで回転させる。棒の先端は円形の導体レールに接していて、O とレールの間に 2.0 Ω の抵抗がつながれている。棒・レールの抵抗と摩擦は無視する。(1)誘導起電力 (2)流れる電流 (3)棒を一定の角速度で回すのに必要な力のモーメント を求めよ。', hint: '電磁力 BIl の合力は棒の中点(O から l/2)にはたらきます。', steps: ['(1) 棒は1秒間に扇形 (1/2)l²ω の面積を掃くので、V＝(1/2)Bωl²＝(1/2)×0.20×40×0.50²＝1.0 V。', '(2) I＝V/R＝1.0/2.0＝0.50 A。', '(3) 棒が受ける電磁力の大きさは F＝IBl＝0.50×0.20×0.50＝0.050 N で、回転を妨げる向き(レンツの法則)。各点に一様にはたらくので、合力は O から 0.25 m の中点にかかる。', '電磁力のモーメントは 0.050×0.25＝1.25×10⁻² N·m。一定の角速度を保つには、これと同じ大きさの力のモーメントを逆向きに加える。', '検算:外力の仕事率は (モーメント)×ω＝1.25×10⁻²×40＝0.50 W、抵抗の消費電力は I²R＝0.50²×2.0＝0.50 W で一致する。'], a: '(1)1.0 V (2)0.50 A (3)約 1.3×10⁻² N·m(1.25×10⁻² N·m)', check: '仕事率のつり合いが成り立ったので、起電力・電流・モーメントの値に矛盾はない。V＝vBl に先端の速さ 20 m/s を使うと 2.0 V になり、仕事率が4倍ずれて合わないことからも、平均の速さ(中点の速さ)を使う理由が分かる。' }] }
    ],
    drill: [
      { lv: 2, q: '自己インダクタンス 0.50 H のコイルに 4.0 A の電流が流れている。コイルにたくわえられているエネルギーを求めよ。また、電流を 2.0 A に減らすと、エネルギーはいくら減るか。', a: '4.0 J。3.0 J 減る(1.0 J になる)', exp: 'コイルのエネルギーは U＝(1/2)LI² です。(1/2)×0.50×4.0²＝4.0 J。電流を半分の 2.0 A にすると、エネルギーは電流の2乗に比例するので 1/4 の 1.0 J になり、3.0 J 減ります。「電流が半分だからエネルギーも半分」としてしまうのが典型的なまちがいです。減った 3.0 J は、電流を減らす間にコイルに生じる自己誘導起電力が回路に電流を流し続けることで、抵抗のジュール熱などとして外に出ていきます。コンデンサーの (1/2)CV² と同じく、「2乗に比例する」ことを押さえておきましょう。' },
      { lv: 3, q: '起電力 12 V、内部抵抗の無視できる電池に、抵抗 4.0 Ω と自己インダクタンス 0.50 H のコイルを直列につなぎ、スイッチを入れた。(1)スイッチを入れた直後の電流と、電流の増える割合(ΔI/Δt) (2)十分時間がたったあとの電流 (3)そのときコイルにたくわえられているエネルギー を求めよ。', a: '(1)電流 0 A、増える割合 24 A/s (2)3.0 A (3)2.25 J(約 2.3 J)', exp: 'スイッチを入れた直後、コイルは電流の急な変化を妨げるので、電流は0から始まります。このとき抵抗の電圧は0なので、電池の電圧 12 V はすべてコイルにかかり、L ΔI/Δt＝12 V から ΔI/Δt＝12/0.50＝24 A/s です。電流が増えると抵抗の電圧 RI がふえ、コイルにかかる電圧(12−RI)が減るので、電流の増え方はしだいにゆるやかになります。十分時間がたつと電流は一定になり、コイルの電圧は0なので、I＝12/4.0＝3.0 A。コイルのエネルギーは (1/2)×0.50×3.0²＝2.25 J です。「直後のコイルは断線と同じ、十分あとは導線と同じ」と覚えておくと、コンデンサー(直後は導線、十分あとは断線)と対にして整理できます。' },
      { lv: 3, q: '1辺 0.10 m、抵抗 0.010 Ω の正方形の1巻きコイルを、磁束密度 0.50 T の一様な磁場の領域(境界はまっすぐで、磁場はコイル面に垂直)に、一定の速さ 0.20 m/s で、1辺を境界と平行にして入れていく。コイルが完全に入るまでの間について、(1)流れる電流 (2)コイルを一定の速さで動かすのに必要な力 (3)発生するジュール熱 を求めよ。', a: '(1)1.0 A (2)0.050 N (3)5.0×10⁻³ J', exp: 'コイルが入っていく間、磁場の中にある1辺だけが磁場を横切り、起電力 V＝vBl＝0.20×0.50×0.10＝0.010 V が生じます(磁束の増える速さ B×l×v と考えても同じ)。電流は I＝V/R＝0.010/0.010＝1.0 A。磁場の中の辺は電磁力 F＝IBl＝1.0×0.50×0.10＝0.050 N を、進む向きと逆向きに受けるので、一定の速さを保つには同じ大きさの力で引き続ける必要があります。入り終わるまでの時間は 0.10/0.20＝0.50 s なので、ジュール熱は I²Rt＝1.0²×0.010×0.50＝5.0×10⁻³ J。これは外力の仕事 F×(移動距離 0.10 m)＝5.0×10⁻³ J と一致し、外力の仕事がすべて熱になったことが確かめられます。コイル全体が磁場に入ってしまうと磁束が変わらないので、電流は流れなくなります。' }
    ],
    faq: [
      ['コイルのエネルギー (1/2)LI² は、コイルのどこにたまっているの?', 'コイルの導線そのものではなく、電流がつくる【磁場】の中にたまっていると考えます。コンデンサーのエネルギーが極板の間の電場にたまっているのと対になる考え方です。電流を増やすには、自己誘導起電力に逆らって仕事をする必要があり、その仕事が磁場のエネルギーになります。電流を切ると、磁場が消えるときにそのエネルギーが放出され、スイッチで火花が出ることがあります。'],
      ['実際の電気振動が、だんだん小さくなって止まってしまうのはなぜ?', '実際の回路には必ず抵抗があり、電流が流れるたびにジュール熱としてエネルギーが失われるからです。ばね振り子が空気抵抗や摩擦で止まるのと同じで、「減衰振動」とよばれます。さらに、速く振動する電流からは電磁波としてエネルギーが空間に出ていきます。ラジオの送信機は、これを積極的に利用して電波を出しています。振動を続けさせるには、失われる分のエネルギーを外から補う必要があります。']
    ]
  });

  add('p4_atom', {
    secs: [
      { h: 'さらに深く:α崩壊のエネルギーは「軽い方」がほとんど持ち去る', t: '静止していた原子核がα崩壊すると、α粒子と娘核(崩壊後の原子核)が逆向きに飛び出します。崩壊で放出されるエネルギー Q(質量欠損から計算される値)は、2つの運動エネルギーに分けられます。その分け方は、運動量保存で決まります。\nはじめは静止しているので、運動量の和は0です。したがって、α粒子と娘核は【同じ大きさの運動量 p】で逆向きに飛びます。運動エネルギーは K＝p²/(2m) と書けるので、運動量が同じなら、【運動エネルギーは質量に反比例】します。\nα粒子の質量を m、娘核の質量を M とすると、Kα：K娘＝M：m、つまり\n【Kα＝Q×M/(M＋m)】\nです。例えば、ラジウム 226 がラドン 222 とα粒子に崩壊するとき、Q を 4.87 MeV とすると、Kα＝4.87×222/226≒4.78 MeV。エネルギーの約 98% をα粒子が持ち去り、重い娘核は約 0.09 MeV で、ゆっくり反動を受けるだけです。\nこの考え方から、α線のエネルギーが核の種類ごとに【決まった値】になることも分かります。2つの物体に分かれるとき、運動量とエネルギーの保存で分け前が1通りに決まるからです。これに対してβ崩壊では、電子のエネルギーが連続的にばらつきます。この謎から、目に見えない第3の粒子(ニュートリノ)がエネルギーの一部を持ち去っている、という考えが生まれました。', key: '2つに分かれる崩壊では運動量の大きさが等しく、運動エネルギーは質量に反比例。Kα＝Q×M/(M＋m)。', ex: [{ q: '静止していたポロニウム 210 の原子核が、α崩壊して鉛 206 になった。このとき放出されるエネルギーを 5.41 MeV とする。α粒子と鉛の原子核の運動エネルギーをそれぞれ求めよ。質量は質量数に比例するとし、放出されたエネルギーはすべて運動エネルギーになるとする。', hint: '運動量の大きさが等しいので、運動エネルギーの比は質量の逆比 206：4 です。', steps: ['崩壊前は静止しているので、運動量保存より α粒子と鉛の原子核の運動量は大きさが等しく逆向き。', 'K＝p²/(2m) より、運動量が同じなら運動エネルギーは質量に反比例する。Kα：K鉛＝206：4。', 'Kα＝5.41×206/(206＋4)＝5.41×206/210≒5.31 MeV。', 'K鉛＝5.41−5.31≒0.10 MeV(5.41×4/210≒0.103 MeV)。'], a: 'α粒子 約 5.31 MeV、鉛の原子核 約 0.10 MeV', check: '和が 5.41 MeV になる。比 5.31/0.103≒51.5 は質量比 206/4＝51.5 と一致する。全エネルギーの約 98% がα粒子に行くという結論は、ラジウムの例と同じ。' }] },
      { h: '実戦演習:核融合のエネルギーと、生成粒子の運動エネルギー', t: '原子核反応の問題は、①質量欠損から放出エネルギー Q を出す、②運動量保存とエネルギー保存で、生成粒子のエネルギーの分け前を出す、の2段階で組み立てます。\n戦略:①Q＝(反応前の質量の和−反応後の質量の和)×c²。原子質量単位 u で与えられたら、【1 u は約 931 MeV に相当】を使うと計算が楽です。②反応前の運動量の和が0になる設定(静止した核の崩壊や、同じ速さで正面衝突する場合)なら、生成した2粒子は同じ大きさの運動量をもつので、運動エネルギーは質量の逆比に分かれます。③反応前の粒子に運動エネルギーがあれば、それも生成粒子の運動エネルギーの和に加えます。\n落とし穴:質量の差が小さい(0.001 u のオーダー)ので、引き算の桁を落とさないこと。また、「質量数の和」は反応の前後で同じですが、「質量の和」は同じではありません。この差こそがエネルギーの源です。', key: '1 u ≒ 931 MeV。Q は質量の差から、分け前は運動量保存から。運動量の和が0なら運動エネルギーは質量の逆比。', ex: [{ q: '重水素の原子核 ²₁H どうしが反応して、ヘリウム3の原子核 ³₂He と中性子ができる。²₁H＋²₁H → ³₂He＋¹₀n。質量を ²₁H 2.0136 u、³₂He 3.0150 u、中性子 1.0087 u とし、1 u は 931 MeV に相当するとする。(1)この反応で放出されるエネルギーを求めよ。(2)2つの重水素核が同じ速さで正面衝突して反応したとき、中性子とヘリウム3の原子核の運動エネルギーを求めよ。ただし、反応前の運動エネルギーは Q に比べて無視できるとし、質量は質量数に比例するとしてよい。', hint: '(2)では反応前の運動量の和が0です。', steps: ['(1) 反応前の質量の和は 2×2.0136＝4.0272 u、反応後は 3.0150＋1.0087＝4.0237 u。質量欠損は 0.0035 u。', '放出エネルギーは Q＝0.0035×931≒3.26 MeV。', '(2) 同じ速さで正面衝突するので、反応前の運動量の和は0。反応後の中性子と ³He も、同じ大きさの運動量で逆向きに飛ぶ。', '運動エネルギーは質量の逆比に分かれるので、K中性子：K_He＝3：1。', 'K中性子＝3.26×3/4≒2.4 MeV、K_He＝3.26×1/4≒0.82 MeV。'], a: '(1)約 3.3 MeV(3.26 MeV) (2)中性子 約 2.4 MeV、ヘリウム3 約 0.82 MeV', check: '和が 3.26 MeV になることを確認。軽い中性子が 3/4 を持ち去る。核融合炉で中性子のエネルギーを熱として取り出す設計が考えられているのは、エネルギーの多くを中性子が運ぶからである。' }] }
    ],
    drill: [
      { lv: 2, q: '波長 5.0×10⁻⁷ m の光子1個の運動量の大きさを求めよ。(h＝6.6×10⁻³⁴ J·s)', a: '約 1.3×10⁻²⁷ kg·m/s', exp: '光子の運動量は p＝h/λ です。6.6×10⁻³⁴/5.0×10⁻⁷＝1.32×10⁻²⁷ kg·m/s。光子には質量がないのに運動量があるのは、ニュートン力学の p＝mv が光には使えず、エネルギー E と p＝E/c の関係をもつからです。この値はとても小さいですが、光が鏡で反射すると運動量が逆向きになり、鏡は 2p の力積を受けます。太陽の光を大きな帆で受けて進む「ソーラーセイル」は、この光の圧力を利用しています。エネルギー E＝hc/λ と混同しないように、単位(J と kg·m/s)で区別しましょう。' },
      { lv: 3, q: '静止していたラジウム 226 の原子核がα崩壊してラドン 222 になり、α粒子は 4.78 MeV の運動エネルギーをもっていた。ラドンの原子核の運動エネルギーはいくらか。また、この崩壊で放出されたエネルギーの合計を求めよ。質量は質量数に比例するとする。', a: 'ラドン 約 0.086 MeV、合計 約 4.87 MeV', exp: 'はじめ静止しているので、運動量保存によりα粒子とラドンの原子核の運動量は大きさが等しく逆向きです。K＝p²/(2m) より、運動量が等しければ運動エネルギーは質量に反比例するので、K_Rn＝Kα×(4/222)＝4.78×4/222≒0.086 MeV。合計は 4.78＋0.086≒4.87 MeV です。「重い核ほど大きなエネルギーをもらう」と逆に考えないように注意。重い核は運動量は同じでも速さが小さく、運動エネルギーは小さくなります。大砲を撃つと砲身が反動で少し下がるのと同じで、大砲(娘核)はゆっくり、砲弾(α粒子)は速く動きます。' },
      { lv: 3, q: '水素原子で、電子が n＝2 の状態にある。この電子を電離させる(原子から引き離す)のに必要な最小のエネルギーを eV で求め、それを1個の光子で与えるとき、光の波長の最大値を求めよ。(Eₙ＝−13.6/n² eV、h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、1 eV＝1.6×10⁻¹⁹ J)', a: '3.4 eV、約 3.6×10⁻⁷ m', exp: 'n＝2 のエネルギーは E₂＝−13.6/4＝−3.4 eV です。電離した状態(電子が原子核から十分に離れて静止)のエネルギーを0とするので、必要なエネルギーは 0−(−3.4)＝3.4 eV。これを J に直すと 3.4×1.6×10⁻¹⁹≒5.4×10⁻¹⁹ J。光子のエネルギー E＝hc/λ が 3.4 eV 以上なら電離できるので、波長は λ≦hc/E。最大値は 6.6×10⁻³⁴×3.0×10⁸/(5.44×10⁻¹⁹)≒3.6×10⁻⁷ m で、紫外線の領域です。これより波長が長い光は、何個当ててもエネルギーが足りず電離できません(1個の光子がすべて受けわたすため)。光電効果の「限界振動数」と同じ考え方です。' }
    ],
    faq: [
      ['α線のエネルギーはとびとびなのに、β線のエネルギーが連続的なのはなぜ?', 'α崩壊は、娘核とα粒子の「2つ」に分かれるので、運動量とエネルギーの保存から分け前が1通りに決まり、α線のエネルギーは決まった値になります。β崩壊で電子のエネルギーがばらつくのは、電子と娘核のほかに、電荷をもたず検出しにくい【ニュートリノ(反ニュートリノ)】が同時に出て、3つでエネルギーを分け合うからです。3つに分かれると、分け方が1通りに決まりません。'],
      ['核反応で「質量数」は保存するのに、「質量」が保存しないのはなぜ?', '質量数は陽子と中性子の個数の合計なので、核子が生まれたり消えたりしないかぎり保存します。一方、原子核の質量は、核子の質量の和から「結合エネルギーに相当する質量」を引いたものです。反応で核子の結びつき方が変わると結合エネルギーが変わり、その差の分だけ質量が変わります。その差が E＝mc² の関係でエネルギーとして放出されるのです。']
    ]
  });

  /* ===================== 化学 ===================== */
  add('c4_state', {
    secs: [
      { h: 'さらに深く:冷却曲線の読み方 ― 過冷却と、溶液の凝固点が「下がり続ける」理由', t: '凝固点降下の実験では、液体を冷やしながら温度を時間ごとに記録し、【冷却曲線】をかきます。この曲線には2つの「くせ」があり、凝固点を正しく読むにはその理由を知る必要があります。\n①【過冷却】:液体は凝固点に達してもすぐには固まらず、凝固点より低い温度まで液体のまま冷えることがあります。結晶ができ始めるには「核」となる小さな結晶が必要で、それができるまで時間がかかるからです。いったん結晶ができ始めると、凝固熱が一気に出て温度が凝固点近くまで上がります。\n②【溶液では温度が下がり続ける】:純粋な水なら、凝固が始まると全部凍るまで温度は一定です(凝固熱と冷却がつり合う)。ところが溶液では、凍るのは【水だけ】で、溶質は残りの液体に取り残されます。すると液体の質量モル濃度がしだいに大きくなり、凝固点降下度 Δt＝Kf m も大きくなるので、温度はゆっくり下がり続けます。\nそのため、溶液の凝固点は、凝固が始まったあとの「ゆるやかに下がる直線部分」を、過冷却が起こる前の時刻までさかのぼって延長(外挿)した点として読み取ります。過冷却の最低点を凝固点としてはいけません。\n具体例:水 100 g に尿素(分子量 60)0.60 g を溶かすと、m＝0.010 mol/0.100 kg＝0.10 mol/kg で、凝固点は −0.185℃。水の 40% が氷になった時点では、液体の水は 60 g に減り、m＝0.010/0.060≒0.167 mol/kg なので、温度は約 −0.31℃ まで下がっています。', key: '溶液では水だけが凍るので、残った液体が濃くなり温度が下がり続ける。凝固点は過冷却前まで直線を外挿して読む。', ex: [{ q: '水 100 g に尿素(分子量 60)0.60 g を溶かした水溶液を冷やした。(1)この水溶液の凝固点を求めよ。(2)冷却を続けて、はじめの水の 40% が氷になったとき、残った液体の温度は何℃か。(水のモル凝固点降下 Kf＝1.85 K·kg/mol、尿素は電離しない)', hint: '(2)では溶質の量は変わらず、液体の水の質量だけが減ります。', steps: ['(1) 尿素の物質量は 0.60/60＝0.010 mol。質量モル濃度 m＝0.010/0.100＝0.10 mol/kg。', '凝固点降下度は Δt＝1.85×0.10＝0.185 K なので、凝固点は −0.185℃(約 −0.19℃)。', '(2) 氷になるのは水だけで、尿素は液体に残る。液体の水は 100×0.60＝60 g。', '質量モル濃度は 0.010/0.060≒0.167 mol/kg、Δt＝1.85×0.167≒0.31 K。', 'よって液体の温度は約 −0.31℃。'], a: '(1)約 −0.19℃(−0.185℃) (2)約 −0.31℃', check: '水の量が 0.6 倍になったので濃度は 1/0.6≒1.67 倍、Δt も 1.67 倍になる。0.185×1.67≒0.31 で一致。冷却曲線で溶液の温度が右下がりになる理由を数で確かめたことになる。' }] },
      { h: '実戦演習:密閉容器の中の気体の溶解(ヘンリーの法則)', t: '密閉容器の中で、気体の一部が水に溶ける問題は、「気体の物質量」と「溶けた物質量」が両方とも未知の圧力 p で決まる点がむずかしいところです。\n戦略:①溶解平衡に達したときの気体の分圧を p とおきます。②気体として残っている物質量は、状態方程式から n気＝pV/(RT)。③溶けている物質量は、ヘンリーの法則から「(1.0×10⁵ Pa での溶解量)×(p/1.0×10⁵)×(水の体積)」。④n気＋n溶＝(入れた全物質量)という【物質量の保存】の式を立てて p を解きます。\n落とし穴:(a)はじめに入れた気体の圧力でヘンリーの法則を使ってしまう(溶けると圧力が下がるので、平衡時の圧力を使うこと)。(b)容器の容積から水の体積を引き忘れ、気体の体積をまちがえる。(c)条件を変えた(圧縮した、温度を変えた)ときに、溶けている量も変わることを忘れる。ヘンリーの法則は、溶ける気体の「物質量(質量)」が圧力に比例する法則で、溶ける気体の体積をその圧力で測れば一定、という言い方とも区別しましょう。', key: '平衡時の分圧 p を未知数にして、「気体の分＋溶けた分＝全体」の物質量保存の式で解く。', ex: [{ q: '300 K で、圧力 1.0×10⁵ Pa の気体 X は、水 1.0 L に 0.030 mol 溶ける。容積が自由に変えられる密閉容器に水 1.0 L を入れ、気体部分の体積を 2.49 L にして、気体 X を合計 0.26 mol 入れた。温度を 300 K に保つ。(1)溶解平衡に達したときの X の圧力と、水に溶けている X の物質量を求めよ。(2)温度を保ったまま、気体部分の体積を 1.245 L に圧縮した。新しい平衡での X の圧力と、溶けている X の物質量を求めよ。水の蒸気圧と体積変化は無視する。(R＝8.3×10³ Pa·L/(K·mol))', hint: 'n気＝pV/(RT)、n溶＝0.030×(p/1.0×10⁵) とおき、和を 0.26 mol にします。', steps: ['(1) 平衡時の圧力を p〔Pa〕とする。気体として残る物質量は p×2.49/(8.3×10³×300)＝p×1.0×10⁻⁶ mol。', 'ヘンリーの法則より、溶けている物質量は 0.030×p/(1.0×10⁵)＝p×3.0×10⁻⁷ mol(水 1.0 L)。', '和が 0.26 mol なので p×(1.0×10⁻⁶＋3.0×10⁻⁷)＝0.26、p＝2.0×10⁵ Pa。溶けているのは 3.0×10⁻⁷×2.0×10⁵＝0.060 mol。', '(2) 気体部分が 1.245 L なら、気体の物質量は p×5.0×10⁻⁷ mol。溶けた分と合わせて p×(5.0×10⁻⁷＋3.0×10⁻⁷)＝0.26、p＝3.25×10⁵ Pa。', '溶けている物質量は 3.0×10⁻⁷×3.25×10⁵≒0.098 mol。'], a: '(1)2.0×10⁵ Pa、0.060 mol (2)約 3.3×10⁵ Pa、約 0.098 mol', check: '(1)で気体として残るのは 0.20 mol、溶けた 0.060 mol と足して 0.26 mol。(2)では体積を半分にしたのに圧力は 1.625 倍にしかならない。圧縮で気体が水に溶けこみ、気体の物質量が 0.20 mol から 0.1625 mol に減ったからで、ボイルの法則がそのままは使えないことが分かる。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある高分子化合物 1.0 g を水に溶かして 100 mL にした水溶液の浸透圧は、27℃で 249 Pa だった。この高分子化合物の分子量を求めよ。(R＝8.3×10³ Pa·L/(K·mol))', a: '1.0×10⁵', exp: 'ファントホッフの式 ΠV＝nRT に n＝w/M を入れると M＝wRT/(ΠV) です。M＝1.0×8.3×10³×300/(249×0.100)＝2.49×10⁶/24.9＝1.0×10⁵。体積は L 単位(0.100 L)で入れることに注意します(R の単位が Pa·L/(K·mol) だから)。高分子の分子量を測るのに浸透圧が使われるのは、分子量が大きいと物質量が小さく、凝固点降下では 0.0001 K 程度の小さな温度差しか生じず測りにくいのに対し、浸透圧なら数百 Pa(水柱で数 cm)の測りやすい値になるからです。' },
      { lv: 3, q: 'ある気体 1.0 mol を、300 K で容積 0.50 L の容器に入れると、圧力は 4.5×10⁶ Pa だった。この条件での圧縮因子 Z＝pV/(nRT) を求めよ。また、Z の値から、この条件で分子間力と分子の体積のどちらの影響が大きいと考えられるか答えよ。(R＝8.3×10³ Pa·L/(K·mol))', a: 'Z≒0.90。1より小さいので、分子間力(引力)の影響が大きい', exp: '理想気体なら Z＝1 です。Z＝4.5×10⁶×0.50/(1.0×8.3×10³×300)＝2.25×10⁶/2.49×10⁶≒0.90。理想気体として計算した圧力 4.98×10⁶ Pa より、実際の圧力が小さくなっています。分子どうしが引き合うと、壁にぶつかる勢いが弱まり、圧力が理想気体より小さくなるので Z＜1 になります。反対に、さらに高圧にすると分子自身の体積の影響が大きくなり、分子が動ける空間が実際の容積より狭くなるので Z＞1 になります。低温では引力が効きやすく、高温では分子の運動が激しく引力が効きにくい、という傾向もあわせて覚えておきましょう。' },
      { lv: 3, q: '非電解質を溶かした質量モル濃度 0.10 mol/kg の水溶液を冷やしていくと、凝固が始まったあと温度はゆっくり下がり、ある時点で −0.370℃ になった。このとき、はじめの水の何% が氷になっているか。(水のモル凝固点降下 Kf＝1.85 K·kg/mol)', a: '50%', exp: '凝固が進むと、氷になるのは水だけなので、溶質は残った液体に濃縮されます。−0.370℃ での凝固点降下度は 0.370 K なので、そのときの液体の質量モル濃度は 0.370/1.85＝0.20 mol/kg です。溶質の物質量は変わらないので、液体の水の質量は、はじめの 0.10/0.20＝1/2 に減っています。したがって、はじめの水の 50% が氷になっています。溶液の冷却曲線が右下がりになるのはこのためで、「凝固点」とは凝固が始まる温度(冷却曲線を過冷却の前まで外挿した温度)のことです。凍っている途中の温度は、凝固点そのものではない点に注意しましょう。' }
    ],
    faq: [
      ['過冷却の状態の液体に、小さな刺激を与えると一気に凍るのはなぜ?', '過冷却の液体は、凝固点より低い温度なので、本当は固体のほうが安定です。それでも液体のままなのは、結晶の「核」ができていないからです。振動を与えたり、小さな氷のかけらを入れたりすると、そこが核になって結晶が急速に成長します。このとき凝固熱が出るので、温度は凝固点まで上がり、そこからは普通の凝固が続きます。'],
      ['ヘンリーの法則が成り立たない気体があるのはなぜ?', 'ヘンリーの法則は、溶けた気体の分子が水とほとんど反応せず、溶ける量が少ない場合に成り立ちます。アンモニアや塩化水素のように、水に非常によく溶け、水と反応して電離する気体では、溶ける量が圧力に比例しません。二酸化炭素も一部が水と反応しますが、その割合が小さいので、おおむね成り立ちます。法則を使う前に、「溶けにくく、反応しにくい気体か」を確かめましょう。']
    ]
  });

  add('c4_thermo', {
    secs: [
      { h: 'さらに深く:反応が進む向きはエンタルピーとエントロピーで決まる', t: '発熱反応(ΔH＜0)の多くは自然に進みますが、硝酸アンモニウムが水に溶けるように、吸熱なのに自然に進む変化もあります。これを説明するのが【エントロピー S】(乱雑さの程度を表す量)です。\n自然界の変化には、「エネルギーの低い状態へ向かう傾向」と「乱雑な状態へ向かう傾向」の2つがあります。この2つをまとめて判断するのが【ギブズエネルギー変化 ΔG＝ΔH−TΔS】で、【ΔG＜0 なら反応は自然に進む】と判断します(T は絶対温度)。\n4つの場合に分けられます。①ΔH＜0、ΔS＞0:どんな温度でも進む(例:多くの燃焼)。②ΔH＞0、ΔS＜0:どんな温度でも進まない。③ΔH＜0、ΔS＜0:低温で進む(例:水蒸気が凝縮して水になる)。④ΔH＞0、ΔS＞0:高温で進む(例:炭酸カルシウムの熱分解、氷がとける)。\nΔS が正になりやすいのは、気体の物質量がふえる反応、固体や液体が気体になる変化、物質が溶けて散らばる変化です。\n具体例:CaCO₃(固)→CaO(固)＋CO₂(気) は ΔH＝＋178 kJ、ΔS＝＋0.161 kJ/K です。気体が生じるので ΔS＞0。ΔG＝0 となる温度は T＝ΔH/ΔS＝178/0.161≒1106 K(約 830℃)で、これより高温で ΔG＜0 となり分解が進みます。石灰石を焼いて生石灰をつくるのに高温が必要なのは、このためです。\nただし、ΔG＜0 は「進む向き」を示すだけで、「速さ」は示しません。ΔG が大きく負でも、活性化エネルギーが大きければ反応はほとんど進みません(紙は空気中で燃えるほうが安定ですが、火をつけないと燃えない)。', key: 'ΔG＝ΔH−TΔS＜0 なら自然に進む。ΔH と ΔS の符号が同じなら、温度で向きが変わり、境目は T＝ΔH/ΔS。', ex: [{ q: 'CaCO₃(固)→CaO(固)＋CO₂(気) の ΔH を ＋178 kJ、ΔS を ＋0.161 kJ/K とし、どちらも温度によらないとする。(1)25℃(298 K)での ΔG を求め、この温度で分解が自然に進むか答えよ。(2)分解が自然に進むようになる温度は約何℃以上か。', hint: 'ΔG＝ΔH−TΔS に T を入れます。単位を kJ にそろえましょう。', steps: ['(1) ΔG＝178−298×0.161＝178−48.0≒130 kJ。', 'ΔG＞0 なので、25℃では分解は自然には進まない(逆に CaO と CO₂ が反応して CaCO₃ になる向きが自然)。', '(2) 分解が進むのは ΔG＜0、つまり ΔH−TΔS＜0 のとき。T＞ΔH/ΔS＝178/0.161≒1106 K。', 'セルシウス温度に直すと 1106−273≒833℃。約 830℃ 以上で分解が進む。'], a: '(1)約 ＋130 kJ で、自然には進まない (2)約 830℃ 以上', check: '実際に石灰石の工業的な焼成は 900℃ 前後で行われ、計算と大きく矛盾しない。ΔS の単位を J/K のまま(161)使うと桁が千倍ずれるので、kJ と J をそろえたかを必ず確かめる。' }] },
      { h: '実戦演習:溶解と中和を同時に起こす熱量測定', t: '固体の水酸化ナトリウムを塩酸に入れると、「溶解」と「中和」の2つの変化が同時に起こり、両方の熱が出ます。入試では、測定値から片方の反応エンタルピーを求めさせる問題がよく出ます。\n戦略:①発生した熱量を q＝(溶液の質量)×(比熱)×(温度上昇) で求めます。溶液の質量には、溶かした固体の質量も入れます。②その熱量を、反応した物質の物質量で割って 1 mol あたりにします。③ヘスの法則で「全体＝溶解＋中和」と分けます。\n落とし穴:(a)温度上昇は、グラフの最高温度ではなく、温度が下がっていく直線部分を【混合した時刻まで外挿】して読みます。測定中にも熱がまわりに逃げているので、最高温度をそのまま使うと小さめに出ます。(b)酸が過剰な場合、中和するのは NaOH の物質量の分だけです。(c)発熱なので ΔH は負の符号をつけます。', key: '熱量は外挿した温度上昇から。物質量は「少ないほう」で決まる。全体の ΔH を溶解と中和に分けるのはヘスの法則。', ex: [{ q: '1.0 mol/L の塩酸 100 mL に、固体の水酸化ナトリウム 2.0 g を加えてかき混ぜた。温度変化のグラフを外挿して求めた温度上昇は 11.8 K だった。(1)発生した熱量を求めよ。(2)NaOH(固) 1 mol が塩酸と反応するときの反応エンタルピーを求めよ。(3)中和エンタルピーを −56.5 kJ/mol として、NaOH(固) の溶解エンタルピーを求めよ。溶液の密度を 1.0 g/cm³、比熱を 4.2 J/(g·K) とし、熱はすべて溶液の温度上昇に使われたとする。(NaOH＝40)', hint: '溶液の質量は 100＋2.0＝102 g。NaOH は 0.050 mol、HCl は 0.10 mol で酸が過剰です。', steps: ['(1) 溶液の質量は 100 g＋2.0 g＝102 g。q＝102×4.2×11.8≒5.06×10³ J＝5.06 kJ。', '(2) NaOH は 2.0/40＝0.050 mol、HCl は 0.10 mol なので、NaOH がすべて反応する。1 mol あたり 5.06/0.050≒101 kJ の発熱。', '発熱なので、反応エンタルピーは約 −101 kJ/mol。', '(3) NaOH(固)→NaOH aq(溶解)と、NaOH aq＋HCl aq→NaCl aq＋H₂O(中和)の和が全体になる(ヘスの法則)。', '溶解エンタルピー＝−101−(−56.5)≒−45 kJ/mol。'], a: '(1)約 5.1 kJ (2)約 −101 kJ/mol (3)約 −45 kJ/mol', check: 'NaOH の溶解エンタルピーの文献値は約 −44.5 kJ/mol で、計算はこれに近い。最高温度をそのまま使うと温度上昇が小さく読まれ、溶解エンタルピーの大きさを小さく見積もってしまう。' }] }
    ],
    drill: [
      { lv: 2, q: '次の(1)〜(3)の変化について、ΔS(エントロピー変化)の符号を予想し、高温・低温のどちらで自然に進みやすいか答えよ。(1)H₂O(液)→H₂O(気) ΔH＞0 (2)N₂(気)＋3H₂(気)→2NH₃(気) ΔH＜0 (3)2H₂O₂(液)→2H₂O(液)＋O₂(気) ΔH＜0', a: '(1)ΔS＞0、高温で進みやすい (2)ΔS＜0、低温で進みやすい (3)ΔS＞0、どの温度でも進む', exp: '気体の物質量がふえる変化は、乱雑さが増すので ΔS＞0 になりやすいです。(1)液体が気体になるので ΔS＞0。ΔH＞0 でも、T を大きくすると −TΔS が大きな負になり ΔG＜0 になるので、高温ほど進みます(沸点より上で沸騰する)。(2)気体 4 mol が 2 mol に減るので ΔS＜0。ΔH＜0 の効果が勝つ低温で進みやすくなります。アンモニア合成で低温のほうが平衡で有利なのは、ルシャトリエの原理とも一致します(ただし低温では反応が遅いので、実際は触媒を使って 400〜500℃ 程度で行います)。(3)気体が生じて ΔS＞0、しかも発熱なので、温度によらず ΔG＜0 です。' },
      { lv: 3, q: '次の値から、C−H の結合エネルギーを求めよ。C(黒鉛)→C(気) ΔH＝＋717 kJ、H−H の結合エネルギー 436 kJ/mol、メタン CH₄(気) の生成エンタルピー −74.9 kJ/mol。', a: '約 416 kJ/mol', exp: 'メタンをばらばらの原子にする変化 CH₄(気)→C(気)＋4H(気) の ΔH は、C−H 結合4本分の結合エネルギーです。これをヘスの法則で、①CH₄(気)→C(黒鉛)＋2H₂(気)(生成の逆なので ＋74.9 kJ)、②C(黒鉛)→C(気)(＋717 kJ)、③2H₂(気)→4H(気)(＋2×436＝＋872 kJ)の和として求めます。合計は 74.9＋717＋872＝1663.9 kJ なので、C−H 1本あたり 1663.9/4≒416 kJ/mol です。炭素の固体を気体の原子にするエネルギー(昇華エンタルピー)を忘れると、まったくちがう値になります。結合エネルギーは「気体の分子」と「気体の原子」の間で定義されることを思い出しましょう。' },
      { lv: 3, q: '塩化ナトリウムの格子エネルギー(NaCl(固)→Na⁺(気)＋Cl⁻(気) の ΔH)を ＋788 kJ/mol、Na⁺(気) と Cl⁻(気) の水和エンタルピーの和を −784 kJ/mol とする。NaCl の溶解エンタルピーを求めよ。また、その符号にもかかわらず NaCl が水によく溶ける理由を説明せよ。', a: '溶解エンタルピーは ＋4 kJ/mol(吸熱)。溶解でエントロピーが増加し、TΔS の効果で ΔG＜0 になるから', exp: '溶解 NaCl(固)→Na⁺aq＋Cl⁻aq は、「結晶をばらばらのイオンにする(＋788)」と「イオンが水和する(−784)」の2段階に分けられるので、ヘスの法則から ΔH＝788−784＝＋4 kJ/mol です。わずかに吸熱で、実際に食塩を水に溶かすとほんの少し温度が下がります。それでも自然に溶けるのは、規則正しく並んだ結晶のイオンが水の中に散らばることで乱雑さ(エントロピー)が大きく増えるからです。ΔG＝ΔH−TΔS で、ΔH が小さな正の値なら、TΔS の効果で ΔG が負になります。大きな2つの値の差として小さな値が出てくる例で、格子エネルギーと水和エネルギーのつり合いで溶けやすさが決まることが分かります。' }
    ],
    faq: [
      ['エントロピーは「乱雑さ」というけれど、どうやって数で表すの?', 'エントロピーは、物質の状態をとる「場合の数(並び方の数)」の多さと結びついた量で、物質ごとに J/(K·mol) の単位で数値が決まっています。気体は分子が広い空間を自由に動けるので並び方が非常に多く、エントロピーが大きくなります。固体は規則正しく並んでいるので小さくなります。高校では数値の計算は発展的な内容ですが、「気体がふえる、溶けて散らばる→ΔS＞0」という見当がつけられれば十分です。'],
      ['単体の生成エンタルピーを 0 にするとき、O₂ と O₃ のどちらを 0 にするの?', '各元素の【最も安定な単体】(標準状態で)の生成エンタルピーを 0 と決めます。酸素なら O₂、炭素なら黒鉛(ダイヤモンドではない)が基準です。そのため O₃ やダイヤモンドの生成エンタルピーは 0 ではなく正の値になります。例えば C(ダイヤモンド) の生成エンタルピーは約 ＋1.9 kJ/mol で、黒鉛よりわずかにエネルギーが高いことを表しています。基準をそろえておくことで、どの反応の ΔH も同じ表から計算できます。']
    ]
  });

  add('c4_rate', {
    secs: [
      { h: 'さらに深く:一次反応の半減期と、温度で速さが変わるしくみ(アレニウスの式)', t: '反応速度式が v＝k[A] のように濃度の1乗に比例する反応を【一次反応】といいます。過酸化水素の分解や、放射性同位体の崩壊がその例です。\n一次反応には大切な性質があります。濃度が半分になるのにかかる時間(【半減期】)が、はじめの濃度によらず一定なのです。速さは濃度に比例するので、濃度が半分になれば減る速さも半分になり、「残りの半分が減るまでの時間」はいつも同じになります。式で書くと半減期は t½＝0.693/k です。\n例えば過酸化水素が 0.80 mol/L から 0.40 mol/L になるのに 10 分かかったなら、0.20 mol/L になるのにさらに 10 分、0.10 mol/L になるのにさらに 10 分かかります。30 分で 1/8 です。\n次に温度です。反応速度定数 k は温度とともに急に大きくなり、【アレニウスの式 k＝A e^(−Ea/RT)】で表されます。Ea は活性化エネルギー、e^(−Ea/RT) は「活性化エネルギー以上のエネルギーをもつ分子の割合」の目安です。温度が少し上がるだけでこの割合が大きくふえるので、速さが急に大きくなります。\n2つの温度 T₁、T₂ での速度定数の比をとると、ln(k₂/k₁)＝(Ea/R)(1/T₁−1/T₂) となり、測定から活性化エネルギーを求められます。例えば 300 K から 310 K で k が2倍になる反応では、Ea＝R ln2/(1/300−1/310)≒8.31×0.693/(1.075×10⁻⁴)≒5.4×10⁴ J/mol、約 54 kJ/mol です。「10 K 上がると速さが2〜3倍」という経験則は、多くの反応の Ea がこのくらいの大きさであることを表しています。', key: '一次反応の半減期は濃度によらず一定(t½＝0.693/k)。k は温度で指数関数的にふえ、その比から Ea が求まる。', ex: [{ q: '過酸化水素の分解 2H₂O₂→2H₂O＋O₂ は、[H₂O₂] について一次反応である。ある温度で [H₂O₂] が 0.80 mol/L から 0.40 mol/L になるのに 10 分かかった。(1)[H₂O₂] が 0.10 mol/L になるのは、はじめから何分後か。(2)反応速度定数 k を求めよ(ln2＝0.693)。(3)はじめの 30 分間の平均の分解速度を求めよ。', hint: '一次反応では半減期が一定です。', steps: ['(1) 一次反応なので半減期は濃度によらず 10 分で一定。0.80→0.40→0.20→0.10 と半減期3回分で 0.10 mol/L になる。', 'よって 30 分後。', '(2) t½＝0.693/k より k＝0.693/10≒6.9×10⁻² /min。', '(3) 30 分間で [H₂O₂] は 0.80−0.10＝0.70 mol/L 減ったので、平均の分解速度は 0.70/30≒2.3×10⁻² mol/(L·min)。'], a: '(1)30 分後 (2)約 6.9×10⁻² /min (3)約 2.3×10⁻² mol/(L·min)', check: '平均の濃度をつかった近似 v＝k×(平均濃度) でも、最初の 10 分間は 0.40/10＝0.040 mol/(L·min)、平均濃度 0.60 mol/L から k≒0.067 /min と、(2)に近い値が出る。濃度が減るほど速さが小さくなるので、後の区間ほど平均速度が小さいことも確かめられる。' }] },
      { h: '実戦演習:沈殿が先にできるのはどちらか(分別沈殿とモール法)', t: '溶解度積の問題で最も差がつくのは、2種類の沈殿ができうるときに「どちらが先に沈殿するか」「後の沈殿ができ始めたとき、先のイオンはどれだけ残っているか」を問う問題です。\n戦略:①それぞれの沈殿について、【沈殿し始めるのに必要な Ag⁺ などの濃度】を Ksp から計算します。②必要な濃度が小さいほうが先に沈殿します。Ksp の大小だけで比べてはいけません。AgCl(Ag⁺ が1個)と Ag₂CrO₄(Ag⁺ が2個)のように式の形がちがうと、Ksp の単位もちがい、直接比べられないからです。③後の沈殿ができ始める瞬間の Ag⁺ 濃度を、先の沈殿の Ksp に入れて、残っているイオンの濃度を出します。\nこの考え方を使った分析法が【モール法】です。Cl⁻ を含む溶液にクロム酸カリウムを少し加えて硝酸銀で滴定すると、まず白い AgCl が沈殿し、Cl⁻ がほぼなくなったところで赤褐色の Ag₂CrO₄ ができ始めるので、それを終点の目印にします。', key: '「沈殿し始めるのに必要な濃度」で比べる。Ksp の値どうしを直接比べない。2つ目の沈殿が出る瞬間の濃度を1つ目の Ksp に入れる。', ex: [{ q: 'Cl⁻ と CrO₄²⁻ をどちらも 0.010 mol/L 含む水溶液に、硝酸銀水溶液を少しずつ加える(体積変化は無視)。AgCl の Ksp＝1.8×10⁻¹⁰ (mol/L)²、Ag₂CrO₄ の Ksp＝1.1×10⁻¹² (mol/L)³ とする。(1)それぞれの沈殿ができ始めるときの [Ag⁺] を求め、どちらが先に沈殿するか答えよ。(2)Ag₂CrO₄ が沈殿し始めたとき、溶液中の [Cl⁻] はいくらか。また、はじめの Cl⁻ の何% が沈殿しているか。(√1.1＝1.05)', hint: 'AgCl:[Ag⁺][Cl⁻]＝Ksp、Ag₂CrO₄:[Ag⁺]²[CrO₄²⁻]＝Ksp。', steps: ['(1) AgCl が沈殿し始める [Ag⁺] は 1.8×10⁻¹⁰/0.010＝1.8×10⁻⁸ mol/L。', 'Ag₂CrO₄ が沈殿し始める [Ag⁺] は √(1.1×10⁻¹²/0.010)＝√(1.1×10⁻¹⁰)≒1.05×10⁻⁵ mol/L。', '必要な [Ag⁺] が小さい AgCl が先に沈殿する。Ksp は Ag₂CrO₄ のほうが小さいが、それで比べると逆の結論になってしまう。', '(2) Ag₂CrO₄ が沈殿し始めるとき [Ag⁺]＝1.05×10⁻⁵ mol/L。AgCl の Ksp より [Cl⁻]＝1.8×10⁻¹⁰/1.05×10⁻⁵≒1.7×10⁻⁵ mol/L。', '残っている割合は 1.7×10⁻⁵/0.010≒0.17%。よって約 99.8% が沈殿している。'], a: '(1)AgCl 1.8×10⁻⁸ mol/L、Ag₂CrO₄ 約 1.1×10⁻⁵ mol/L で、AgCl が先 (2)約 1.7×10⁻⁵ mol/L、約 99.8%', check: '赤褐色の沈殿が見え始めた時点で Cl⁻ の 99.8% がすでに沈殿しているので、Ag₂CrO₄ の色を滴定の終点の目印に使える(モール法)。Cl⁻ が残りわずかになるまで Ag₂CrO₄ が出ないことが、この方法が成り立つ理由である。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある一次反応で、反応物の濃度が 60 分で 1/8 になった。この反応の半減期は何分か。また、濃度がはじめの 1/32 になるのは何分後か。', a: '半減期 20 分、100 分後', exp: '1/8＝(1/2)³ なので、60 分の間に半減期が3回くり返されたことになり、半減期は 60/3＝20 分です。1/32＝(1/2)⁵ なので、半減期5回分の 100 分後です。一次反応では「半分になる時間」が濃度によらず一定なので、このように半減期の回数で考えられます。「1/8 になるのに 60 分なら、1/32 には 4 倍の 240 分」のように、濃度の減り方を比例で考えるのは誤りです。なお、二次反応(v＝k[A]²)では、濃度が小さくなるほど半減期が長くなるので、このような計算はできません。' },
      { lv: 3, q: '活性化エネルギーが 50 kJ/mol の反応がある。温度を 300 K から 320 K に上げると、反応速度定数は約何倍になるか。アレニウスの式 k＝A e^(−Ea/RT) を使い、A は温度によらないとする。(R＝8.31 J/(mol·K)、e^1.25≒3.5)', a: '約 3.5 倍', exp: '2つの温度での速度定数の比は k₂/k₁＝e^{(Ea/R)(1/T₁−1/T₂)} です。(1/300−1/320)＝20/96000≒2.08×10⁻⁴ /K、Ea/R＝50000/8.31≒6.02×10³ K なので、指数は 6.02×10³×2.08×10⁻⁴≒1.25。よって k₂/k₁＝e^1.25≒3.5 倍です。温度は 300 K から 320 K へ約 7% しか上がっていないのに、速さは 3.5 倍になります。これは、活性化エネルギーをこえるエネルギーをもつ分子の割合が、温度の上昇でとても敏感にふえるからです。活性化エネルギーが大きい反応ほど、指数が大きくなり、温度の影響を強く受けます。' },
      { lv: 3, q: '[Mg²⁺]＝0.010 mol/L の水溶液に、水酸化ナトリウム水溶液を少しずつ加えて pH を上げていく。水酸化マグネシウム Mg(OH)₂ が沈殿し始める pH を求めよ。Mg(OH)₂ の Ksp＝1.0×10⁻¹¹ (mol/L)³、Kw＝1.0×10⁻¹⁴ (mol/L)² とし、体積変化は無視する。', a: 'pH 9.5', exp: '沈殿し始めるのは [Mg²⁺][OH⁻]²＝Ksp となったときです。[OH⁻]²＝1.0×10⁻¹¹/0.010＝1.0×10⁻⁹、[OH⁻]＝√(1.0×10⁻⁹)＝10^(−4.5) mol/L なので pOH＝4.5、pH＝14−4.5＝9.5 です。[OH⁻] が2乗で入ることを忘れて [OH⁻]＝1.0×10⁻⁹ とすると pH 5 となり、酸性で沈殿するという不自然な答えになります。この計算を使うと、金属イオンを pH の調節で分離できます。例えば Fe(OH)₃ のように Ksp がずっと小さい水酸化物は、もっと低い pH で沈殿するので、pH を少しずつ上げると、Fe³⁺ を先に沈殿させて Mg²⁺ と分けることができます。' }
    ],
    faq: [
      ['半減期が濃度によらないのは、どんな反応でも成り立つの?', '成り立つのは一次反応だけです。一次反応では、減る速さが「その時の量」に比例するので、どの時点から見ても半分になるまでの時間が同じになります。二次反応(v＝k[A]² など)では、濃度が小さくなると速さが急に小さくなるので、半減期はしだいに長くなります。放射性同位体の崩壊は一次反応と同じ式に従うので、半減期を使って年代測定ができます。'],
      ['活性化エネルギーが大きい反応ほど、温度の影響を受けやすいのはなぜ?', 'アレニウスの式で、温度の影響は e^(−Ea/RT) の部分に表れます。Ea が大きいと、活性化エネルギーをこえる分子は「エネルギー分布のすそ」のごく一部だけになります。温度が上がると分布が高エネルギー側へ広がり、すその部分が何倍にもふえます。すその奥ほどふえ方の割合が大きいので、Ea が大きい反応ほど、同じ温度上昇で速さが大きく変わるのです。']
    ]
  });

  add('c4_redox', {
    secs: [
      { h: 'さらに深く:同じ金属でも電池になる ― 濃淡電池', t: '電池は「イオン化傾向のちがう2つの金属」でつくる、と習いました。ところが、【同じ金属・同じ種類の水溶液で、濃度だけがちがう】組み合わせでも電池になります。これを【濃淡電池】といいます。\n例えば、2つの容器にそれぞれ銅板を入れ、片方には濃い CuSO₄ 水溶液、もう片方には薄い CuSO₄ 水溶液を入れ、塩橋でつなぎます。どちらが負極になるでしょうか。\n考え方は「濃度の差をなくす向きに変化が進む」です。薄い側では、銅が溶けて Cu²⁺ がふえれば濃度差が小さくなるので、Cu→Cu²⁺＋2e⁻(酸化)が起こり、【薄い側が負極】になります。濃い側では Cu²⁺＋2e⁻→Cu(還元)で Cu²⁺ が減り、濃い側が正極です。\nこれは、イオン化傾向(イオンへのなりやすさ)が金属の種類だけでなく、水溶液のイオン濃度でも変わることを示しています。イオン濃度が小さい溶液の中では、金属はイオンになりやすいのです。水が乾いた所へ蒸発しやすいのと同じで、「少ない所へふえる」向きの変化が自然に進みます。\n放電を続けると、薄い側は濃くなり、濃い側は薄くなります。両方の濃度が等しくなったところで電圧は0になり、電流は止まります。\n具体例:0.10 mol/L と 1.00 mol/L の CuSO₄ 水溶液を 100 mL ずつ使うと、両方が 0.55 mol/L になるまで、薄い側で 0.045 mol の銅が溶け、電子は 0.090 mol 流れます。', key: '濃度の差をなくす向きに反応が進む。薄い側が負極(金属が溶ける)、濃い側が正極(金属が析出する)。濃度が等しくなると止まる。', ex: [{ q: '銅板を 0.10 mol/L の CuSO₄ 水溶液 100 mL に入れたもの(A)と、銅板を 1.00 mol/L の CuSO₄ 水溶液 100 mL に入れたもの(B)を塩橋でつなぎ、導線で銅板どうしを結んだ。(1)負極は A、B のどちらか。(2)電子が 0.020 mol 流れたとき、A、B の Cu²⁺ の濃度はそれぞれいくらか。(3)電流が流れなくなるまでに流れる電子は何 mol か。水の量の変化は無視する。', hint: '濃度差をなくす向きに反応が進みます。電子 2 mol で Cu²⁺ が 1 mol 変化します。', steps: ['(1) 濃度差を小さくする向きに変化が進むので、薄い A で Cu→Cu²⁺＋2e⁻ が起こる。電子を出す A が負極。', '(2) 電子 0.020 mol で、A では Cu²⁺ が 0.010 mol ふえ、B では 0.010 mol 減る。', 'A:0.10×0.100＋0.010＝0.020 mol → 0.20 mol/L。B:1.00×0.100−0.010＝0.090 mol → 0.90 mol/L。', '(3) 両方の濃度が等しくなると電圧が0になる。A で x mol ふえ B で x mol 減るとすると、0.010＋x＝0.100−x、x＝0.045 mol。', '電子は Cu²⁺ の2倍なので 0.090 mol。'], a: '(1)A (2)A 0.20 mol/L、B 0.90 mol/L (3)0.090 mol', check: '(3)のとき両方とも 0.055 mol/0.100 L＝0.55 mol/L で等しい。Cu²⁺ の合計 0.110 mol は最初から最後まで変わらない(一方でふえた分、もう一方で減る)ことも確認できる。' }] },
      { h: '実戦演習:並列につないだ電解槽の電気量の分け前', t: '電解槽を並列につなぐ問題では、全体の電流がそれぞれの電解槽に分かれて流れます。1つの電解槽の生成物の量から、その槽を流れた電気量を逆算し、全体から引いて、もう一方の槽の電気量を出すのが基本の流れです。\n戦略:①全体の電気量 Q＝It から、全体の電子の物質量 Q/F を出す。②生成物の量が分かっている電解槽について、電極反応式から電子の物質量を出す。③残りがもう一方の電解槽の電子の物質量。④それぞれの電極反応式の係数で生成物を計算する。⑤水溶液中のイオン(H⁺ や OH⁻)の増減を、電極反応式から数えて pH の変化を出す。\n落とし穴:(a)並列なのに、両方に同じ電気量が流れたとしてしまう(それは直列)。(b)気体の体積で、陽極と陰極の気体を両方足すのか、片方だけかを読みまちがえる。(c)硫酸銅(Ⅱ)水溶液の電気分解では、陽極で O₂ が出るとき H⁺ が生じて溶液が酸性になることを見落とす。', key: '並列では電子の物質量を「分ける」。片方の生成物から逆算し、全体から引く。H⁺ の増減は電極反応式で数える。', ex: [{ q: '硫酸銅(Ⅱ)水溶液 1.0 L を入れた電解槽 A と、希硫酸を入れた電解槽 B を並列につなぎ、どちらも白金電極を使って、全体で 2.0 A の電流を 9650 秒間流した。A の陰極には銅が 3.2 g 析出した。(1)A と B を流れた電子はそれぞれ何 mol か。(2)B で発生した気体の体積の合計は、標準状態で何 L か。(3)電気分解後の A の水溶液で、増えた H⁺ は何 mol か。(Cu＝64、F＝9.65×10⁴ C/mol、標準状態の気体 1 mol の体積は 22.4 L)', hint: '全体の電子は 2.0×9650/96500＝0.20 mol です。', steps: ['全体の電気量は 2.0×9650＝1.93×10⁴ C で、電子は 1.93×10⁴/9.65×10⁴＝0.20 mol。', '(1) A の陰極:Cu²⁺＋2e⁻→Cu。銅 3.2/64＝0.050 mol なので、A の電子は 0.10 mol。B の電子は 0.20−0.10＝0.10 mol。', '(2) B(希硫酸)の陰極:2H⁺＋2e⁻→H₂ で 0.050 mol、陽極:2H₂O→O₂＋4H⁺＋4e⁻ で 0.025 mol。合計 0.075 mol、体積は 0.075×22.4＝1.68 L。', '(3) A の陽極:2H₂O→O₂＋4H⁺＋4e⁻。電子 0.10 mol に対して H⁺ が 0.10 mol 生じる。陰極では H⁺ は関係しない(Cu²⁺ が還元される)ので、H⁺ は 0.10 mol 増える。'], a: '(1)A 0.10 mol、B 0.10 mol (2)約 1.7 L(1.68 L) (3)0.10 mol', check: 'B 全体では、陰極で H⁺ が 0.10 mol 消費され、陽極で 0.10 mol 生じるので、H⁺ の量は変わらず、実質的に水が電気分解されただけ(H₂：O₂＝2：1)。A では Cu²⁺ が H⁺ に入れかわり、[H⁺] が 0.10 mol/L ふえて酸性が強くなる。' }] }
    ],
    drill: [
      { lv: 2, q: '0.050 mol/L のシュウ酸 (COOH)₂ 水溶液 10.0 mL を硫酸で酸性にし、濃度不明の過マンガン酸カリウム水溶液で滴定すると、8.0 mL で終点になった。過マンガン酸カリウム水溶液の濃度を求めよ。', a: '0.025 mol/L', exp: '過マンガン酸イオンは MnO₄⁻＋8H⁺＋5e⁻→Mn²⁺＋4H₂O で電子を5個受け取り、シュウ酸は (COOH)₂→2CO₂＋2H⁺＋2e⁻ で電子を2個出します。終点では「受け取った電子＝出した電子」なので、5×c×(8.0/1000)＝2×0.050×(10.0/1000)。右辺は 1.0×10⁻³ mol なので、c＝1.0×10⁻³/(5×8.0×10⁻³)＝0.025 mol/L です。物質量の比 MnO₄⁻：(COOH)₂＝2：5 を使っても同じです。過マンガン酸カリウムは自身が赤紫色で、還元されるとほぼ無色の Mn²⁺ になるので、赤紫色が消えなくなった点が終点になり、指示薬がいりません。硫酸で酸性にするのは、塩酸だと Cl⁻ が酸化されてしまい、硝酸だと硝酸自身が酸化剤としてはたらくからです。' },
      { lv: 3, q: '水素 1.0 mol を燃料電池で反応させ、平均 1.0 V の電圧で電気エネルギーを取り出した。得られた電気エネルギーは、水素の燃焼エンタルピー(−286 kJ/mol、液体の水が生じる)の何% にあたるか。(F＝9.65×10⁴ C/mol)', a: '約 67%', exp: '水素は H₂→2H⁺＋2e⁻ で、1 mol あたり電子 2 mol を出します。流れた電気量は 2×9.65×10⁴＝1.93×10⁵ C。電気エネルギーは「電気量×電圧」なので 1.93×10⁵×1.0＝1.93×10⁵ J＝193 kJ です。燃焼で出る熱 286 kJ と比べると 193/286≒0.67、約 67% です。火力発電は、燃料の熱で水蒸気をつくりタービンを回すので、熱機関としての効率の上限(熱力学第二法則)があり、40% 前後にとどまります。燃料電池は化学エネルギーを直接電気エネルギーに変えるので、熱機関の制約を受けず、高い効率が期待できます。電圧が高いほど効率がよくなる(理論上の上限は約 1.23 V)ことも、式から分かります。' },
      { lv: 3, q: '濃度不明の過酸化水素水 10.0 mL を硫酸で酸性にし、過剰のヨウ化カリウム水溶液を加えると、ヨウ素が遊離した。このヨウ素を、デンプンを指示薬として 0.10 mol/L のチオ硫酸ナトリウム Na₂S₂O₃ 水溶液で滴定すると、20.0 mL で終点になった。過酸化水素水のモル濃度を求めよ。(I₂＋2S₂O₃²⁻→2I⁻＋S₄O₆²⁻)', a: '0.10 mol/L', exp: '反応は2段階です。①H₂O₂＋2I⁻＋2H⁺→I₂＋2H₂O(H₂O₂ 1 mol から I₂ 1 mol)、②I₂＋2S₂O₃²⁻→2I⁻＋S₄O₆²⁻(I₂ 1 mol とチオ硫酸イオン 2 mol)。チオ硫酸イオンは 0.10×20.0/1000＝2.0×10⁻³ mol なので、I₂ は 1.0×10⁻³ mol、H₂O₂ も 1.0×10⁻³ mol。濃度は 1.0×10⁻³/(10.0/1000)＝0.10 mol/L です。このように、測りたい酸化剤で I⁻ を酸化して I₂ をつくり、その I₂ を滴定する方法を【ヨウ素滴定】といいます。ヨウ化カリウムを過剰に加えるのは、酸化剤を残さず反応させるためです。終点では、デンプンによる青紫色が消えます。' }
    ],
    faq: [
      ['濃淡電池の電圧は、ふつうの電池に比べて大きいの?', 'ふつうはとても小さく、濃度が10倍ちがっても、2価の銅イオンでは約 0.03 V 程度です。ダニエル電池(約 1.1 V)のように金属の種類がちがう電池に比べると、ずっと小さな電圧です。しかし、この原理は大切で、例えば神経細胞の膜電位は、細胞の内外のイオンの濃度差から生じる電位で、濃淡電池と同じ考え方で説明できます。pH メーターも、H⁺ の濃度差で生じる電位を測っています。'],
      ['電池の電圧は、金属板を大きくすると高くなるの?', '高くなりません。電池の電圧(起電力)は、使う物質の組み合わせとイオンの濃度、温度で決まり、金属板の大きさにはよりません。金属板を大きくしたり水溶液を多くしたりすると、取り出せる電流の大きさや、取り出せる電気量の合計(容量)が大きくなります。電圧を上げたいときは、電池を直列につなぎます。乾電池の単1と単3の電圧が同じ 1.5 V なのもこのためです。']
    ]
  });

  add('c4_inorg', {
    secs: [
      { h: 'さらに深く:錯イオンの形と名前は「配位数」で決まる', t: '金属イオンに、非共有電子対をもつ分子や陰イオン(【配位子】)が配位結合したものが【錯イオン】です。結合している配位子の数を【配位数】といい、配位数によって錯イオンの形がほぼ決まります。\n・配位数2:【直線形】 例:[Ag(NH₃)₂]⁺(ジアンミン銀(Ⅰ)イオン、無色)\n・配位数4:【正四面体形】 例:[Zn(NH₃)₄]²⁺(テトラアンミン亜鉛(Ⅱ)イオン、無色)/ 【正方形】 例:[Cu(NH₃)₄]²⁺(テトラアンミン銅(Ⅱ)イオン、深青色)\n・配位数6:【正八面体形】 例:[Fe(CN)₆]³⁻(ヘキサシアニド鉄(Ⅲ)酸イオン)、[Fe(CN)₆]⁴⁻(ヘキサシアニド鉄(Ⅱ)酸イオン)\n名前のつけ方は、「配位子の数(ジ2・テトラ4・ヘキサ6)＋配位子名(NH₃ はアンミン、CN⁻ はシアニド、OH⁻ はヒドロキシド、H₂O はアクア)＋金属名(酸化数)」で、錯イオン全体が陰イオンなら最後に「酸イオン」をつけます。\n錯イオンの電荷は「金属イオンの電荷＋配位子の電荷の和」です。[Fe(CN)₆]³⁻ なら、鉄の酸化数を x として x＋6×(−1)＝−3 から x＝＋3 と分かります。\n配位子が2種類あると、形のちがいから【異性体】が生じることがあります。正八面体の [CoCl₂(NH₃)₄]⁺ では、2つの Cl⁻ がとなり合う(シス形)か、向かい合う(トランス形)かで2種類の異性体があり、色もちがいます。このように、錯イオンは「形」をもつ立体的な粒子として考えると、性質がよく理解できます。', key: '配位数2は直線、4は正四面体か正方形、6は正八面体。名前は「数＋配位子＋金属(酸化数)」、陰イオンなら「〜酸イオン」。', ex: [{ q: '次の錯イオンについて、(1)中心の金属の酸化数 (2)配位数と形 (3)名前 を答えよ。(a)[Fe(CN)₆]³⁻ (b)[Zn(OH)₄]²⁻ (c)[Ag(NH₃)₂]⁺', hint: '配位子の電荷は CN⁻ と OH⁻ が −1、NH₃ は 0 です。', steps: ['(a) x＋6×(−1)＝−3 より x＝＋3。配位数6で正八面体形。全体が陰イオンなので「酸イオン」をつけ、ヘキサシアニド鉄(Ⅲ)酸イオン。', '(b) x＋4×(−1)＝−2 より x＝＋2。配位数4で正四面体形。テトラヒドロキシド亜鉛(Ⅱ)酸イオン。水酸化亜鉛が過剰の水酸化ナトリウム水溶液に溶けるときにできる。', '(c) x＋2×0＝＋1 より x＝＋1。配位数2で直線形。陽イオンなので「酸」はつけず、ジアンミン銀(Ⅰ)イオン。', '共通する考え方:電荷の和から酸化数、配位子の数から形、全体の電荷の符号から名前の語尾を決める。'], a: '(a)＋3、6・正八面体形、ヘキサシアニド鉄(Ⅲ)酸イオン (b)＋2、4・正四面体形、テトラヒドロキシド亜鉛(Ⅱ)酸イオン (c)＋1、2・直線形、ジアンミン銀(Ⅰ)イオン', check: '(c)は、AgCl の沈殿がアンモニア水に溶ける反応 AgCl＋2NH₃→[Ag(NH₃)₂]⁺＋Cl⁻ で生じる。電荷の和を左右で確かめると 0＝＋1−1 で合う。' }] },
      { h: '実戦演習:混合物の組成を、加熱と滴定で決める', t: '炭酸ナトリウムと炭酸水素ナトリウム、水酸化ナトリウムと炭酸ナトリウムのような混合物の組成を決める問題は、無機化学と量計算をつなぐ入試の定番です。\n戦略1(加熱):炭酸水素ナトリウムは加熱すると 2NaHCO₃→Na₂CO₃＋H₂O＋CO₂ と分解しますが、炭酸ナトリウムは分解しません。【減った質量＝出ていった H₂O と CO₂ の質量】で、NaHCO₃ 2 mol(168 g)あたり 62 g 減ります。この「1組あたりの減少量」を使うと、一気に NaHCO₃ の量が出ます。\n戦略2(二段滴定):NaOH と Na₂CO₃ の混合水溶液を塩酸で滴定すると、フェノールフタレインの変色(第1終点)までに「NaOH の中和」と「Na₂CO₃→NaHCO₃」が、メチルオレンジの変色(第2終点)までに「NaHCO₃→CO₂」が起こります。第1終点から第2終点までの滴下量が Na₂CO₃ の物質量に対応する、というのが鍵です。\n落とし穴:減少した質量を CO₂ だけだと思ってしまう(H₂O も出ていく)、二段滴定で第2段階の量を NaOH にあててしまう、などです。', key: '加熱では「NaHCO₃ 2 mol で 62 g 減る」。二段滴定では「第1→第2終点の量＝Na₂CO₃ の量」。', ex: [{ q: '炭酸ナトリウムと炭酸水素ナトリウムの混合物 10.0 g を、質量が変わらなくなるまで十分に加熱したところ、質量は 8.45 g になった。(1)混合物中の炭酸水素ナトリウムの質量を求めよ。(2)加熱で発生した二酸化炭素の体積は、標準状態で何 L か。(H＝1.0、C＝12、O＝16、Na＝23、標準状態の気体 1 mol は 22.4 L)', hint: '2NaHCO₃→Na₂CO₃＋H₂O＋CO₂。出ていくのは H₂O と CO₂ の両方です。', steps: ['分解するのは NaHCO₃ だけ。2NaHCO₃(2×84＝168 g)から H₂O(18 g)と CO₂(44 g)、合わせて 62 g が出ていく。', '減った質量は 10.0−8.45＝1.55 g。これは 1.55/62＝0.025 組分の反応にあたる。', '(1) NaHCO₃ はその2倍の 0.050 mol で、質量は 0.050×84＝4.2 g。', '(2) CO₂ は 1組につき 1 mol なので 0.025 mol。体積は 0.025×22.4＝0.56 L。'], a: '(1)4.2 g (2)0.56 L', check: '炭酸ナトリウムは 10.0−4.2＝5.8 g。加熱後の Na₂CO₃ は 5.8＋0.025×106＝5.8＋2.65＝8.45 g となり、問題の値と一致する。' }] }
    ],
    drill: [
      { lv: 2, q: '次のイオンを含む水溶液に、アンモニア水を少量加えると沈殿ができ、さらに過剰に加えると沈殿が溶けるものをすべて選べ。また、溶けたときにできる錯イオンの化学式を答えよ。Al³⁺、Fe³⁺、Cu²⁺、Zn²⁺、Ag⁺', a: 'Cu²⁺:[Cu(NH₃)₄]²⁺、Zn²⁺:[Zn(NH₃)₄]²⁺、Ag⁺:[Ag(NH₃)₂]⁺', exp: 'アンモニア水を少量加えると、どのイオンも水酸化物(Ag⁺ は酸化物 Ag₂O)の沈殿をつくります。過剰に加えたとき溶けるのは、NH₃ と安定な錯イオン(アンミン錯イオン)をつくる Cu²⁺(深青色の溶液)、Zn²⁺(無色)、Ag⁺(無色)です。Al(OH)₃ と Fe(OH)₃ はアンモニア水には溶けません。水酸化ナトリウム水溶液を過剰に加えた場合は話が別で、両性の Al(OH)₃ と Zn(OH)₂ が溶けて [Al(OH)₄]⁻、[Zn(OH)₄]²⁻ になります。Zn²⁺ はどちらの試薬でも溶けるので、Al³⁺ と Zn²⁺ を分けるにはアンモニア水を、Zn²⁺ と Cu²⁺ を分けるには水酸化ナトリウム水溶液を使う、のように使い分けます。' },
      { lv: 3, q: '水酸化ナトリウムと炭酸ナトリウムの混合水溶液 20.0 mL を、0.10 mol/L の塩酸で滴定した。フェノールフタレインを指示薬にすると 30.0 mL で変色し、続けてメチルオレンジを加えて滴定すると、さらに 10.0 mL で変色した。水酸化ナトリウムと炭酸ナトリウムのモル濃度をそれぞれ求めよ。', a: 'NaOH 0.10 mol/L、Na₂CO₃ 0.050 mol/L', exp: '第1終点(フェノールフタレイン、pH 約8)までに起こるのは、NaOH＋HCl→NaCl＋H₂O と Na₂CO₃＋HCl→NaHCO₃＋NaCl の2つ。第2終点(メチルオレンジ、pH 約4)までに起こるのは NaHCO₃＋HCl→NaCl＋H₂O＋CO₂ だけです。第2段階の 10.0 mL は NaHCO₃、つまりもとの Na₂CO₃ の物質量に対応するので、Na₂CO₃＝0.10×10.0/1000＝1.0×10⁻³ mol。第1段階の 30.0 mL のうち 10.0 mL は Na₂CO₃→NaHCO₃ に使われたので、NaOH に使われたのは 20.0 mL で、NaOH＝2.0×10⁻³ mol です。20.0 mL 中の量なので、NaOH は 0.10 mol/L、Na₂CO₃ は 0.050 mol/L。Na₂CO₃ は2段階で合計2倍の HCl を使う点に注意しましょう。' },
      { lv: 3, q: 'アルミニウムは、酸化アルミニウムを氷晶石とともに融解し、電気分解(溶融塩電解)してつくる。アルミニウム 54 kg をつくるのに必要な電気量を求めよ。また、1.0×10⁵ A の電流を流すと、何秒かかるか。(Al＝27、F＝9.65×10⁴ C/mol)', a: '電気量 約 5.8×10⁸ C、時間 約 5.8×10³ 秒(約1.6時間)', exp: '陰極では Al³⁺＋3e⁻→Al の反応が起こり、Al 1 mol をつくるのに電子 3 mol が必要です。Al 54 kg は 54000/27＝2000 mol なので、電子は 6000 mol、電気量は 6000×9.65×10⁴≒5.79×10⁸ C です。時間は Q＝It より t＝5.79×10⁸/1.0×10⁵≒5.8×10³ 秒。アルミニウムは「電気の缶詰」とよばれるほど製造に大量の電気を使うので、使用済みの缶をリサイクルすると、新しくつくるより大幅にエネルギーを節約できます。水溶液を電気分解しないのは、Al³⁺ よりも水のほうが還元されやすく、陰極で水素が発生してしまうからです。氷晶石を加えるのは、酸化アルミニウムの融点(約 2000℃)を下げるためです。' }
    ],
    faq: [
      ['アンモニア水を過剰に加えると、溶ける水酸化物と溶けない水酸化物があるのはなぜ?', '溶けるかどうかは、金属イオンがアンモニア分子と安定な錯イオンをつくれるかどうかで決まります。Cu²⁺・Zn²⁺・Ag⁺ などはアンモニアの窒素原子の非共有電子対を強く受け入れ、アンミン錯イオンになって溶けます。Al³⁺ や Fe³⁺ はアンモニアより水酸化物イオンや水との結びつきのほうが強く、アンミン錯イオンをつくりにくいので、沈殿のまま残ります。この差が、金属イオンの分離に利用されています。'],
      ['炭酸ナトリウムと炭酸水素ナトリウムを見分けるには、どうすればよい?', 'いくつかの方法があります。①加熱する:炭酸水素ナトリウムは分解して二酸化炭素を出し、石灰水を白くにごらせますが、炭酸ナトリウムは分解しません。②水溶液にフェノールフタレインを加える:炭酸ナトリウムは強めの塩基性で濃い赤色、炭酸水素ナトリウムは弱い塩基性でうすい赤色です。③水への溶けやすさ:炭酸水素ナトリウムのほうが溶けにくい。ベーキングパウダーに炭酸水素ナトリウムが使われるのは、加熱で CO₂ を出す性質を利用しています。']
    ]
  });

  add('c4_org', {
    secs: [
      { h: 'さらに深く:二重結合への付加の向きと、二重結合を切って位置を決める方法', t: '非対称なアルケンに HBr や H₂O を付加させると、2種類の生成物が考えられます。例えばプロペン CH₂＝CH−CH₃ に HBr を付加させると、1-ブロモプロパンと 2-ブロモプロパンが考えられますが、実際に主に生じるのは 2-ブロモプロパンです。\nこの傾向を【マルコフニコフ則】といいます。「二重結合の炭素のうち、もともと H を多くもつほうに H が付加しやすい」という経験則です。理由は、反応の途中で生じる正の電荷をもつ炭素(炭素陽イオン)が、多くの炭素に囲まれているほど安定だからです。H⁺ が CH₂ 側につくと、正電荷はまん中の炭素(炭素2つに囲まれる)にでき、こちらのほうが安定なので、この道すじが優先されます。プロペンに水を付加させると、同じ理由で主に 2-プロパノールができます。\n次に、二重結合の【位置】を決める方法です。アルケンにオゾンを反応させてから分解する(オゾン分解)と、二重結合が切れて、両側の炭素がそれぞれ C＝O になります。例えば 2-メチル-2-ブテン (CH₃)₂C＝CH−CH₃ では、(CH₃)₂C＝O(アセトン)と O＝CH−CH₃(アセトアルデヒド)ができます。生成物を見れば、二重結合がどこにあったかを逆にたどれます。硫酸酸性の過マンガン酸カリウムで酸化しても二重結合が切れますが、この場合は H のついた側の C がさらに酸化されて、アルデヒドではなくカルボン酸(または CO₂)になる点がちがいます。\n生成物の C＝O の炭素どうしを「＝」でつなぎ直すと、もとのアルケンにもどる、と考えると、構造決定の問題が解きやすくなります。', key: '付加は「H の多いほうに H」(マルコフニコフ則)。オゾン分解の生成物の C＝O どうしをつなぎ直すと、もとのアルケンが分かる。', ex: [{ q: '分子式 C₅H₁₀ のアルケン A をオゾン分解すると、アセトン CH₃COCH₃ とアセトアルデヒド CH₃CHO が得られた。(1)A の構造式(示性式)と名前を答えよ。(2)A に臭化水素を付加させたときに主に生じる化合物の名前を答えよ。', hint: '2つの生成物の C＝O の炭素を「＝」でつなぎ直します。', steps: ['オゾン分解では、二重結合の両側の炭素がそれぞれ C＝O になる。逆に、生成物の C＝O の O を取り、炭素どうしを＝でつなげばもとのアルケンになる。', 'アセトンの (CH₃)₂C と、アセトアルデヒドの CH−CH₃ をつなぐと (CH₃)₂C＝CH−CH₃。炭素は 3＋2＝5 個で C₅H₁₀ と一致する。', '(1) A は 2-メチル-2-ブテン。', '(2) 二重結合の炭素のうち、H を1個もつ CH 側に H が、H をもたない C(CH₃)₂ 側に Br が付加しやすい(マルコフニコフ則)。', '主に生じるのは (CH₃)₂CBr−CH₂−CH₃、つまり 2-ブロモ-2-メチルブタン。'], a: '(1)(CH₃)₂C＝CH−CH₃、2-メチル-2-ブテン (2)2-ブロモ-2-メチルブタン', check: '逆向きに付加した 2-ブロモ-3-メチルブタンも少しは生じうるが、主生成物ではない。分子式は C₅H₁₁Br で、HBr が1分子付加したことと合う。' }] },
      { h: '実戦演習:エステルの構造決定 ― 加水分解生成物から逆にたどる', t: 'エステルの構造決定は、加水分解でできるカルボン酸とアルコールを、それぞれ別の手がかりで決めていく問題です。\n戦略:①分子式から不飽和度を出し、エステル結合(C＝O が1つ)以外に二重結合や環があるかを確かめます。②カルボン酸の手がかり:銀鏡反応を示すならギ酸 HCOOH(カルボン酸なのにホルミル基をもつ)。③アルコールの手がかり:酸化してケトンになるなら第二級、酸化されにくいなら第三級、アルデヒドを経てカルボン酸になるなら第一級。ヨードホルム反応を示すなら CH₃CH(OH)− の構造をもつ。不斉炭素原子をもつかどうかも手がかりになります。④両方を組み合わせて、炭素数の合計が分子式と合うかを確かめます。\n落とし穴は、「銀鏡反応を示すのはアルデヒドだけ」と思いこんでギ酸を見落とすこと、ヨードホルム反応を示すアルコール(エタノール・2-プロパノールなど)と示さないアルコールの区別があいまいなことです。', key: '銀鏡反応＋カルボン酸ならギ酸。酸化でケトンなら第二級アルコール。炭素数の合計で最後に確かめる。', ex: [{ q: '分子式 C₅H₁₀O₂ のエステル A を加水分解すると、カルボン酸 B とアルコール C が得られた。B は銀鏡反応を示した。C を二クロム酸カリウムの硫酸酸性溶液で酸化するとケトンが得られ、また C は不斉炭素原子をもっていた。(1)A の示性式を答えよ。(2)A 5.1 g を完全に加水分解(けん化)するのに必要な水酸化ナトリウムは何 g か。(H＝1.0、C＝12、O＝16、Na＝23)', hint: '銀鏡反応を示すカルボン酸はギ酸。残りの炭素は4個です。', steps: ['不飽和度は (2×5＋2−10)/2＝1 で、エステルの C＝O だけ。鎖状で、ほかに二重結合はない。', 'B は銀鏡反応を示すカルボン酸なので、ギ酸 HCOOH(炭素1個)。よって C は炭素4個の飽和1価アルコール C₄H₉OH。', 'C₄H₉OH の異性体のうち、酸化でケトンになる第二級アルコールは 2-ブタノール CH₃CH(OH)CH₂CH₃ だけで、これは不斉炭素原子(OH のついた C)をもつ。条件に合う。', '(1) A は HCOOCH(CH₃)CH₂CH₃(ギ酸 sec-ブチル)。', '(2) A の分子量は 102 で、5.1 g は 0.050 mol。エステル 1 mol に NaOH 1 mol が反応するので、NaOH は 0.050×40＝2.0 g。'], a: '(1)HCOOCH(CH₃)CH₂CH₃ (2)2.0 g', check: 'C の 2-ブタノールは CH₃CH(OH)− の構造をもつので、ヨードホルム反応も示すはずである。もし問題にその情報があれば、さらに確かめに使える。ほかの C₄H₉OH(1-ブタノール、2-メチル-1-プロパノール、2-メチル-2-プロパノール)はどれも酸化でケトンにならない。' }, { q: '分子式 C₆H₁₂ の化合物 D は臭素水を脱色した。D をオゾン分解すると、アセトンだけが得られた。D の示性式を答えよ。', hint: 'アセトン2分子の C＝O をつなぎ直します。', steps: ['臭素水を脱色するので C＝C をもつ(C₆H₁₂ はシクロアルカンの可能性もあるが、それなら脱色しない)。', 'オゾン分解で同じ化合物だけが生じるので、二重結合の左右が同じ形(対称)である。', 'アセトン (CH₃)₂C＝O 2分子の C＝O の炭素どうしをつなぐと (CH₃)₂C＝C(CH₃)₂。', '炭素数は 3＋3＝6、水素は 12 で、分子式と一致する。'], a: '(CH₃)₂C＝C(CH₃)₂(2,3-ジメチル-2-ブテン)', check: 'この化合物は二重結合の炭素に H がないので、硫酸酸性の過マンガン酸カリウムで酸化しても、やはりアセトンだけが生じ、カルボン酸はできない。シス-トランス異性体ももたない(片方の炭素に同じ CH₃ が2つ)。' }] }
    ],
    drill: [
      { lv: 2, q: 'プロペン CH₂＝CH−CH₃ に、(1)臭化水素 (2)水(酸触媒) を付加させたとき、主に生じる化合物の名前をそれぞれ答えよ。', a: '(1)2-ブロモプロパン (2)2-プロパノール', exp: 'マルコフニコフ則により、二重結合の炭素のうち H を多くもつ CH₂ 側に H が、H の少ない CH 側に Br や OH が付加しやすくなります。(1)は CH₃−CHBr−CH₃(2-ブロモプロパン)、(2)は CH₃−CH(OH)−CH₃(2-プロパノール)です。逆向きに付加すると 1-ブロモプロパン、1-プロパノールになりますが、これらは少量しかできません。2-プロパノールは第二級アルコールなので、酸化するとアセトン(ケトン)になります。また CH₃CH(OH)− の構造をもつので、ヨードホルム反応を示します。工業的には、プロペンへの水の付加で 2-プロパノールがつくられています。' },
      { lv: 3, q: '分子式 C₅H₁₀ で表されるアルケンは何種類あるか。シス-トランス異性体も区別して数えよ。', a: '6 種類', exp: '炭素骨格で分けて数えます。①直鎖(C−C−C−C−C):二重結合の位置で 1-ペンテンと 2-ペンテンの2種類。2-ペンテンにはシス形とトランス形があるので、計3種類。②枝分かれ(C−C(C)−C−C):2-メチル-1-ブテン、2-メチル-2-ブテン、3-メチル-1-ブテンの3種類。これらは、二重結合の片方の炭素に同じ原子(団)が2つついているので、シス-トランス異性体はありません。③C(C)₂−C(ネオペンタン型):中心の炭素が4つの炭素と結合していて、二重結合をつくれないので0種類。合計 3＋3＝6 種類です。なお、分子式 C₅H₁₀ にはシクロペンタンなどのシクロアルカンもありますが、問題は「アルケン」なので数えません。' },
      { lv: 3, q: 'オレイン酸 C₁₇H₃₃COOH(C＝C を1つもつ)だけからなる油脂(トリオレイン、分子量 884)について、(1)けん化価(油脂 1 g をけん化するのに必要な KOH の mg 数) (2)ヨウ素価(油脂 100 g に付加するヨウ素 I₂ の g 数) を求めよ。(KOH＝56、I₂＝254)', a: '(1)約 190 (2)約 86', exp: '油脂は、グリセリン1分子に脂肪酸3分子がエステル結合したものです。(1)けん化では、エステル結合1つに KOH 1 つが反応するので、油脂 1 mol に KOH 3 mol が必要です。1 g は 1/884 mol なので、KOH は 3×56/884 g≒0.190 g＝190 mg。けん化価は約 190 です。(2)オレイン酸は C＝C を1つもつので、油脂1分子には C＝C が3つあり、I₂ が3分子付加します。100 g は 100/884 mol なので、I₂ は 3×254×100/884≒86 g。ヨウ素価は約 86 です。けん化価が大きいほど分子量が小さい油脂、ヨウ素価が大きいほど C＝C が多い(不飽和度が大きい)油脂と判断できます。ヨウ素価の大きい油は空気中で固まりやすく(乾性油)、ペンキなどに使われます。' }
    ],
    faq: [
      ['マルコフニコフ則の「炭素陽イオンが安定」とは、どういう意味?', 'H⁺ がつくと、二重結合のもう一方の炭素は電子が足りなくなり、正の電荷を帯びます。まわりに炭素(アルキル基)が多く結合していると、それらが電子を少しずつ押し出して正電荷をやわらげるので、安定になります。安定な中間体ができる道すじほど、活性化エネルギーが小さく、反応が速く進みます。そのため、多くの炭素に囲まれた炭素に正電荷ができる向き、つまり H の多い炭素に H がつく向きに反応が進みます。'],
      ['ケトンがアルデヒドとちがって酸化されにくいのはなぜ?', 'アルデヒド R−CHO は、C＝O の炭素に H がついているので、その H の位置に O が入ってカルボン酸 R−COOH になれます。ケトン R−CO−R′ の C＝O の炭素には H がなく、両側が炭素なので、これ以上酸化するには C−C 結合を切る必要があり、ふつうの条件では起こりません。そのため、ケトンは銀鏡反応やフェーリング液の還元を示さず、アルデヒドと見分けることができます。']
    ]
  });

  add('c4_poly', {
    secs: [
      { h: 'さらに深く:イオン交換樹脂で「イオンを入れかえる」量を数える', t: '【イオン交換樹脂】は、スチレンとジビニルベンゼンの共重合体(立体網目状の高分子)に、イオンを交換できる官能基をつけたものです。\n【陽イオン交換樹脂】:スルホ基 −SO₃H をもちます。水溶液を通すと、溶液中の陽イオンが樹脂の H⁺ と入れかわります。例:R−SO₃H＋Na⁺→R−SO₃Na＋H⁺。\n【陰イオン交換樹脂】:−N⁺(CH₃)₃OH⁻ のような基をもち、溶液中の陰イオンが樹脂の OH⁻ と入れかわります。例:R−N⁺(CH₃)₃OH⁻＋Cl⁻→R−N⁺(CH₃)₃Cl⁻＋OH⁻。\n両方に続けて通すと、陽イオンは H⁺ に、陰イオンは OH⁻ に置きかわり、H⁺＋OH⁻→H₂O となるので、イオンをほとんど含まない【脱イオン水】が得られます。\n量の関係で大切なのは、【電荷の量で交換する】ことです。Na⁺ 1 個は H⁺ 1 個と、Ca²⁺ 1 個は H⁺ 2 個と入れかわります。したがって、陽イオン交換樹脂から流れ出る H⁺ の物質量は、(陽イオンの物質量×価数)の合計になります。流出液を NaOH 水溶液で滴定すれば、もとの陽イオンの量が求められます。\nまた、交換反応は平衡なので、使い終わった樹脂に濃い塩酸を流すと逆向きに反応が進み、H⁺ 型にもどせます(【再生】)。この性質を使うと、樹脂をくり返し使えます。', key: '交換は「電荷の量」で起こる。Ca²⁺ 1 mol は H⁺ 2 mol を押し出す。濃い酸で逆反応させると再生できる。', ex: [{ q: '0.10 mol/L の塩化カルシウム水溶液 10.0 mL を、十分な量の H⁺ 型の陽イオン交換樹脂に通し、樹脂を純水でよく洗って、流出液と洗液をすべて集めた。(1)この液に含まれる H⁺ は何 mol か。(2)この液を 0.10 mol/L の水酸化ナトリウム水溶液で中和するには、何 mL 必要か。', hint: 'Ca²⁺ 1 個が H⁺ 2 個と入れかわります。', steps: ['CaCl₂ は 0.10×10.0/1000＝1.0×10⁻³ mol。Ca²⁺ も 1.0×10⁻³ mol。', '2R−SO₃H＋Ca²⁺→(R−SO₃)₂Ca＋2H⁺ のように、Ca²⁺ 1 mol で H⁺ 2 mol が出る。', '(1) H⁺ は 2.0×10⁻³ mol(流出液は塩酸 HCl になっている)。', '(2) NaOH の体積を v〔mL〕とすると、0.10×v/1000＝2.0×10⁻³、v＝20 mL。'], a: '(1)2.0×10⁻³ mol (2)20 mL', check: 'Cl⁻ は交換されずに通りぬけるので、流出液は HCl 2.0×10⁻³ mol を含む。もとの Cl⁻ も 2.0×10⁻³ mol(CaCl₂ 1 mol に Cl⁻ 2 mol)で、陽イオンと陰イオンの電荷の量が一致していることからも確かめられる。' }] },
      { h: '実戦演習:アミノ酸の電離平衡から等電点を計算する', t: 'アミノ酸は水溶液中で、pH によって陽イオン・双性イオン・陰イオンの割合が変わります。グリシンで書くと、\n陽イオン H₃N⁺−CH₂−COOH ⇄ 双性イオン H₃N⁺−CH₂−COO⁻ ⇄ 陰イオン H₂N−CH₂−COO⁻\nの2段階の電離平衡で、それぞれの電離定数を K₁、K₂ とします。\n戦略:①1段目の平衡から [陽イオン]/[双性イオン]＝[H⁺]/K₁、2段目から [陰イオン]/[双性イオン]＝K₂/[H⁺]。この2つの比の式が出発点です。②【等電点】は全体の電荷の平均が0になる pH で、[陽イオン]＝[陰イオン] の条件から [H⁺]/K₁＝K₂/[H⁺]、つまり [H⁺]²＝K₁K₂、pH＝(pK₁＋pK₂)/2 です。③電気泳動では、等電点より酸性側(pH が小さい)では陽イオンが多く陰極へ、塩基性側では陰イオンが多く陽極へ移動します。\n落とし穴:pH＝pK₁ のとき「陽イオンだけ」と考えてしまうこと。実際には陽イオンと双性イオンが 1：1 です。また、等電点でも陽イオンや陰イオンが0になるわけではなく、両者が同じ量だけ存在して電荷が打ち消し合っている点に注意しましょう。', key: '比 [陽]/[双]＝[H⁺]/K₁、[陰]/[双]＝K₂/[H⁺]。等電点は [陽]＝[陰] から pH＝(pK₁＋pK₂)/2。', ex: [{ q: 'グリシンの電離定数を pK₁＝2.4(陽イオン⇄双性イオン)、pK₂＝9.6(双性イオン⇄陰イオン)とする。(1)グリシンの等電点を求めよ。(2)pH 3.4 の水溶液中で、陽イオンと双性イオンの物質量の比を求めよ(陰イオンは無視できる)。(3)pH 3.4 と pH 9.6 の緩衝液中で電気泳動を行うと、グリシンはそれぞれ陽極・陰極のどちらへ移動するか。', hint: '[陽イオン]/[双性イオン]＝[H⁺]/K₁＝10^(pK₁−pH)。', steps: ['(1) 等電点では [陽イオン]＝[陰イオン]。[H⁺]/K₁＝K₂/[H⁺] より [H⁺]²＝K₁K₂、pH＝(2.4＋9.6)/2＝6.0。', '(2) [陽イオン]/[双性イオン]＝[H⁺]/K₁＝10^(−3.4)/10^(−2.4)＝10^(−1)＝0.10。', 'よって 陽イオン：双性イオン＝1：10。陽イオンは全体の約 1/11(約 9%)。', '(3) pH 3.4 は等電点 6.0 より酸性側で、陽イオンがあるため全体として正に帯電しており、陰極へ移動する。', 'pH 9.6(＝pK₂)では双性イオン：陰イオン＝1：1 で、全体として負に帯電しているので、陽極へ移動する。'], a: '(1)6.0 (2)陽イオン：双性イオン＝1：10 (3)pH 3.4 では陰極、pH 9.6 では陽極', check: 'pH 6.0 では [陽]/[双]＝10^(−3.6)、[陰]/[双]＝10^(−3.6) で等しく、どちらも双性イオンの約 0.025% しかない。等電点ではほとんどが双性イオンで、電気泳動で動かないことが数でも確かめられる。' }] }
    ],
    drill: [
      { lv: 2, q: '次の高分子を、熱可塑性樹脂と熱硬化性樹脂に分けよ。ポリエチレン、フェノール樹脂、ナイロン66、尿素樹脂、ポリ塩化ビニル、メラミン樹脂', a: '熱可塑性:ポリエチレン、ナイロン66、ポリ塩化ビニル。熱硬化性:フェノール樹脂、尿素樹脂、メラミン樹脂', exp: '【熱可塑性樹脂】は、鎖状の分子が分子間力で集まっているので、加熱すると分子が動けるようになってやわらかくなり、冷やすと固まります。何度でも成形し直せます。付加重合でできるポリエチレン・ポリ塩化ビニルや、縮合重合でできる鎖状のナイロン66・PET がこれにあたります。【熱硬化性樹脂】は、加熱すると分子どうしが共有結合で【立体網目状】につながって固まるので、一度固まると加熱してもやわらかくなりません。フェノール・尿素・メラミンとホルムアルデヒドを付加縮合させた樹脂がこれにあたり、熱や薬品に強いので、電気部品や食器に使われます。「縮合重合なら熱硬化性」とは限らない(ナイロンは縮合重合だが熱可塑性)点に注意しましょう。' },
      { lv: 3, q: 'ε-カプロラクタム(分子量 113)を開環重合させて、ナイロン6をつくる。(1)ε-カプロラクタム 1.13 kg から得られるナイロン6は理論上何 kg か。(2)得られたナイロン6の平均分子量が 2.26×10⁴ のとき、平均重合度はいくらか。', a: '(1)1.13 kg (2)200', exp: '開環重合では、環状の単量体の環が開いて次々につながるだけで、水などの小さな分子は取れません。そのため、生成物の質量は単量体の質量と同じ 1.13 kg です(両端の分は無視できるほど小さい)。くり返し単位 −[NH−(CH₂)₅−CO]− の式量は、単量体と同じ 113 なので、平均重合度は 2.26×10⁴/113＝200 です。同じポリアミドでも、ナイロン66 はアジピン酸とヘキサメチレンジアミンの【縮合重合】で、くり返し単位1つにつき水が2分子取れるので、単量体の質量の和より生成物が軽くなります。重合の種類によって、質量の計算が変わることに注意しましょう。' },
      { lv: 3, q: '交換容量が 1 g あたり 2.0×10⁻³ mol(H⁺ として)の陽イオン交換樹脂 5.0 g がある。この樹脂で、塩化カルシウム水溶液中の Ca²⁺ を完全に交換するとき、交換できる塩化カルシウムは最大何 g か。(CaCl₂＝111)', a: '約 0.56 g(0.555 g)', exp: 'この樹脂がもつ交換できる H⁺ は、2.0×10⁻³×5.0＝1.0×10⁻² mol です。Ca²⁺ は2価なので、1 個の Ca²⁺ が H⁺ 2 個と入れかわります。したがって交換できる Ca²⁺ は 1.0×10⁻²/2＝5.0×10⁻³ mol で、塩化カルシウムも 5.0×10⁻³ mol、質量は 5.0×10⁻³×111≒0.56 g です。もし Na⁺(1価)なら 1.0×10⁻² mol まで交換でき、NaCl なら 0.585 g です。交換容量は「H⁺ の物質量」で表されるので、価数で割るのを忘れないようにしましょう。家庭用の浄水器や、ボイラーの水から Ca²⁺・Mg²⁺(硬度成分)を除くのにも、この原理が使われています。' }
    ],
    faq: [
      ['熱硬化性樹脂は、なぜ一度固まると加熱してもやわらかくならないの?', '熱可塑性樹脂の分子は長い鎖で、鎖どうしは弱い分子間力で集まっているだけなので、加熱すると鎖がすべって動けるようになります。熱硬化性樹脂は、硬化するときに分子どうしが共有結合で立体的な網目をつくるので、全体がひとつの巨大な分子のようになります。加熱しても共有結合は切れにくく、鎖がすべることもできないので、やわらかくなりません。強く加熱すると、とける前に分解して焦げてしまいます。'],
      ['紙おむつに使われる吸水性高分子が、自分の重さの何百倍もの水を吸えるのはなぜ?', '吸水性高分子は、ポリアクリル酸ナトリウムを網目状に橋かけした構造をもちます。水に入れると −COONa が電離して −COO⁻ と Na⁺ になり、網目の中のイオン濃度が高くなるので、浸透圧によって水が網目の中へ入りこみます。さらに −COO⁻ どうしが反発して網目が広がり、より多くの水を保持できます。網目が橋かけされているので溶けてしまうことはなく、水はゲルの中に閉じこめられます。']
    ]
  });

  /* ===================== 生物 ===================== */
  add('b4_cell', {
    secs: [
      { h: 'さらに深く:細胞骨格は「レール」、モータータンパク質は「貨物列車」', t: '細胞骨格は、細胞の形を支えるだけでなく、細胞の中で物を運ぶ【レール】にもなっています。3種類の細胞骨格は、太さと役割がちがいます。\n・【アクチンフィラメント】(直径約 7 nm):細胞膜の内側に多く、細胞の形の変化、アメーバ運動、筋収縮、原形質流動、動物細胞の細胞質分裂(くびれ)にはたらく。\n・【微小管】(直径約 25 nm):チューブリンというタンパク質が管状に集まったもの。紡錘体、繊毛・鞭毛の芯、細胞内の長距離輸送のレールになる。\n・【中間径フィラメント】(直径約 10 nm):とても丈夫な繊維で、細胞や核の形を保つ。輸送にはほとんど使われない。\nレールの上を動くのが【モータータンパク質】で、ATP を分解したエネルギーで形を変え、「足」を一歩ずつ進めるように動きます。アクチンフィラメントの上を動くのが【ミオシン】、微小管の上を動くのが【キネシン】と【ダイニン】です。\n大切なのは、レールに【向き】があることです。微小管には ＋端と −端があり、キネシンはおもに ＋端へ、ダイニンは −端へ向かって動きます。神経細胞の軸索では、微小管の ＋端が軸索の末端側を向いているので、キネシンは細胞体でつくられた神経伝達物質入りの小胞などを末端へ運び、ダイニンは末端で回収したものを細胞体へもどします。\n繊毛や鞭毛が波打つのは、内部に並んだ微小管どうしを、ダイニンがずらそうとするからです。筋収縮でミオシンがアクチンフィラメントをたぐり寄せるのと、しくみがよく似ています。', key: 'レールは向きをもつ。ミオシンはアクチン上、キネシン(＋端へ)とダイニン(−端へ)は微小管上を ATP で動く。', ex: [{ q: '神経細胞の軸索で、細胞体でつくられた小胞は末端へ、末端で取りこまれた物質は細胞体へ運ばれる。軸索の微小管は、＋端を末端側に向けて並んでいる。(1)細胞体から末端への輸送にはたらくモータータンパク質は何か。(2)ダイニンのはたらきだけを止める薬物を与えると、どちらの向きの輸送が止まるか。(3)微小管を壊す薬物を与えると、どうなると考えられるか。', hint: 'キネシンは ＋端へ、ダイニンは −端へ向かいます。', steps: ['微小管の ＋端が末端側、−端が細胞体側を向いている。', '(1) 細胞体から末端へ、つまり ＋端へ向かうのはキネシン。', '(2) ダイニンは −端、つまり細胞体へ向かう輸送を担うので、末端から細胞体への輸送が止まる。キネシンによる末端への輸送は続く。', '(3) 微小管はキネシンとダイニン共通のレールなので、レールがなくなると両方向の輸送が止まる。'], a: '(1)キネシン (2)末端から細胞体への輸送 (3)両方向の輸送が止まる', check: 'モータータンパク質のはたらきには ATP が必要なので、呼吸を止めて ATP をつくれなくしても両方向の輸送が止まるはずである。「どのタンパク質を止めると、どちらの向きが止まるか」は、レールの向きとモーターの進む向きの組み合わせで決まる。' }] },
      { h: '実戦演習:基質濃度と反応速度のデータから、阻害のしかたを見分ける', t: '酵素反応の考察問題では、基質濃度と反応速度の表やグラフから、阻害物質のはたらき方を推理させる問題がよく出ます。\n戦略:①【基質濃度が十分に高いときの速度(最大速度)】を見ます。基質をいくらふやしても最大速度が下がったままなら、はたらける酵素そのものが減った(活性部位以外に結合する非競争的阻害)と考えます。最大速度が元にもどるなら、基質と活性部位を奪い合う競争的阻害です。②【最大速度の半分の速度になる基質濃度】(この値をミカエリス定数 Km といい、小さいほど酵素と基質が結びつきやすい)を比べます。競争的阻害では、同じ速度を出すのにより多くの基質が必要になるので、見かけの Km が大きくなります。\n落とし穴:基質濃度が低い所だけを見ると、どちらの阻害でも速度が下がっていて区別できません。区別できるのは【基質濃度が高い所】です。また、グラフの「頭打ちの高さ」を読むとき、まだ上がり続けている途中の値を最大速度と読みちがえないようにしましょう。', key: '高い基質濃度で速度が元にもどれば競争的、もどらなければ非競争的。見分けどころは「高濃度側」。', ex: [{ q: 'ある酵素について、基質濃度 S〔mmol/L〕と反応速度 v(相対値)を、阻害物質なし・阻害物質 X あり・阻害物質 Y あり の3条件で測定した。\n S＝2 のとき:なし 5.0、X 2.5、Y 2.5\n S＝8 のとき:なし 8.0、X 5.7、Y 4.0\n S＝50 のとき:なし 9.6、X 8.9、Y 4.8\n速度は v＝Vmax×S/(Km＋S) で表されるとする。(1)阻害物質なしでの最大速度 Vmax と Km を求めよ。(2)X、Y はそれぞれ競争的阻害・非競争的阻害のどちらか。(3)X があるときの見かけの Km を求めよ。', hint: 'S＝Km のとき v＝Vmax/2 になります。X と Y の S＝50 の値に注目します。', steps: ['(1) S が大きくなると v は 10 に近づいていく(S＝50 で 9.6)ので Vmax≒10。S＝2 で v＝5.0＝Vmax/2 なので Km＝2 mmol/L。検算:S＝8 なら 10×8/(2＋8)＝8.0 で表と一致。', '(2) X:S＝50 で 8.9 と、阻害なしの値に近づいていく。基質が多いと阻害がうすれるので競争的阻害。', 'Y:S を 2→8→50 とふやしても 2.5→4.0→4.8 で、5 程度で頭打ちになり、最大速度が半分に下がったまま。基質をふやしても回復しないので非競争的阻害。', '(3) X があっても Vmax＝10 のまま。v＝5(Vmax の半分)になる S が見かけの Km。式に S＝8、v＝5.7 を入れると 5.7＝10×8/(Km＋8)、Km＋8≒14、Km≒6 mmol/L。'], a: '(1)Vmax≒10、Km＝2 mmol/L (2)X は競争的阻害、Y は非競争的阻害 (3)約 6 mmol/L', check: 'X で Km＝6 とすると S＝2 では 10×2/8＝2.5、S＝50 では 10×50/56≒8.9 で、表とすべて一致する。Y は Vmax＝5、Km＝2 とすると 2.5、4.0、4.8 と一致し、Km が変わらず Vmax だけが下がる、非競争的阻害の特徴と合う。' }] }
    ],
    drill: [
      { lv: 2, q: '次の(1)〜(4)に最も深くかかわる細胞骨格を、アクチンフィラメント・微小管・中間径フィラメントから選べ。(1)紡錘体 (2)動物細胞の細胞質分裂のくびれ (3)細胞や核の形を丈夫に保つ (4)原形質流動', a: '(1)微小管 (2)アクチンフィラメント (3)中間径フィラメント (4)アクチンフィラメント', exp: '(1)紡錘体は微小管でできていて、染色体を両極へ引き分けます。(2)動物細胞の分裂の終わりに、細胞の赤道部分の内側にアクチンフィラメントとミオシンの輪ができ、これが縮んでくびれます。植物細胞は細胞壁があるのでくびれず、細胞板をつくって仕切ります。(3)中間径フィラメントは引っ張りに強い丈夫な繊維で、皮膚の細胞のケラチンもそのなかまです。(4)オオカナダモの葉などで見られる原形質流動は、ミオシンがアクチンフィラメントの上を動くことで起こります。「細胞骨格」は骨という名前でも固定されたものではなく、つくられたり分解されたりしながらはたらく、動的な構造です。' },
      { lv: 3, q: '細胞をすりつぶした液を遠心分離し、沈殿を取り出しては上ずみをより強い遠心力で遠心分離する操作をくり返した(細胞分画法)。動物細胞の場合、沈殿として得られる順に、核・ミトコンドリア・リボソーム(小胞体の断片をふくむ)を並べよ。また、この操作をふつう低温で、細胞と同じくらいの濃度のスクロース溶液中で行う理由を2つ答えよ。', a: '核→ミトコンドリア→リボソーム(小胞体の断片)。低温にするのは酵素のはたらきを抑えて細胞小器官の分解を防ぐため、等張液を使うのは細胞小器官が吸水して破裂したり脱水したりするのを防ぐため', exp: '遠心分離では、大きく重いものほど弱い遠心力で沈みます。核(直径数 μm)が最初に沈み、次にミトコンドリア(1〜数 μm)、最後にリボソームや小胞体の断片(ミクロソーム)が強い遠心力で沈みます。植物細胞では、核の次に葉緑体が沈み、その後ミトコンドリアが沈みます。低温にするのは、すりつぶした液の中で消化酵素などがはたらいて細胞小器官を分解してしまうのを防ぐためです。また、細胞小器官は膜で包まれているので、水の中では浸透で吸水して破れてしまいます。そのため細胞内と同じ濃度(等張)のスクロース溶液を使います。スクロースは膜を通りにくく、反応もしにくいので適しています。' },
      { lv: 3, q: 'ヒトの赤血球を、0.9% の食塩水(等張液)に入れると形は変わらない。ところが、等張液と同じ質量モル濃度の尿素水溶液に入れると、赤血球はしだいにふくらんで破裂(溶血)した。その理由を説明せよ。', a: '尿素は細胞膜を通りぬけるので、尿素が細胞内に入って内外の尿素の濃度差がなくなり、細胞内の浸透圧が外より高くなって水が流れこむから', exp: '浸透で水が動くのは、膜を【通りにくい】溶質の濃度に差があるときです。食塩水の Na⁺ や Cl⁻ はポンプなどの働きで細胞内外の濃度差が保たれ、実質的に膜を通らないので、等張なら水の出入りはつり合います。尿素は小さく電荷をもたない分子で、細胞膜を比較的通りやすいので、時間がたつと細胞の中にも入ってきます。すると、外の尿素は水を引き出す力にならなくなり、細胞内には尿素に加えて元からのイオンやタンパク質があるので、細胞内のほうが濃くなり、水が流れこんで破裂します。数値の上で同じ濃度(等浸透)でも、生物にとって等張とは限らない、という大切な例です。' }
    ],
    faq: [
      ['キネシンとミオシンは、どちらも「モーター」なのに何がちがうの?', 'どちらも ATP を分解して形を変え、レールの上を進むタンパク質ですが、使うレールがちがいます。ミオシンはアクチンフィラメントの上を動き、筋収縮や原形質流動、細胞質分裂にはたらきます。キネシンは微小管の上をおもに ＋端へ動き、細胞内の小胞や細胞小器官を運びます。ダイニンも微小管の上を動きますが、−端へ向かい、繊毛・鞭毛の運動にもはたらきます。レールと進む向きの組み合わせで、役割が分かれているのです。'],
      ['ミカエリス定数 Km が小さい酵素は、何がよいの?', 'Km は「最大速度の半分の速さになる基質濃度」で、小さいほど、少ない基質でもすぐに酵素と結合して反応が進むことを意味します。つまり、酵素と基質の結びつきやすさ(親和性)の目安です。細胞の中で基質の濃度が低い場合でも、Km の小さい酵素なら十分にはたらけます。同じ反応を受けもつ酵素でも、組織によって Km のちがう種類が使い分けられていることがあり、その組織の役割に合った調節が行われています。']
    ]
  });

  add('b4_meta', {
    secs: [
      { h: 'さらに深く:ルビスコの「まちがい」と、C₄植物・CAM植物の工夫', t: 'カルビン回路で CO₂ を固定する酵素【ルビスコ】(RuBP カルボキシラーゼ/オキシゲナーゼ)は、地球上で最も多いタンパク質といわれます。ところがこの酵素には弱点があり、CO₂ の代わりに【O₂ とも反応してしまう】のです。O₂ と反応すると、せっかくつくった有機物の一部が分解され、CO₂ が放出されます。光のもとでこのように O₂ を使い CO₂ を出す反応を【光呼吸】といい、光合成の効率を下げます。\n光呼吸は、葉の中の CO₂ 濃度が低く、O₂ 濃度が高いほど、また温度が高いほど起こりやすくなります。暑く乾燥した日に、水の蒸発を防ぐために気孔を閉じると、葉の中の CO₂ が減って光呼吸がふえてしまいます。\nこれを解決したのが【C₄植物】(トウモロコシ・サトウキビなど)です。葉肉細胞で、O₂ と反応しない酵素(PEP カルボキシラーゼ)を使って CO₂ を炭素4個の化合物(オキサロ酢酸、さらにリンゴ酸など)として取りこみ、それを維管束鞘細胞へ送ってから CO₂ を放出します。こうして維管束鞘細胞の中の CO₂ 濃度を高め、そこでルビスコをはたらかせるので、光呼吸がほとんど起こりません。「CO₂ のポンプ」をもっているといえます。\n【CAM植物】(サボテン・パイナップル・ベンケイソウなど)は、CO₂ の取りこみを【時間】で分けます。気温が低く水が逃げにくい夜に気孔を開いて CO₂ を C₄化合物として液胞にためこみ、昼は気孔を閉じたまま、ためた CO₂ を放出してカルビン回路を回します。C₄植物は「場所」で、CAM植物は「時間」で、CO₂ の取りこみとカルビン回路を分けているのです。', key: 'ルビスコは O₂ とも反応する(光呼吸)。C₄植物は CO₂ を濃縮する「場所」の分業、CAM植物は夜に取りこむ「時間」の分業。', ex: [{ q: '気温が高く、強い光が当たる乾燥した環境で、イネなどの C₃植物よりトウモロコシなどの C₄植物のほうが光合成速度が大きくなりやすい。その理由を、気孔・CO₂ 濃度・ルビスコの性質にふれて説明せよ。', hint: '乾燥すると気孔を閉じ気味にします。そのとき葉の中で何が起こるでしょう。', steps: ['乾燥した環境では、植物は水の損失を防ぐために気孔を閉じ気味にする。すると葉の中に入る CO₂ が減り、葉の中の CO₂ 濃度が下がる。', 'C₃植物では、ルビスコが CO₂ の代わりに O₂ と反応する光呼吸がふえ、さらに高温ではこの傾向が強まるので、光合成の効率が下がる。', 'C₄植物は、O₂ と反応しない PEP カルボキシラーゼで低い濃度の CO₂ も効率よく取りこみ、維管束鞘細胞で CO₂ を高濃度にしてルビスコにわたす。', 'そのため気孔を閉じ気味にしても光呼吸がほとんど起こらず、強い光を十分に使って光合成を続けられる。'], a: '乾燥で気孔を閉じると葉の中の CO₂ が減り、C₃植物ではルビスコが O₂ と反応する光呼吸がふえて効率が落ちる。C₄植物は CO₂ を C₄化合物として取りこみ、維管束鞘細胞で濃縮してルビスコにわたすので、光呼吸がほとんど起こらず、高温・強光・乾燥下でも光合成速度が大きくなる。', check: '逆に、涼しく光が弱い環境では、CO₂ を濃縮するために余分な ATP を使う C₄植物の利点は小さく、C₃植物のほうが有利なこともある。「どの植物がよいか」は環境で決まる。' }] },
      { h: '実戦演習:呼吸商の測定実験と、呼吸基質の割合', t: '呼吸商(RQ＝放出した CO₂ の体積÷吸収した O₂ の体積)は、発芽種子を入れたフラスコの気体の体積変化から測ります。入試では、装置の読み取りから RQ を出し、さらに呼吸基質の割合まで計算させる問題が出ます。\n戦略:①水酸化カリウム(KOH)水溶液を入れたフラスコでは、出てきた CO₂ がすべて吸収されるので、気体の減少量＝吸収した O₂ の量。②KOH の代わりに水を入れたフラスコでは、減少量＝O₂ の吸収量−CO₂ の放出量。③この2つから CO₂ の放出量を出し、RQ を計算します。④炭水化物(RQ＝1.0)と脂肪(RQ≒0.7)が混ざって使われているときは、それぞれに使われた O₂ を x、y として連立方程式を立てます。\n落とし穴:水のフラスコの減少量を CO₂ の量と思いこむこと。また、温度や気圧の変化による体積の変化を除くため、種子を入れない対照のフラスコを用意する点も、実験の考察でよく問われます。', key: 'KOH ありの減少量＝O₂、水ありの減少量＝O₂−CO₂。混合基質は「O₂ の分け前」を未知数にする。', ex: [{ q: '発芽種子を使って、密閉したフラスコ A(KOH 水溶液を入れた)と B(水を入れた)の気体の体積の減少量を、同じ条件で一定時間測った。(1)種子 X では A が 1.20 mL、B が 0.36 mL 減少した。X の呼吸商を求め、主な呼吸基質を答えよ。(2)種子 Y では A が 2.00 mL、B が 0.30 mL 減少した。Y は炭水化物(呼吸商 1.0)と脂肪(呼吸商 0.70)だけを呼吸基質としているとすると、吸収した O₂ のうち何 mL が炭水化物の分解に使われたか。', hint: 'CO₂ の放出量＝A の減少量−B の減少量。', steps: ['(1) A の減少 1.20 mL が O₂ の吸収量。B の減少 0.36 mL は O₂−CO₂ なので、CO₂ の放出量は 1.20−0.36＝0.84 mL。', 'RQ＝0.84/1.20＝0.70。主な呼吸基質は脂肪。', '(2) O₂ の吸収量は 2.00 mL、CO₂ の放出量は 2.00−0.30＝1.70 mL(RQ＝0.85)。', '炭水化物に使われた O₂ を x、脂肪に使われた O₂ を y とすると、x＋y＝2.00、CO₂ は 1.0x＋0.70y＝1.70。', '2式から 0.30y＝0.30、y＝1.00、x＝1.00。炭水化物の分解に使われた O₂ は 1.00 mL。'], a: '(1)RQ 0.70、脂肪 (2)1.00 mL', check: '(2)で CO₂ は炭水化物から 1.00 mL、脂肪から 0.70 mL、合計 1.70 mL で一致。RQ 0.85 は 1.0 と 0.70 のちょうど中間なので、O₂ を半分ずつ使ったという結論とも合う。' }] }
    ],
    drill: [
      { lv: 2, q: '次の植物を、C₃植物・C₄植物・CAM植物に分けよ。イネ、トウモロコシ、サボテン、コムギ、サトウキビ、パイナップル', a: 'C₃植物:イネ、コムギ。C₄植物:トウモロコシ、サトウキビ。CAM植物:サボテン、パイナップル', exp: 'C₄植物は、熱帯起源で、強い光と高温の環境に適応した植物が多く、トウモロコシ・サトウキビ・ススキなどが代表です。葉の維管束のまわりの維管束鞘細胞に葉緑体がよく発達しているのが特徴です。CAM植物は乾燥地の植物が多く、サボテン・パイナップル・ベンケイソウなどが代表で、夜に気孔を開いて CO₂ をためます。イネやコムギなど多くの植物は、CO₂ をカルビン回路で直接固定する C₃植物で、最初にできる物質が炭素3個の PGA であることからこうよばれます。C₄植物も最終的にはカルビン回路で糖をつくる点は共通で、「CO₂ を最初にどう取りこむか」がちがうだけです。' },
      { lv: 3, q: 'ある植物の葉は、ある強さの光の下で見かけの光合成速度が CO₂ 吸収量で 20 mg/時、暗所での呼吸速度が CO₂ 放出量で 4 mg/時だった(呼吸速度は明暗で変わらないとする)。この光の下に5時間置いたとき、(1)光合成でつくられたグルコースの量 (2)葉に蓄積されたグルコースの量 を求めよ。(CO₂＝44、C₆H₁₂O₆＝180)', a: '(1)約 82 mg (2)約 68 mg', exp: '光合成の反応式は 6CO₂＋12H₂O→C₆H₁₂O₆＋6O₂＋6H₂O で、CO₂ 6×44＝264 mg からグルコース 180 mg ができます。(1)光合成でつくられた量は【真の光合成速度】で考えます。真の光合成速度＝見かけの光合成速度＋呼吸速度＝20＋4＝24 mg/時、5時間で 120 mg の CO₂ が固定されたので、グルコースは 120×180/264≒82 mg。(2)蓄積された量は、呼吸で使った分を引いた【見かけの光合成速度】で考えます。5時間で 100 mg の CO₂ に相当し、グルコースは 100×180/264≒68 mg。「つくった量」と「たまった量」で使う速度がちがう点が、この種の計算の最大のポイントです。' },
      { lv: 3, q: '糸状の緑藻(アオミドロ)に、プリズムで分けた光を当て、好気性の細菌といっしょに顕微鏡で観察すると、細菌は藻の特定の部分に多く集まった。細菌が多く集まったのは、どの色の光が当たった部分か。また、この実験から何が分かるか。', a: '赤色光と青紫色光の当たった部分。光合成にはおもに赤色光と青紫色光が使われる(光合成の作用スペクトル)ことが分かる', exp: 'これはエンゲルマンが行った実験です。好気性細菌は酸素の多い所に集まるので、細菌が集まった部分は、光合成がさかんで酸素が多く発生している部分です。細菌は赤色光と青紫色光の当たった部分に多く集まり、緑色光の部分にはあまり集まりませんでした。これは、クロロフィルが赤色光と青紫色光をよく吸収し、緑色光をあまり吸収しない(だから葉は緑に見える)ことと一致します。光の波長ごとの光合成の効率を表したグラフを【作用スペクトル】、色素が光を吸収する割合を表したグラフを【吸収スペクトル】といい、両者がよく似ていることから、クロロフィルなどの色素が吸収した光が光合成に使われていると分かります。' }
    ],
    faq: [
      ['光呼吸はむだなのに、なぜ植物はルビスコを改良しなかったの?', 'ルビスコが生まれたころの大気には酸素がほとんどなく、CO₂ が豊富だったので、O₂ と反応してしまう弱点は問題になりませんでした。その後、光合成生物がふえて大気中の O₂ がふえ、CO₂ が減ったことで、光呼吸が目立つようになったと考えられています。酵素の基本的なしくみを大きく変えるのはむずかしく、代わりに C₄植物や CAM植物のように、CO₂ を濃縮するしくみが進化しました。光呼吸には、強い光による害を減らすはたらきもあると考えられています。'],
      ['CAM植物は、昼に気孔を閉じているのに、なぜ光合成ができるの?', '夜のうちに取りこんだ CO₂ を、リンゴ酸などの C₄化合物として液胞にためておくからです。昼になると、リンゴ酸から CO₂ を取り出し、気孔を閉じたままカルビン回路で糖をつくります。光のエネルギーは昼にしか得られないので、光化学反応とカルビン回路は昼に行い、CO₂ の取りこみだけを夜にずらしているのです。そのかわり、液胞にためられる量には限りがあるので、成長はおそい傾向があります。']
    ]
  });

  add('b4_gene', {
    secs: [
      { h: 'さらに深く:エンハンサーと転写因子 ― 「どの細胞で」遺伝子をはたらかせるかの決め方', t: '真核生物の遺伝子の転写は、プロモーターだけでは決まりません。遺伝子から遠く離れた場所(数千〜数万塩基対も離れていることがある)に、転写を強める DNA の領域があり、これを【エンハンサー】といいます(弱める領域はサイレンサー)。\nエンハンサーには、特定の【転写調節因子】が結合します。DNA は折れ曲がることができるので、遠くのエンハンサーに結合した調節因子が、ループを作るようにしてプロモーターの近くにある基本転写因子や RNA ポリメラーゼに近づき、転写を促進します。\nどの細胞で遺伝子がはたらくかは、「その細胞にどの転写調節因子があるか」で決まります。例えば、肝臓の細胞には肝臓に特有の調節因子があり、それが結合するエンハンサーをもつ遺伝子だけが肝臓で強く転写されます。1つの遺伝子が複数のエンハンサーをもち、組織ごとに別のエンハンサーが使われることもあります。\nエンハンサーのはたらきを調べるには、【レポーター遺伝子】を使う実験がよく行われます。調べたい DNA 領域を、光る GFP(緑色蛍光タンパク質)などの遺伝子の上流につないで細胞に入れ、どの細胞で光るかを見るのです。領域の一部を削ってから同じ実験をすると、どの部分が必要かが分かります。\nさらに、DNA がヒストンに巻きついたクロマチンの状態も大切です。ぎっしり凝縮した部分では転写にかかわるタンパク質が DNA に近づけないので、遺伝子ははたらきません。分化した細胞では、使わない遺伝子の領域が凝縮していることが多いのです。', key: '遠くのエンハンサーに転写調節因子が結合し、DNA のループでプロモーターにはたらく。どの調節因子をもつかで、細胞ごとの発現が決まる。', ex: [{ q: 'ある遺伝子 G の上流には、領域 E1・E2 とプロモーター P がある。E1・E2・P を GFP 遺伝子の上流につないだ DNA(①)、E1 を除いた DNA(②)、E2 を除いた DNA(③)、E1 と E2 を両方除いた DNA(④)を、それぞれ肝臓の細胞と筋肉の細胞に入れた。結果:①は肝臓・筋肉の両方で光った。②は筋肉だけで光った。③は肝臓だけで光った。④はどちらでも光らなかった。E1 と E2 のはたらきを説明せよ。', hint: '「除くと、どの細胞で光らなくなったか」に注目します。', steps: ['P だけ(④)ではどちらでも光らないので、プロモーターだけでは転写が十分に起こらず、エンハンサーが必要である。', 'E1 を除くと(②)肝臓で光らなくなったので、E1 は肝臓での転写に必要なエンハンサーである。', 'E2 を除くと(③)筋肉で光らなくなったので、E2 は筋肉での転写に必要なエンハンサーである。', '肝臓には E1 に結合する転写調節因子が、筋肉には E2 に結合する転写調節因子があると考えられる。'], a: 'E1 は肝臓で、E2 は筋肉で遺伝子 G の転写を促進するエンハンサーである。それぞれの組織には、対応するエンハンサーに結合する転写調節因子が存在すると考えられる。', check: '細胞にある DNA はどちらも同じでも、使われるエンハンサーがちがう。もし筋肉の細胞に肝臓の調節因子の遺伝子を人工的に入れてはたらかせたら、②でも筋肉で光るはずである、という追加実験で確かめられる。' }] },
      { h: '実戦演習:環状プラスミドの制限酵素地図をつくる', t: '制限酵素で DNA を切断し、電気泳動で断片の長さを調べて、切断部位の位置関係を決める問題です。直線状 DNA の場合に加えて、プラスミドのような【環状 DNA】がよく出ます。\n戦略:①環状 DNA では、切断部位が1か所なら直線状の1本(長さは全体と同じ)、n か所なら【n 本の断片】になります(直線状 DNA なら n＋1 本)。②酵素 A だけ、酵素 B だけ、A と B の両方で切ったときの断片を比べます。両方で切ったときに、ある断片が2つに分かれていたら、その断片の中にもう一方の酵素の切断部位がある、と分かります。③断片の長さの和が、いつも全体の長さと等しいことで検算します。\n落とし穴:環状 DNA を1か所で切ったときに「断片が2本になる」と考えてしまうこと。また、同じ長さの断片が2本できると電気泳動ではバンドが1本に重なって見えるので、バンドの「濃さ」や長さの合計から判断する必要があります。', key: '環状 DNA は切断部位の数＝断片の数。両方の酵素で切ったとき、どの断片が分かれたかで位置を決める。長さの合計で検算。', ex: [{ q: '5000 塩基対の環状プラスミドがある。制限酵素 E だけで切ると 5000 塩基対の断片が1本、制限酵素 B だけで切ると 2000 塩基対と 3000 塩基対の断片ができた。E と B の両方で切ると、2000、1800、1200 塩基対の3本の断片ができた。(1)E と B の切断部位はそれぞれ何か所か。(2)E の切断部位は、どちらの B 断片の中にあり、両側の B の切断部位からそれぞれ何塩基対の位置か。(3)E の切断部位に 1000 塩基対の遺伝子を組みこんだプラスミドを B だけで切ると、どんな長さの断片ができるか。', hint: '環状 DNA では、切断部位の数と断片の数が等しくなります。', steps: ['(1) E だけで1本(全長のまま)なので、E の切断部位は1か所(環が開いて直線になっただけ)。B だけで2本なので、B の切断部位は2か所。', '(2) 両方で切ると、B の 2000 の断片はそのまま残り、3000 の断片が 1800 と 1200 に分かれた。したがって E の切断部位は 3000 の断片の中にある。', 'E の切断部位は、3000 の断片の一方の端(B の切断部位)から 1200 塩基対、もう一方の端から 1800 塩基対の位置。', '(3) E の切断部位に 1000 塩基対が入ると、それをふくむ B 断片が 3000 から 4000 になる。もう一方の B 断片 2000 は変わらない。', 'B だけで切ると 2000 と 4000 塩基対の断片ができる。'], a: '(1)E 1か所、B 2か所 (2)3000 塩基対の B 断片の中で、両端の B 部位からそれぞれ 1200 と 1800 塩基対の位置 (3)2000 と 4000 塩基対', check: '長さの合計は、B だけで 2000＋3000＝5000、両方で 2000＋1800＋1200＝5000、組みこみ後は 2000＋4000＝6000(5000＋1000)となり、すべて合う。組みこみに成功したかを B で切って確かめる、という実際の実験の考え方にもなっている。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある遺伝子の mRNA 前駆体は、5′ 側から エキソン1(300 塩基)・イントロン1(400 塩基)・エキソン2(500 塩基)・イントロン2(200 塩基)・エキソン3(100 塩基) からなる。スプライシング後の mRNA は何塩基か。また、成熟 mRNA の 5′ 末端から数えて 51 番目の塩基から開始コドンが始まり、800 番目の塩基で終止コドンが終わるとすると、翻訳されるポリペプチドは何個のアミノ酸からなるか。', a: 'mRNA は 900 塩基、アミノ酸は 249 個', exp: 'スプライシングではイントロンが取り除かれ、エキソンだけがつながるので、300＋500＋100＝900 塩基です。翻訳される範囲は 51 番目から 800 番目までの 750 塩基で、750/3＝250 コドンです。このうち最後の1つは終止コドンで、対応するアミノ酸がないので、アミノ酸は 250−1＝249 個になります。開始コドン AUG はメチオニンを指定するので、1個目に数えます。mRNA の両端には、翻訳されない部分(非翻訳領域)があることも覚えておきましょう。「mRNA の長さ÷3」をそのままアミノ酸の数にしてしまうのはよくあるまちがいです。' },
      { lv: 3, q: 'mRNA の一部にトリプトファンを指定するコドン UGG がある。このコドンに対応する DNA の1塩基が置換され、mRNA のこのコドンで1塩基だけが変化したとき、翻訳が途中で止まってしまう変化をすべて答えよ。また、そのような突然変異を何というか。(終止コドンは UAA、UAG、UGA)', a: 'UGG→UAG(2番目の G→A)、UGG→UGA(3番目の G→A)。ナンセンス突然変異', exp: '終止コドン UAA・UAG・UGA と UGG を1塩基ずつ比べます。UAG とは2番目だけがちがい(G↔A)、UGA とは3番目だけがちがいます(G↔A)。UAA とは2番目と3番目の2か所がちがうので、1塩基の置換ではなりません。アミノ酸を指定するコドンが終止コドンに変わる置換を【ナンセンス突然変異】といい、ポリペプチドが途中で切れてしまうので、はたらきが大きく損なわれることが多いです。これに対し、別のアミノ酸に変わるものを【ミスセンス突然変異】、同じアミノ酸のまま変わらないもの(遺伝暗号の縮重による)を【同義置換(サイレント突然変異)】といいます。同じ「1塩基の置換」でも、影響の大きさはさまざまです。' },
      { lv: 3, q: 'アンピシリン耐性遺伝子と、lacZ 遺伝子(はたらくと X-gal を分解して青い色素をつくる)をもつプラスミドがある。lacZ の内部にある制限酵素の切断部位に目的の遺伝子を組みこみ、大腸菌に取りこませて、アンピシリンと X-gal を含む寒天培地で培養した。白いコロニーと青いコロニーができた。目的の遺伝子が組みこまれたプラスミドをもつのはどちらか。理由も答えよ。', a: '白いコロニー。目的の遺伝子が lacZ の中に入ると lacZ がはたらかなくなり、X-gal が分解されず青くならないから', exp: 'まず、アンピシリンを含む培地で育つのは、プラスミドを取りこんだ大腸菌だけです(プラスミドのアンピシリン耐性遺伝子のおかげで生きられる)。プラスミドを取りこまなかった大腸菌は死ぬので、コロニーをつくりません。次に、目的の遺伝子が lacZ の内部に入ると、lacZ の遺伝子が分断されて正常な酵素がつくられなくなります。そのため X-gal を分解できず、コロニーは白くなります。目的の遺伝子が入らずに元どおりに閉じたプラスミドをもつ大腸菌では、lacZ がはたらいて青くなります。2段階のふるい分けで、「プラスミドをもち、しかも目的の遺伝子が入ったもの」を選び出すしくみで、【青白選択】とよばれます。' }
    ],
    faq: [
      ['エンハンサーが遺伝子から何万塩基対も離れていてもはたらけるのはなぜ?', 'DNA は長いひものような分子で、折れ曲がってループをつくることができるからです。エンハンサーに結合した転写調節因子は、DNA がループ状に曲がることで、遠く離れたプロモーターの近くに来て、基本転写因子や RNA ポリメラーゼと接触し、転写を促進します。直線距離では遠くても、立体的には近くに来られるのです。エンハンサーは遺伝子の上流だけでなく、下流やイントロンの中にあることもあります。'],
      ['原核生物にはオペロンが多いのに、真核生物ではほとんど見られないのはなぜ?', '原核生物では、関係する複数の遺伝子をひとまとめにして1本の mRNA に転写すれば、同時に必要になる酵素を一度につくれるので効率的です。真核生物では、1本の mRNA からはふつう1種類のタンパク質しか翻訳されず、遺伝子ごとにエンハンサーや転写調節因子の組み合わせで細かく調節しています。この方式なら、同じ遺伝子を組織ごと・時期ごとにちがう組み合わせではたらかせることができ、多細胞生物の複雑な調節に向いています。']
    ]
  });

  add('b4_dev', {
    secs: [
      { h: 'さらに深く:子の形質が「母親の遺伝子型」で決まる ― 母性効果遺伝子', t: 'ふつうの遺伝では、子の形質は子自身の遺伝子型で決まります。ところが、発生の最初の段階を決める遺伝子の中には、子の形質が【母親の遺伝子型】で決まるものがあります。これを【母性効果遺伝子】といいます。\nなぜそうなるのでしょうか。受精卵が卵割を始めたばかりのころは、胚自身の遺伝子はまだあまりはたらかず、母親が卵をつくるときに卵の中に用意しておいた mRNA やタンパク質を使って発生が進みます。ショウジョウバエのビコイドやナノスの mRNA がその代表です。これらの mRNA は、母親の体の中で、母親の遺伝子からつくられて卵に入れられます。だから胚の遺伝子型に関係なく、母親が正常な遺伝子をもっていれば胚は正常に前後の軸をつくり、母親が正常な遺伝子をもたなければ、胚は頭部を欠くなどの異常を示します。\n具体例として、巻貝(ヨーロッパモノアラガイ)の殻の巻く向きがあります。右巻きの対立遺伝子 D が左巻きの d に対して顕性です。この形質は母性効果で決まるので、dd の母親から生まれた子は、子が Dd でもすべて左巻きになります。その Dd の子が自家受精で産んだ子は、遺伝子型が DD：Dd：dd＝1：2：1 に分かれても、母親(Dd)が D をもつので、すべて右巻きになります。\nこのように、母性効果では形質の分離が【1世代遅れて】現れます。核の遺伝子による遺伝なので、母親の遺伝子型さえ分かれば、メンデルの法則で予測できます。ミトコンドリアの DNA などによる細胞質遺伝(母親の細胞質そのものが受け継がれる)とは区別しましょう。', key: '母性効果では、卵に入れられた母親由来の mRNA で初期発生が決まるので、子の形質は母親の遺伝子型で決まる。分離は1世代遅れて現れる。', ex: [{ q: '巻貝の殻の巻く向きは、母性効果遺伝子で決まり、右巻きの D が左巻きの d に対して顕性である。遺伝子型 dd の個体を母親、DD の個体を父親として交配して得た子(F₁)を自家受精させて F₂ を得た。さらに F₂ の各個体を自家受精させて F₃ を得た。(1)F₁ の遺伝子型と殻の向き (2)F₂ の遺伝子型の比と殻の向き (3)F₃ で、左巻きの個体だけを産む F₂ の親は、F₂ 全体のどれだけの割合か。', hint: '殻の向きは、その個体自身ではなく、その個体を産んだ母親の遺伝子型で決まります。', steps: ['(1) F₁ の遺伝子型は Dd。殻の向きは母親 dd で決まるので、すべて左巻き。', '(2) F₁(Dd)の自家受精で、F₂ の遺伝子型は DD：Dd：dd＝1：2：1。殻の向きは母親 F₁(Dd)が D をもつので、すべて右巻き。', '(3) F₃ の殻の向きは、それを産む F₂ の個体の遺伝子型で決まる。dd の F₂ が産む子はすべて左巻き、DD や Dd の F₂ が産む子はすべて右巻き。', 'dd の F₂ は全体の 1/4 なので、左巻きの子だけを産む親は F₂ 全体の 1/4。'], a: '(1)Dd、すべて左巻き (2)DD：Dd：dd＝1：2：1、すべて右巻き (3)1/4', check: 'ふつうの遺伝なら F₂ の時点で右巻き：左巻き＝3：1 に分かれるはずだが、母性効果では F₂ はすべて右巻きで、3：1 の分離は F₃ を産む親ごとの比として1世代遅れて現れる。' }] },
      { h: '実戦演習:三点交雑で遺伝子の並び順と距離を決める', t: '3つの連鎖した遺伝子をまとめて検定交雑すると、子の表現型は8種類に分かれます。この8種類の数から、遺伝子の並び順と距離を一度に決めるのが【三点交雑】の問題です。\n戦略:①いちばん多い2つの表現型が【親型】(乗換えなし)です。②いちばん少ない2つが【二重乗換え型】です。二重乗換えでは、まん中の遺伝子だけが親型と入れかわるので、親型と二重乗換え型を比べて、【入れかわっている遺伝子がまん中】と分かります。③残りの4つは一回乗換え型で、どの区間で乗換えたかに分けます。④各区間の組換え価は、「その区間で乗換えが起きた個体(一回乗換え型＋二重乗換え型)÷全体」で求めます。\n落とし穴:両端の遺伝子だけを見て組換え価を出すと、二重乗換え型は両端が親型の組み合わせにもどって見えるので、組換え価を小さく見積もってしまいます。両端の間の正しい距離は、2つの区間の組換え価の和です。', key: '最多の2つが親型、最少の2つが二重乗換え型。二重乗換え型で入れかわる遺伝子がまん中。区間の組換え価には二重乗換え型も加える。', ex: [{ q: '連鎖している遺伝子 A、B、C について、ABC/abc の個体(A・B・C が同じ染色体上)を abc/abc の個体と検定交雑し、1000 個体の子を得た。表現型と個体数は、[ABC] 395、[abc] 395、[Abc] 45、[aBC] 45、[ABc] 55、[abC] 55、[AbC] 5、[aBc] 5 だった。(1)遺伝子の並び順を答えよ。(2)A−B 間、B−C 間の組換え価を求めよ。(3)A と C だけに注目して組換え価を求めると何% になるか。また、それが(2)の和より小さくなる理由を答えよ。', hint: 'いちばん少ない [AbC] と [aBc] を親型 [ABC]・[abc] と比べます。', steps: ['親型は最多の [ABC] と [abc]。二重乗換え型は最少の [AbC] と [aBc]。親型 [ABC] と比べると、[AbC] は B だけが入れかわっている。', '(1) まん中の遺伝子だけが入れかわるのが二重乗換えなので、B がまん中。並び順は A−B−C。', '(2) A−B 間で乗換えた個体は、[Abc]・[aBC](45＋45)と二重乗換え型(5＋5)で 100 個体。組換え価は 100/1000＝10%。B−C 間は [ABc]・[abC](55＋55)と二重乗換え型 10 で 120 個体、12%。', '(3) A と C の組み合わせが親型と入れかわっているのは [Abc]・[aBC]・[ABc]・[abC] の 200 個体で、20%。', '二重乗換え型 [AbC]・[aBc] は、A と C の組み合わせが親型と同じ(A と C、a と c)にもどって見えるので数えられない。そのため、本当の距離 10＋12＝22 より小さく見える。'], a: '(1)A−B−C (2)A−B 間 10%、B−C 間 12% (3)20%。二重乗換えが起きた個体では A と C の組み合わせが親型にもどって見え、組換えとして数えられないから。', check: '二重乗換えの割合は 10/1000＝1.0% で、2つの区間で独立に乗換えが起こるとしたときの期待値 0.10×0.12＝1.2% に近い(実際には、近くで2回乗換えが起こりにくい「干渉」があり、やや少なくなる)。' }] }
    ],
    drill: [
      { lv: 2, q: 'ショウジョウバエで、ビコイド遺伝子をもたない(bcd/bcd)雌を、正常な雄と交配した。生じる胚はどうなるか。胚の遺伝子型にふれて説明せよ。', a: '胚はすべて頭部や胸部などの前方の構造を欠く。胚の遺伝子型は bcd/＋ で正常な遺伝子をもつが、卵に母親由来のビコイド mRNA が入っていないため', exp: 'ビコイドは母性効果遺伝子で、母親が卵をつくるときに、ビコイド mRNA を卵の前端に局在させます。受精後、これが翻訳されてビコイドタンパク質の濃度勾配ができ、前方の構造をつくる遺伝子を調節します。bcd/bcd の雌がつくる卵には、ビコイド mRNA がありません。胚自身は父親から正常な遺伝子を受け取って bcd/＋ ですが、胚の遺伝子がはたらき始める前に前後軸が決まってしまうので、前方の構造ができません。子の遺伝子型ではなく、母親の遺伝子型で表現型が決まることが、母性効果の特徴です。' },
      { lv: 3, q: '連鎖している遺伝子 P、Q、R について、PQR/pqr の個体を pqr/pqr と検定交雑し、1000 個体を得た。[PQR] 410、[pqr] 410、[Pqr] 40、[pQR] 40、[PQr] 45、[pqR] 45、[PqR] 5、[pQr] 5。並び順と、両端の遺伝子の間の正しい距離(組換え価の和)を求めよ。', a: '並び順は P−Q−R(Q がまん中)。P−Q 間 9%、Q−R 間 10% で、P−R 間は 19%', exp: '最多の [PQR]・[pqr] が親型、最少の [PqR]・[pQr] が二重乗換え型です。[PQR] と [PqR] を比べると Q だけが入れかわっているので、Q がまん中です。P−Q 間で乗換えたのは [Pqr]・[pQR] の 80 個体と、二重乗換え型 10 個体の計 90 個体で 9%。Q−R 間は [PQr]・[pqR] の 90 個体と二重乗換え型 10 個体で 100 個体、10%。両端 P−R の正しい距離は 9＋10＝19% です。P と R の組み合わせだけを見ると、[Pqr]・[pQR]・[PQr]・[pqR] の 170 個体で 17% になり、二重乗換え型の分(2%)だけ小さく見えます。「いちばん大きい組換え価の2つの遺伝子が両端」という考え方だけでなく、二重乗換え型からまん中を決める方法も使えるようにしましょう。' },
      { lv: 3, q: 'イモリの初期原腸胚で、予定表皮域と予定神経域の一部を交換移植すると、移植片はどちらも移植先の予定運命に従って分化した。一方、初期神経胚で同じ交換移植をすると、移植片はもとの予定運命に従って分化した。この結果から分かることを説明せよ。', a: '初期原腸胚のころには、これらの領域の予定運命はまだ決まっておらず(決定していない)、まわりからの影響で変えられる。初期神経胚のころまでに予定運命が決定し、移植しても変わらなくなっている', exp: 'これはシュペーマンらの交換移植実験です。初期原腸胚では、予定表皮域の細胞を予定神経域に移すと神経になり、予定神経域の細胞を予定表皮域に移すと表皮になりました。つまり、この時期の細胞は「どこにいるか」によって運命が変わり、まだ運命が【決定】していません。初期神経胚では、移植片はもとの運命のまま分化したので、この時期までに運命が決定していたことが分かります。原腸胚の時期に、原口背唇部(形成体)から誘導を受けることで、外胚葉の一部が神経に決定されると考えられます。予定運命図(原基分布図)は「そのままなら何になるか」を示すもので、「必ずそうなる」ことを示すものではない点に注意しましょう。' }
    ],
    faq: [
      ['母性効果遺伝子と、ミトコンドリアの遺伝(細胞質遺伝)はどうちがうの?', 'どちらも子の形質が母親で決まるように見えますが、しくみがちがいます。母性効果遺伝子は核の遺伝子で、母親の遺伝子型によって卵に入れられる mRNA などが決まります。子は父親の遺伝子も受け継ぎ、孫の代では父親由来の遺伝子もメンデルの法則どおりに影響します。細胞質遺伝は、ミトコンドリアや葉緑体の DNA が卵の細胞質を通して母親からだけ受け継がれるもので、父親の遺伝子はふつう伝わりません。'],
      ['二重乗換えが、2つの区間の組換え価の積より少なく起こりがちなのはなぜ?', '1か所で乗換えが起こると、そのすぐ近くでは2回目の乗換えが起こりにくくなる性質があるからで、これを【干渉】といいます。染色体の乗換えは、相同染色体が対合したときにつくられる構造の中で起こり、近い場所で何度も起こるようには調節されていないと考えられています。そのため、遺伝子が近いほど、二重乗換えは期待値よりさらに少なくなります。']
    ]
  });

  add('b4_resp', {
    secs: [
      { h: 'さらに深く:単収縮から強縮へ ― 刺激の間隔で筋肉の力が変わるしくみ', t: '筋肉に1回だけ短い刺激を与えると、筋肉は1回だけ収縮してもとにもどります。これを【単収縮】といいます。カエルのふくらはぎの筋肉なら、刺激から収縮が始まるまで(潜伏期)約 0.01 秒、縮んでいく時間(収縮期)約 0.04 秒、ゆるんでいく時間(弛緩期)約 0.05 秒で、全体で約 0.1 秒です。\n刺激の間隔を短くしていくと、何が起こるでしょうか。前の収縮が終わらないうちに次の刺激が来ると、収縮が重なり合って大きくなります(【加重】)。\n・前の収縮の【弛緩期】に次の刺激が来ると、ゆるみきる前にまた縮むので、ぎざぎざした大きな収縮になる。これが【不完全強縮】です。\n・前の収縮の【収縮期】のうちに次の刺激が来るほど間隔が短いと、ゆるむひまがなく、なめらかで単収縮の数倍もの大きな収縮が続く。これが【完全強縮】です。\n強縮で力が大きくなるのは、刺激のたびに筋小胞体から Ca²⁺ が放出され、細胞質の Ca²⁺ 濃度が高いまま保たれるので、アクチンとミオシンの結合が続き、筋肉に十分な張力がたまるからです。私たちがふだん手足を動かすときの収縮は、運動神経から高い頻度で興奮が送られる強縮です。\n強縮を続けると、ATP が大量に必要になります。ところが筋肉にたくわえられている ATP はわずかで、数秒分しかありません。そこで、筋肉にたくさんある【クレアチンリン酸】が、ADP にリン酸を渡してすばやく ATP を再生します(クレアチンリン酸＋ADP→クレアチン＋ATP)。その後、解糖や呼吸で ATP がつくられ、運動の後半や休息中にクレアチンリン酸もつくり直されます。', key: '弛緩期に次の刺激→不完全強縮、収縮期のうちに次の刺激→完全強縮。ATP はクレアチンリン酸ですばやく補われる。', ex: [{ q: 'カエルの神経筋標本で、1回の刺激による単収縮は、潜伏期 0.01 秒・収縮期 0.04 秒・弛緩期 0.05 秒だった。次の間隔で刺激をくり返したとき、どのような収縮が見られるか。(1)0.20 秒ごと (2)0.07 秒ごと (3)0.02 秒ごと', hint: '次の刺激が、前の収縮のどの時期(終わったあと・弛緩期・収縮期)に届くかを考えます。', steps: ['単収縮は刺激から 0.01 秒後に縮み始め、0.05 秒後に最も縮み、0.10 秒後にもとにもどる。', '(1) 0.20 秒ごとなら、前の収縮が 0.10 秒で終わってから次の刺激が来るので、単収縮がくり返されるだけ。', '(2) 0.07 秒ごとなら、次の刺激は前の収縮の弛緩期(0.05〜0.10 秒の間)に来る。ゆるみきる前に次の収縮が重なり、ぎざぎざの不完全強縮になる。', '(3) 0.02 秒ごとなら、前の収縮がまだ縮んでいる途中(収縮期)に次の刺激が来るので、ゆるむ時間がなく、なめらかな完全強縮になる。'], a: '(1)単収縮のくり返し (2)不完全強縮 (3)完全強縮', check: '(3)の刺激頻度は1秒間に 50 回で、カエルの筋肉で完全強縮が起こるといわれる頻度(1秒間に約 30 回以上)と矛盾しない。収縮の高さは (1)＜(2)＜(3) の順に大きくなる。' }] },
      { h: '実戦演習:反射にかかる時間を、伝導・伝達・筋肉の時間に分ける', t: '膝蓋腱反射のような反射では、刺激を受けてから筋肉が縮むまでの時間に、①感覚神経での伝導、②脊髄の中での伝達(シナプス)、③運動神経での伝導、④神経筋接合部での伝達と筋肉が縮み始めるまでの時間、がふくまれます。入試では、刺激する場所を変えたデータから、これらを1つずつ分けて求める問題が出ます。\n戦略:①同じ神経の2点を刺激した時間差を、2点の距離で割ると伝導速度が出ます(距離の差÷時間の差)。②運動神経を筋肉のすぐ近くで刺激した時間から、伝導にかかった分を引くと、「神経筋接合部の伝達＋筋肉の潜伏」の時間が出ます。③全体の時間から、伝導の時間と②の時間を引いた残りが、脊髄の中での時間(シナプスでの伝達など)です。\n落とし穴:1点だけの刺激の時間を距離で割って伝導速度にしてしまうこと(その時間には伝達や筋肉の潜伏の時間がふくまれる)。単位も、mm と ms(ミリ秒)を使うと m/s がそのまま出る(1 mm/ms＝1 m/s)ことを使うと計算が楽になります。', key: '伝導速度は「距離の差÷時間の差」。全体−伝導−(接合部＋筋肉)＝脊髄の中の時間。', ex: [{ q: 'ある動物の反射で、次の測定をした。①運動神経を、筋肉から 0.80 m の点(脊髄から出たところ)で刺激すると 12.0 ミリ秒後に、筋肉から 0.08 m の点で刺激すると 3.0 ミリ秒後に筋肉が収縮し始めた。②感覚神経を、脊髄から 0.60 m の点 P で刺激すると 22.0 ミリ秒後に、脊髄から 0.40 m の点 Q で刺激すると 19.5 ミリ秒後に、反射によって同じ筋肉が収縮し始めた。(1)運動神経と感覚神経の伝導速度 (2)神経筋接合部での伝達と筋肉の潜伏にかかる時間の合計 (3)脊髄の中で興奮が伝わるのにかかる時間 を求めよ。', hint: '(3)は、P を刺激したときの 22.0 ミリ秒を分解します。', steps: ['(1) 運動神経:距離の差 0.80−0.08＝0.72 m を、時間の差 12.0−3.0＝9.0 ミリ秒で伝わるので、0.72/0.0090＝80 m/s。', '感覚神経:距離の差 0.60−0.40＝0.20 m、時間の差 22.0−19.5＝2.5 ミリ秒なので、0.20/0.0025＝80 m/s。', '(2) 筋肉から 0.08 m の点で刺激したとき、伝導にかかる時間は 0.08/80 s＝1.0 ミリ秒。残りの 3.0−1.0＝2.0 ミリ秒が、接合部の伝達と筋肉の潜伏の時間。', '(3) P を刺激したときの 22.0 ミリ秒の内訳は、感覚神経の伝導 0.60/80 s＝7.5 ミリ秒、脊髄の中の時間 x、運動神経の伝導と接合部・筋肉の時間の合計 12.0 ミリ秒(①の最初の測定)。', 'x＝22.0−7.5−12.0＝2.5 ミリ秒。'], a: '(1)どちらも 80 m/s (2)2.0 ミリ秒 (3)2.5 ミリ秒', check: 'Q を刺激した場合でも、0.40/80 s＝5.0 ミリ秒＋2.5＋12.0＝19.5 ミリ秒となり、測定値と一致する。脊髄の中の 2.5 ミリ秒には、シナプスでの伝達(1か所あたり約 0.5〜1 ミリ秒)がふくまれる。' }] }
    ],
    drill: [
      { lv: 2, q: 'フグ毒のテトロドトキシンは、ニューロンの電位依存性ナトリウムチャネルをふさぐ。この毒を作用させたニューロンでは、静止電位と活動電位はそれぞれどうなるか。', a: '静止電位はほぼ変わらないが、活動電位は生じなくなる', exp: '静止電位は、ナトリウムポンプがつくった K⁺ の濃度差と、常に開いているカリウムチャネルを通る K⁺ の流出によって生じます。電位依存性ナトリウムチャネルは静止状態では閉じているので、これをふさいでも静止電位はほぼ変わりません。一方、活動電位は、刺激によって電位依存性ナトリウムチャネルが開き、Na⁺ が細胞内へ一気に流れこむことで生じます。このチャネルがふさがれると Na⁺ が流入できないので、どんなに強い刺激を与えても活動電位は生じず、興奮は伝導しません。フグ毒で手足がしびれたり呼吸が止まったりするのはこのためです。毒や薬物のはたらきから、イオンチャネルの役割を逆にたどる問題はよく出題されます。' },
      { lv: 3, q: '明るい所から暗い所に入ったあと、光を感じる最小の明るさ(閾値)の時間変化を調べると、閾値はまず数分で下がって一度ほぼ一定になり、その後、10 分ごろから再び大きく下がって、30 分ほどでさらに低い値で一定になった。この2段階の変化を、2種類の視細胞にふれて説明せよ。', a: '最初の数分の低下は錐体細胞の感度の上昇によるもので、錐体はすぐに回復するがあまり感度が高くならない。その後の大きな低下は、桿体細胞でロドプシンが再合成されて蓄積し、感度が大きく上がるためで、時間はかかるが錐体よりずっと低い明るさまで感じられるようになる', exp: '暗順応の曲線が2段階になるのは、性質のちがう2種類の視細胞があるからです。錐体細胞は色を感じる細胞で、感度の回復は速いのですが、もともと感度が低いので、閾値はある程度までしか下がりません。桿体細胞は、明るい所では視物質のロドプシンが分解されて感度が低くなっていますが、暗い所でロドプシンが再合成されて蓄積すると、非常に高い感度をもつようになります。この回復には時間がかかるので、2段階目の低下は遅れて始まります。暗い所で色が分かりにくいのは、はたらいているのが主に桿体細胞だからです。ロドプシンの合成にはビタミン A が必要で、不足すると暗い所で見えにくくなります(夜盲症)。' },
      { lv: 3, q: 'カエルの筋肉を、解糖のはたらきを止める薬物を与え、酸素のない状態に置いて刺激をくり返した。筋肉ははじめしばらく収縮をくり返したが、やがて縮んだまま動かなくなった。(1)はじめに収縮できたとき、ATP を供給していたものは何か。(2)最後に縮んだまま動かなくなった理由を説明せよ。', a: '(1)筋肉にたくわえられていたクレアチンリン酸(と、わずかな ATP) (2)ATP がなくなると、ミオシンがアクチンから離れられなくなり、筋肉がゆるめなくなるから', exp: '酸素がないので呼吸ができず、解糖も止められているので、新しく ATP をつくる経路が2つともふさがれています。それでもしばらく収縮できたのは、筋肉にたくわえられたクレアチンリン酸が ADP にリン酸を渡し、ATP を再生していたからです。クレアチンリン酸を使い果たすと ATP が供給されなくなります。筋収縮では、ATP は「ミオシンの頭部がアクチンを引く」ことだけでなく、「ミオシンがアクチンから離れる」ことにも必要です。ATP がないとミオシンとアクチンが結合したまま離れられず、筋肉は縮んだまま固まります。これは死後硬直と同じしくみです。「ATP は縮むためだけに必要」という思いこみに注意しましょう。' }
    ],
    faq: [
      ['反射が、自分で意識して動くより速いのはなぜ?', '反射では、興奮が大脳まで行かず、脊髄などの中枢で感覚神経から運動神経へ直接(または少数の介在ニューロンを通して)伝えられるからです。シナプスでの伝達には1か所あたり約 0.5〜1 ミリ秒かかるので、通るシナプスが少ないほど速くなります。膝蓋腱反射では、シナプスは1か所だけです。熱いものにさわって手を引っこめたあとで「熱い」と感じるのは、手を引っこめる反射が先に起こり、大脳への伝達と判断があとから追いつくからです。'],
      ['筋肉が疲れて力が出なくなるのは、ATP がなくなったからなの?', '激しい運動の疲労では、ATP が完全になくなることはほとんどありません。ATP がなくなると死後硬直のように縮んだまま動かなくなるはずですが、疲れた筋肉はむしろ力が出なくなります。疲労の原因には、細胞の中のリン酸などがふえて筋収縮のしくみが妨げられること、Ca²⁺ の放出が低下することなど、いくつかの要因が考えられていて、完全には分かっていません。']
    ]
  });

  add('b4_plant', {
    secs: [
      { h: 'さらに深く:動けない植物の防衛術 ― ジャスモン酸と全身への情報伝達', t: '植物は逃げられないので、食べられたり病原体に感染したりしたときに、化学的に身を守るしくみを発達させています。\n【食害への応答】:昆虫に葉をかじられると、傷ついた葉で【ジャスモン酸】という植物ホルモンがつくられます。ジャスモン酸は、タンパク質分解酵素のはたらきを妨げる物質(プロテアーゼ阻害物質)などの遺伝子を発現させます。この物質を食べた昆虫は、食べたタンパク質を消化できなくなり、成長が妨げられます。しかも、この応答は傷ついた葉だけでなく、【かじられていない離れた葉】でも起こります。傷ついた場所から信号が植物の体内を伝わり、全身で防御の準備をするのです。\nさらに、食害を受けた植物は揮発性の物質を出し、その昆虫を食べる天敵(寄生バチなど)を呼び寄せることもあります。また、近くの植物がその匂いを受けとって、防御を強めることも知られています。\n【病原体への応答】:病原体が感染すると、感染した部分の細胞がみずから死ぬ【過敏感反応】が起こり、病原体を閉じこめて広がりを防ぎます。その後、サリチル酸などがかかわって、植物全体で病原体に強くなる状態(全身獲得抵抗性)が生じます。\n植物には神経はありませんが、ホルモンや電気的な信号、揮発性物質などを使って、離れた場所に情報を伝えているのです。', key: '食害→ジャスモン酸→消化を妨げる物質。応答は離れた葉にも広がる。病原体には過敏感反応で封じこめ、全身の抵抗性を高める。', ex: [{ q: 'トマトの下の方の葉1枚に傷をつけ、数時間後に、傷をつけていない上の方の葉のプロテアーゼ阻害物質の量を調べた。(1)野生型では、上の葉の阻害物質の量はどうなると考えられるか。(2)ジャスモン酸を合成できない突然変異体で同じ実験をすると、どうなると考えられるか。(3)(2)の突然変異体の上の葉にジャスモン酸を直接与えると、どうなると考えられるか。(4)これらの結果から分かることをまとめよ。', hint: '野生型・突然変異体・ジャスモン酸を与えた突然変異体の3つを比べると、ジャスモン酸が「必要か」「十分か」が分かります。', steps: ['(1) 傷ついた葉から全身に信号が伝わるので、傷をつけていない上の葉でも阻害物質がふえる。', '(2) ジャスモン酸がつくれないと、傷をつけても上の葉の阻害物質はふえない(ジャスモン酸が必要)。', '(3) ジャスモン酸を直接与えれば、傷がなくても阻害物質がふえる(ジャスモン酸があれば十分)。', '(4) 食害の情報は傷ついた葉から全身に伝わり、ジャスモン酸を介して防御物質の合成が起こる。ジャスモン酸は、この応答に必要で、かつ十分な物質である。'], a: '(1)ふえる (2)ふえない (3)ふえる (4)食害の情報は離れた葉まで伝わり、ジャスモン酸が防御物質(プロテアーゼ阻害物質)の合成を引き起こす', check: '「欠けると起こらない(必要)」と「与えると起こる(十分)」の2つの実験をそろえることが、ホルモンのはたらきを示す基本の論理である。オーキシンやジベレリンの実験も、同じ組み立てで考えられる。' }] },
      { h: '実戦演習:光屈性のオーキシンは「こわれる」のか「移動する」のか', t: '光屈性で、光の当たる側が伸びにくく影側が伸びやすいのは、影側のオーキシンが多くなるからです。では、その差は「光の当たる側のオーキシンが光でこわされる」ためでしょうか、それとも「オーキシンが光の当たる側から影側へ移動する」ためでしょうか。これを区別する実験の考察は、入試の定番です。\n戦略:①オーキシンの量は、幼葉鞘の先端を寒天片にのせて集め、その寒天片を、先端を切った幼葉鞘の片側にのせて曲がる角度で測ります(角度はオーキシンの量に比例すると考える)。②【左右の合計】に注目します。合計が暗所と同じなら「こわれていない」、合計が減っていれば「こわれた」と判断します。③雲母片(物質を通さない板)を先端までさしこむと、横の移動ができなくなります。そのときの左右の差を見れば、「移動」が原因かどうかが分かります。\n落とし穴は、片側の値だけを見て結論を出してしまうことです。光の当たる側が少ないだけなら、「こわれた」と「移動した」のどちらでも説明できてしまいます。', key: '合計が変わらなければ「こわれていない」。雲母片で横の移動を止めると差が消えるなら「移動」が原因。', ex: [{ q: 'マカラスムギの幼葉鞘の先端を切り取り、下に寒天片を置いた。寒天片は雲母片で左右に仕切ってある。一定時間後、左右の寒天片をそれぞれ、先端を切った別の幼葉鞘の片側にのせ、曲がった角度を測った(角度はオーキシン量に比例する)。\n(a)暗所に置いた(雲母片は寒天片だけ):左 12°、右 12°\n(b)右から光を当てた(雲母片は寒天片だけで、先端は仕切らない):右(光側)8°、左(影側)16°\n(c)右から光を当てた(雲母片を先端までさしこんで仕切った):右 12°、左 12°\nこれらの結果から、光屈性でオーキシンの分布にかたよりが生じるしくみを説明せよ。', hint: '(a)と(b)の左右の合計を比べ、次に(b)と(c)を比べます。', steps: ['(a)の合計は 12＋12＝24°、(b)の合計は 8＋16＝24° で等しい。光を当ててもオーキシンの総量は減っていないので、光でこわされたのではない。', '(b)では光側が少なく影側が多い。総量は同じなので、光側のオーキシンが影側へ移動したと考えられる。', '(c)で先端まで仕切って横の移動を止めると、光を当てても左右が 12° ずつで差がなくなった。', 'したがって、光を受けた先端で、オーキシンが光側から影側へ横に移動することで、かたよりが生じる。'], a: '光によってオーキシンがこわされるのではなく、幼葉鞘の先端で、オーキシンが光の当たる側から影側へ移動するために、影側のオーキシンが多くなる。', check: 'もし「光でこわされる」のが原因なら、(b)の合計は 24° より小さくなり、(c)でも光側が少なくなるはずである。2つの予想とどちらも合わないので、「移動」の説明が正しいと確かめられる。' }] }
    ],
    drill: [
      { lv: 2, q: '昆虫の食害を受けた植物で合成され、昆虫の消化を妨げる物質の合成を引き起こす植物ホルモンは何か。また、病原体に感染した部分の細胞がみずから死んで、病原体の広がりを防ぐ反応を何というか。', a: 'ジャスモン酸、過敏感反応', exp: 'ジャスモン酸は、食害などの傷に応答してつくられる植物ホルモンで、タンパク質分解酵素の阻害物質などの合成を引き起こし、昆虫の成長を妨げます。また、ジャスモン酸は傷ついた葉だけでなく植物の全身で防御を高めるはたらきにかかわっています。過敏感反応は、病原体が感染した細胞とその周りの細胞が積極的に死ぬことで、病原体が栄養をとれないようにして、感染の広がりを止める反応です。「細胞が死ぬ」のは一見損に見えますが、全体を守るための犠牲といえます。ジャスモン酸はほかにも、果実の成熟や老化などにかかわることが知られています。' },
      { lv: 3, q: '限界暗期が 10 時間の短日植物を、明期 8 時間・暗期 16 時間の条件で育てた。暗期のまん中に、短い光を次の(1)〜(3)のように当てた。花芽を形成するのはどれか。(1)赤色光 (2)赤色光のあとすぐ遠赤色光 (3)赤色光→遠赤色光→赤色光', a: '(2)だけ', exp: '短日植物が花芽をつくるには、【連続した暗期】が限界暗期より長いことが必要です。暗期 16 時間のまん中に光を当てると、暗期が 8 時間ずつに分断されます(光中断)。このとき、光中断の効果を決めているのは光受容体の【フィトクロム】で、赤色光を当てると活性型(Pfr 型)に、遠赤色光を当てると不活性型(Pr 型)に変わり、最後に当てた光の効果が残ります。(1)最後が赤色光なので光中断が効き、連続暗期が 8 時間しかないとみなされて花芽をつくりません。(2)最後が遠赤色光なので、赤色光の効果が打ち消され、光中断がなかったことになって、16 時間の連続暗期として花芽をつくります。(3)最後が赤色光なので花芽をつくりません。レタスの光発芽種子と同じく「最後の光で決まる」と考えると整理できます。' },
      { lv: 3, q: '根の先端の根冠を取り除いた芽ばえを横に倒しておくと、根は伸び続けるが、下向きに曲がらなかった。根冠を残しておくと下に曲がった。この結果から、根冠にはどのようなはたらきがあると考えられるか。根冠の細胞の特徴にもふれて説明せよ。', a: '根冠は重力の向きを感じとる部位である。根冠のコルメラ細胞にはデンプン粒をふくむアミロプラストがあり、それが重力の方向に沈むことで重力の向きを感じ、オーキシンを下側に多く運ばせる', exp: '根冠を除いても根が伸び続けたので、根冠は伸長そのものには必要ありません。しかし下に曲がらなくなったので、根冠は「重力の向きを感じる」はたらきをもつと考えられます。根冠の中心部にある【コルメラ細胞】には、デンプンをたくさんふくむアミロプラストがあり、これが重りのように重力の方向へ沈みます。根を横に倒すとアミロプラストが細胞の下側に移り、その情報によってオーキシンを運ぶタンパク質の配置が変わって、根の下側にオーキシンが多く運ばれます。根では、茎より低い濃度で伸長が抑えられるので、オーキシンの多い下側の伸長が抑えられ、根は下に曲がります。茎の場合は、内皮の細胞のアミロプラストが同じ役割をしています。' }
    ],
    faq: [
      ['植物には神経がないのに、どうやって離れた葉に情報を伝えるの?', '植物は、ホルモンなどの化学物質を維管束を通して運ぶほか、傷ついた場所から電気的な信号やカルシウムイオンの濃度変化が葉から葉へ伝わることも分かってきています。さらに、揮発性物質を空気中に放出して、同じ株の離れた葉や、近くの別の植物に情報を伝えることもあります。動物の神経ほど速くはありませんが、数分から数時間で全身に応答が広がり、防御の準備ができるのです。'],
      ['「1個の腐ったリンゴが箱全体を腐らせる」と言われるのはなぜ?', '熟したり傷んだりしたリンゴからは、気体の植物ホルモンである【エチレン】が多く出ます。エチレンは果実の成熟を促し、さらに成熟した果実はエチレンをもっと出す、という「自分で自分を加速する」性質があります。そのため、1個から出たエチレンが周りの果実の成熟を進め、それらもエチレンを出して、箱全体の熟成や老化が進むのです。逆に、エチレンを吸収する物質を入れておくと、果物を長持ちさせられます。']
    ]
  });

  add('b4_eco', {
    secs: [
      { h: 'さらに深く:群れの大きさには「ちょうどよい」大きさがある', t: '群れをつくると、天敵を見つけやすくなる一方で、えさをめぐる争いがふえます。この2つの効果のつり合いから、群れには【最適な大きさ】があると考えられます。\nある鳥の群れで、1羽が1時間のうちに使う時間を考えます。周りを見張る【警戒】の時間は、群れが大きいほど見張りを分担できるので、1羽あたりは少なくてすみます。一方、仲間との【争い】の時間は、群れが大きいほどふえます。残りの時間が【採食】にあてられます。\n例えば、警戒の時間が 36÷(群れの個体数)分、争いの時間が (群れの個体数)分 だとすると、\n・1羽:警戒 36＋争い 1＝37 分、採食 23 分\n・4羽:警戒 9＋争い 4＝13 分、採食 47 分\n・6羽:警戒 6＋争い 6＝12 分、採食 48 分\n・10羽:警戒 3.6＋争い 10＝13.6 分、採食 46.4 分\nとなり、警戒と争いの合計が最も少なく、採食に最も多くの時間を使えるのは6羽のときです。\nこの考え方の大切な点は、【最適な大きさは環境で変わる】ことです。天敵が多い場所では警戒に必要な時間がふえるので、最適な群れは大きくなります。えさが少ない場所では争いが激しくなるので、最適な群れは小さくなります。\n群れの大きさだけでなく、縄張りの広さにも同じ考え方が使えます。縄張りを広げると得られるえさはふえますが、守るための労力もふえるので、「利益−費用」が最も大きくなる広さが最適になります。生物の行動を「利益と費用のつり合い」として考えるのは、行動生態学の基本的な見方です。', key: '群れの最適な大きさは、警戒の時間(群れが大きいほど減る)と争いの時間(ふえる)の合計が最小になる所。天敵やえさの量で変わる。', ex: [{ q: '上の例(警戒の時間＝36÷個体数、争いの時間＝個体数、単位は分)で、天敵がふえて警戒に必要な時間が2倍(72÷個体数)になったとする。群れの個体数が 4、6、8、10 のときの「警戒＋争い」の時間を求め、最適な群れの大きさがどう変わるか答えよ。', hint: '個体数ごとに 72÷n＋n を計算します。', steps: ['4羽:72÷4＋4＝18＋4＝22 分。', '6羽:72÷6＋6＝12＋6＝18 分。', '8羽:72÷8＋8＝9＋8＝17 分。', '10羽:72÷10＋10＝7.2＋10＝17.2 分。', '調べた4つの大きさの中で合計が最小になるのは8羽で、天敵がふえる前の6羽より大きくなる。'], a: '4羽 22 分、6羽 18 分、8羽 17 分、10羽 17.2 分。最適な群れは6羽から8羽へと大きくなる', check: '天敵が多いと、警戒を分担できる大きな群れの利点が大きくなるので、最適な群れが大きくなるのは理にかなう。実際に、天敵の多い環境で群れが大きくなる傾向は、多くの動物で観察されている。' }] },
      { h: '実戦演習:生命表から、どの時期の死亡が個体群を左右するかを読む', t: '個体群の生存のようすは、生まれた個体が各段階でどれだけ生き残ったかを表にした【生命表】で調べます。入試では、生命表から死亡率を計算し、生存曲線の型や、個体群がふえるか減るかを判断させる問題が出ます。\n戦略:①各段階の【死亡数】＝その段階のはじめの数−次の段階のはじめの数。②【死亡率】＝死亡数÷その段階のはじめの数。死亡数が多い段階と、死亡率が高い段階は、必ずしも一致しない点に注意します。③次の世代の卵(子)の数を、成体の数×雌の割合×1匹あたりの産卵数で求め、はじめの卵の数と比べて、個体群がふえるか減るかを判断します。\n落とし穴:死亡率を「はじめの卵の数」で割ってしまうこと。死亡率は、その段階に入った個体の数で割ります。また、生存曲線は縦軸を対数で表すことが多く、その場合、傾きが急なほど死亡率が高いことを表します。', key: '死亡率は「その段階のはじめの数」で割る。次世代の数＝成体数×雌の割合×産卵数で、ふえるか減るかを判断。', ex: [{ q: 'ある昆虫の個体群で、卵 1000 個が、1齢幼虫 400、2齢幼虫 300、3齢幼虫 240、成虫 120 と減っていった。(1)各段階(卵、1齢、2齢、3齢)の死亡率を求めよ。(2)死亡数が最も多いのはどの段階か。(3)成虫の雌雄の比は 1：1 で、雌1匹が 20 個の卵を産むとすると、次の世代の卵は何個か。この個体群はふえているか、減っているか。', hint: '死亡率＝その段階の死亡数÷その段階のはじめの数。', steps: ['(1) 卵:(1000−400)/1000＝60%。1齢:(400−300)/400＝25%。2齢:(300−240)/300＝20%。3齢:(240−120)/240＝50%。', '(2) 死亡数は卵 600、1齢 100、2齢 60、3齢 120 で、卵の段階が最も多い。', '(3) 成虫 120 匹のうち雌は 60 匹。次の世代の卵は 60×20＝1200 個。', 'はじめの 1000 個より多いので、この個体群はふえている(1世代で 1.2 倍)。'], a: '(1)卵 60%、1齢 25%、2齢 20%、3齢 50% (2)卵の段階 (3)1200 個、ふえている', check: '死亡率は3齢(50%)も高いが、死亡数では卵の段階が圧倒的に多い。若い時期に多くが死ぬので、生存曲線は早死型に近い。もし3齢の死亡率が 50% から 60% に上がると、成虫は 96 匹、次世代の卵は 960 個となり、個体群は減少に転じる。' }] }
    ],
    drill: [
      { lv: 2, q: '生態系での窒素の循環について、次の(1)〜(3)のはたらきを何というか。また、それを行う生物の例を1つずつ答えよ。(1)大気中の N₂ をアンモニウムイオンなどに変える (2)アンモニウムイオンを硝酸イオンに変える (3)硝酸イオンを N₂ にもどして大気中へ放出する', a: '(1)窒素固定(根粒菌、アゾトバクター、ネンジュモなどのシアノバクテリア) (2)硝化(亜硝酸菌・硝酸菌などの硝化菌) (3)脱窒(脱窒素細菌)', exp: '大気の約 78% は N₂ ですが、ほとんどの生物は N₂ を直接使えません。(1)【窒素固定】は N₂ をアンモニウムイオンに変えるはたらきで、マメ科植物と共生する根粒菌や、アゾトバクター、ネンジュモなど一部の細菌だけが行えます。(2)【硝化】は、アンモニウムイオンを亜硝酸菌が亜硝酸イオンに、硝酸菌が硝酸イオンに酸化するはたらきです。硝化菌はこの酸化で得たエネルギーで有機物をつくる化学合成細菌です。植物は、おもに硝酸イオンやアンモニウムイオンを根から吸収して、アミノ酸などの有機窒素化合物をつくります(窒素同化)。(3)【脱窒】は、酸素の少ない土の中などで、硝酸イオンが N₂ にもどされるはたらきです。' },
      { lv: 3, q: '群れをつくる鳥の1羽が1時間に、警戒に 36÷n 分、争いに n 分を使うとする(n は群れの個体数)。えさが減って争いが激しくなり、争いの時間が 2n 分になった。n が 2、4、6 のときの「警戒＋争い」の時間を求め、最適な群れの大きさがどう変わるか答えよ。', a: '2羽 22 分、4羽 17 分、6羽 18 分。最適な群れは6羽から4羽へと小さくなる', exp: '2羽:36÷2＋2×2＝18＋4＝22 分。4羽:9＋8＝17 分。6羽:6＋12＝18 分。合計が最も少ないのは4羽で、争いが激しくなる前の最適な大きさ(6羽)より小さくなります。えさが少ないと、群れが大きいほど1羽あたりのえさが減り、争いの損失が大きくなるので、小さな群れのほうが有利になるのです。天敵がふえると最適な群れは大きくなり、えさが減ると小さくなる、というように、「どちらの費用がふえたか」で変わる向きが決まります。実際の動物は、こうした計算をしているわけではありませんが、自然選択によって、その環境で有利な行動をとる個体が多く子を残してきた結果、こうした傾向が見られると考えられます。' },
      { lv: 3, q: 'ある森林で、1年間の総生産量が 2000、生産者の呼吸量が 800、消費者と分解者の呼吸量の合計が 900 だった(単位はすべて g/m²)。(1)純生産量 (2)この森林全体で1年間に蓄積された有機物の量(生態系純生産量) を求めよ。また、(2)の値から、この森林は大気中の CO₂ を吸収しているか、放出しているかを答えよ。', a: '(1)1200 g/m² (2)300 g/m²。CO₂ を吸収している', exp: '(1)純生産量＝総生産量−生産者の呼吸量＝2000−800＝1200 g/m²。これは生産者がつくって自分で使わなかった有機物で、生産者の成長、枯死、被食に回ります。(2)枯死した部分や食べられた部分も、消費者や分解者の呼吸でやがて分解されます。森林全体として見ると、有機物がふえた量は、純生産量から消費者と分解者の呼吸量を引いた 1200−900＝300 g/m² です。これを生態系純生産量といいます。正の値なので、光合成で取りこんだ炭素のほうが、生態系全体の呼吸で出ていく炭素より多く、森林は大気中の CO₂ を吸収していることになります。若い森林では大きな正の値になりやすく、成熟した森林では0に近づく傾向があります。' }
    ],
    faq: [
      ['群れは大きければ大きいほど安全なのではないの?', '天敵から身を守る点だけを見れば、群れが大きいほど見張りの目がふえ、自分が襲われる確率も下がるので有利です。しかし、群れが大きいと、えさをめぐる争いがふえ、えさ場を早く食べつくしてしまい、病気もうつりやすくなります。利益と費用の両方がふえるので、差し引きが最も大きくなる「ちょうどよい」大きさがあります。どの大きさが最適かは、天敵の多さやえさの量などの環境で変わります。'],
      ['生態系純生産量がマイナスになることはあるの?', 'あります。生態系全体の呼吸(生産者・消費者・分解者)が光合成より多いと、生態系の有機物は減り、大気へ CO₂ を放出することになります。例えば、森林火災や伐採のあとでは、残った大量の枯れ木や落ち葉が分解されるので、しばらくはマイナスになりやすいです。また、温暖化で土の中の分解者のはたらきが活発になると、土に蓄えられた有機物の分解が進み、CO₂ の放出がふえることが心配されています。']
    ]
  });

  add('b4_evo', {
    secs: [
      { h: 'さらに深く:自分を犠牲にする行動が進化できる理由 ― 血縁度と包括適応度', t: '働きバチは自分では子を産まず、女王が産んだ妹たちの世話をします。自分の子を残さない個体の性質が、自然選択でどうして受け継がれるのでしょうか。\n鍵になるのが【血縁度】です。血縁度は、2個体がある遺伝子を共通祖先から受け継いで共有している確率で、ヒトのような二倍体の生物では、親子は 1/2、両親が同じきょうだいは 1/2、祖父母と孫は 1/4、いとこは 1/8 です。\n自分の遺伝子を次の世代に伝える方法は、自分の子を残すことだけではありません。自分と遺伝子を共有する血縁者を助けて、その子をふやすことでも、自分と同じ遺伝子が次の世代にふえます。自分の子を通して伝わる分と、血縁者を助けることで伝わる分を合わせた、遺伝子の伝わりやすさを【包括適応度】といいます。\n血縁者を助ける行動が有利になる条件は、「助けた相手との血縁度×相手がふやす子の数」が、「自分が失う子の数×自分の子との血縁度」より大きいことです(ハミルトンの考え)。\nミツバチでは、雄は未受精卵から生まれる一倍体(半数体)、雌は二倍体です。父親が同じ姉妹は、父親からまったく同じ遺伝子を受け継ぎ(共有する確率1)、母親からは確率 1/2 で同じ遺伝子を受け継ぐので、姉妹の血縁度は 1/2×1＋1/2×1/2＝【3/4】になります。一方、自分が産む娘との血縁度は 1/2 です。つまり、働きバチにとっては、自分の娘を育てるより、妹を育てるほうが、自分の遺伝子を多く残せる計算になります。これが、ミツバチなどで社会性が発達した理由の1つと考えられています。', key: '血縁者を助けても自分と同じ遺伝子はふえる(包括適応度)。二倍体のきょうだいは 1/2、ミツバチの姉妹は 3/4。', ex: [{ q: 'ミツバチでは、雄は一倍体、雌は二倍体である。1匹の女王と1匹の雄の間に生まれた働きバチどうし(姉妹)の血縁度を求めよ。また、働きバチが自分で娘を産んだとした場合の、母と娘の血縁度と比べよ。', hint: '姉妹が共有する遺伝子を、父親由来と母親由来に分けて考えます。', steps: ['姉妹のゲノムの半分は父親由来、半分は母親由来である。', '父親は一倍体で、精子はすべて同じ遺伝子をもつので、父親由来の半分は姉妹で確実に(確率1で)同じ。', '母親は二倍体で、卵には母親の対立遺伝子の片方が 1/2 の確率で入るので、母親由来の半分を姉妹が共有する確率は 1/2。', '姉妹の血縁度は 1/2×1＋1/2×1/2＝3/4。一方、母と娘では、娘のゲノムの半分が母親由来なので血縁度は 1/2。'], a: '姉妹の血縁度は 3/4、母と娘は 1/2。姉妹のほうが血縁度が高い', check: 'ヒトのような二倍体どうしのきょうだいなら、父親由来の部分も 1/2 の確率でしか共有しないので 1/2×1/2＋1/2×1/2＝1/2 となる。ミツバチの雄が一倍体であることが、姉妹の血縁度を高めている。' }] },
      { h: '実戦演習:ヘテロ接合体が有利なときの遺伝子頻度の変化', t: '自然選択の計算は、「選択前の遺伝子型の頻度」→「生き残る割合(適応度)をかける」→「生き残った集団で遺伝子頻度を数え直す」の3段階で行います。\n戦略:①ハーディ・ワインベルグの法則で、選択前の遺伝子型の頻度 p²、2pq、q² を出します。②それぞれに適応度(子を残せる割合)をかけます。③生き残った集団の合計で割って、新しい頻度を出します。ここで割り算を忘れるのが最大の落とし穴です。\nヘテロ接合体が両方のホモ接合体より有利な場合(鎌状赤血球の遺伝子とマラリアの関係など)は、どちらの対立遺伝子も集団から消えず、ある頻度でつり合います。つり合いの頻度は、【2つの対立遺伝子の「平均の適応度」が等しくなる】条件から求められます。ある対立遺伝子が、相手として A と組む確率は p、S と組む確率は q なので、その対立遺伝子の平均の適応度は「(A と組んだときの適応度)×p＋(S と組んだときの適応度)×q」です。', key: '頻度→適応度をかける→合計で割る。ヘテロが有利なら、2つの対立遺伝子の平均の適応度が等しくなる頻度でつり合う。', ex: [{ q: 'マラリアの多い地域で、ある遺伝子の対立遺伝子 A(正常)と S(鎌状赤血球)について、子を残せる割合(適応度)が AA 0.90、AS 1.00、SS 0.20 だったとする。任意交配が行われ、はじめの S の頻度は 0.10 である。(1)次の世代の S の頻度を求めよ(小数第3位まで)。(2)S の頻度がつり合う値を求めよ。', hint: '(2)A の平均の適応度は 0.90p＋1.00q、S の平均の適応度は 1.00p＋0.20q。', steps: ['(1) 選択前の頻度は AA＝0.81、AS＝2×0.9×0.1＝0.18、SS＝0.01。', '適応度をかけると AA 0.729、AS 0.180、SS 0.002、合計 0.911。', '生き残った集団での S の頻度は (0.180×1/2＋0.002)/0.911＝0.092/0.911≒0.101。', '(2) つり合いでは A と S の平均の適応度が等しい:0.90p＋1.00q＝1.00p＋0.20q。', '整理すると 0.80q＝0.10p、q/p＝1/8。p＋q＝1 より q＝1/9≒0.11。'], a: '(1)約 0.101 (2)約 0.11(1/9)', check: 'はじめの S の頻度 0.10 はつり合いの値 0.111 より少し小さいので、次の世代でわずかに増える(0.101)という(1)の結果と合う。SS が非常に不利(0.20)でも、AS が有利なので S は集団から消えない。' }] }
    ],
    drill: [
      { lv: 2, q: 'ヒトで、自分といとこ(父親の兄弟の子)の血縁度を求めよ。', a: '1/8', exp: '血縁度は、共通祖先を通る経路の「親子の受け渡し」1回ごとに 1/2 をかけて求めます。自分といとこの共通祖先は、祖父と祖母の2人です。自分→父→祖父→おじ→いとこ の経路では、親子の受け渡しが4回あるので (1/2)⁴＝1/16。祖母を通る経路も同じく 1/16 です。2つの経路を足して 1/16＋1/16＝1/8 になります。きょうだい(両親が同じ)なら、父を通る経路 (1/2)²＝1/4 と母を通る経路 1/4 の和で 1/2、おじと自分なら 1/4 です。血縁度は「遺伝子の何% が同じか」ではなく、「共通祖先から同じ遺伝子を受け継いでいる確率」である点に注意しましょう。' },
      { lv: 3, q: 'ある鳥では、若い個体が自分で繁殖すると子を2羽育てられる。一方、繁殖せずに親の巣を手伝うと、親が育てられる子(自分のきょうだい、血縁度 1/2)が3羽ふえる。自分の子との血縁度を 1/2 として、遺伝子を次の世代に伝える点では、どちらが有利か。', a: '手伝うほうが有利(自分で繁殖:2×1/2＝1.0、手伝う:3×1/2＝1.5)', exp: '自分と同じ遺伝子がどれだけ次の世代に伝わるかを、「子やきょうだいの数×血縁度」で比べます。自分で繁殖すると 2×1/2＝1.0、手伝うと 3×1/2＝1.5 なので、手伝うほうが有利です。このように、血縁者を助ける行動は、「助けた相手の血縁度×ふえた数」が「失う自分の子の数×血縁度」より大きいときに進化しうると考えられます(ハミルトンの考え)。実際に、ヘルパーとよばれる手伝いをする鳥は、自分で繁殖できるなわばりが不足している環境で多く見られます。もし手伝ってもきょうだいが1羽しかふえないなら 0.5 となり、自分で繁殖するほうが有利です。条件によって有利な行動が変わる点が大切です。' },
      { lv: 3, q: 'ある大きな集団で、対立遺伝子 a の頻度は 0.05 である。この集団からたまたま 10 個体(二倍体)だけが離れた島に移り住み、新しい集団をつくった。この 10 個体がもつ 20 個の遺伝子の中に、a が1つもふくまれない確率はおよそいくらか。(0.95²⁰≒0.36)', a: '約 0.36(36%)', exp: '10 個体は二倍体なので、遺伝子は 20 個あります。それぞれの遺伝子が a でない確率は 1−0.05＝0.95 で、20 個がすべて a でない確率は 0.95²⁰≒0.36 です。つまり、約 36% の確率で、新しい集団から a が完全に失われます。このように、少数の個体が新しい集団をつくるときに、もとの集団とはちがう遺伝子頻度になることを【創始者効果】といい、遺伝的浮動の一種です。偶然によって、有利・不利と関係なく遺伝子が失われたり、逆にまれな遺伝子の頻度が高くなったりします。島の生物や、少人数の集団から広がった人類集団で、特定の遺伝病の頻度が高いことがあるのは、この効果で説明されることがあります。' }
    ],
    faq: [
      ['自分の子を残さない働きバチの性質は、どうやって次の世代に伝わるの?', '働きバチ自身は子を残しませんが、働きバチの性質にかかわる遺伝子は、働きバチの母親である女王ももっています。女王が産む次の女王や雄を通して、その遺伝子は次の世代に伝わります。働きバチが妹たちの世話をすることで、同じ遺伝子をもつ血縁者がたくさん育てば、その遺伝子は集団の中でふえていきます。自然選択は個体ではなく、遺伝子が次の世代にどれだけ伝わるかで考えると理解しやすくなります。'],
      ['ヘテロ接合体が有利だと、なぜ不利な遺伝子が消えないの?', '不利な遺伝子(例えば SS で重い症状を引き起こす S)は、ホモ接合体では選択で取り除かれますが、頻度が低いときは、そのほとんどがヘテロ接合体(AS)の中にあります。AS はマラリアに強く有利なので、S は AS を通して効率よく次の世代に伝わります。S が減るとヘテロの利点で増え、S が増えると SS の不利で減るので、ある頻度でつり合います。マラリアのない地域では AS の利点がなくなるので、S の頻度は下がっていきます。']
    ]
  });

  /* ===================== 地学 ===================== */
  add('g4_earth', {
    secs: [
      { h: 'さらに深く:地球の中はなぜ熱いのか ― 地温勾配と地殻熱流量', t: '鉱山やボーリングで地下にもぐると、地表付近では深さ 1 km ごとに温度が約 20〜30℃ ずつ上がります。この割合を【地温勾配】といいます。\n温度に差があると、熱は高温の所から低温の所へ流れます。地下から地表へ向かって、単位面積・単位時間あたりに流れ出る熱の量を【地殻熱流量】といい、【熱流量＝(岩石の熱の伝えやすさ)×(地温勾配)】で求められます。岩石の熱の伝えやすさ(熱伝導率)を 2.5 W/(m·K)、地温勾配を 30 K/km(＝0.030 K/m)とすると、熱流量は 2.5×0.030＝0.075 W/m² です。地球全体の平均はおよそ 0.08 W/m² で、地表全体(約 5.1×10¹⁴ m²)では約 4×10¹³ W にもなります。それでも、地表が吸収する太陽のエネルギー(平均約 240 W/m²)の数千分の1にすぎないので、地表の気温はほとんど太陽で決まっています。\nでは、この熱はどこから来るのでしょうか。主な源は、①地球が誕生したときに微惑星の衝突などで生じた熱の残り、②岩石にふくまれる【放射性同位体】(ウラン・トリウム・カリウム40など)が崩壊するときに出す熱、です。放射性同位体は花こう岩など大陸地殻の岩石に多くふくまれます。\n注意したいのは、地温勾配は深くなるとずっと小さくなることです。地表付近の 30 K/km のまま 100 km の深さまで延ばすと 3000℃ 以上になってしまいますが、実際の 100 km の深さの温度は 1300℃ 前後と考えられています。熱を生む放射性同位体が浅い所に多いことや、深い所ではマントルの対流が熱を運ぶことが、その理由です。', key: '熱流量＝熱伝導率×地温勾配。熱源は誕生時の熱の残りと放射性同位体の崩壊熱。地温勾配は深くなるほど小さくなる。', ex: [{ q: 'ある地域で、ボーリング孔の深さ 500 m と 1500 m の温度がそれぞれ 30℃ と 55℃ だった。岩石の熱伝導率を 2.4 W/(m·K) とする。(1)地温勾配を K/km で求めよ。(2)地殻熱流量を求めよ。(3)この地温勾配が保たれるとすると、深さ 3000 m の温度は何℃か。', hint: '地温勾配＝温度差÷深さの差。熱流量を出すときは K/m に直します。', steps: ['(1) 深さの差は 1000 m＝1 km、温度差は 55−30＝25 K。地温勾配は 25 K/km。', '(2) 25 K/km＝0.025 K/m。熱流量＝2.4×0.025＝0.060 W/m²。', '(3) 1500 m から 3000 m までは 1.5 km 深いので、温度は 25×1.5＝37.5 K 上がる。', '55＋37.5≒93℃。'], a: '(1)25 K/km (2)0.060 W/m² (3)約 93℃(92.5℃)', check: '熱流量 0.060 W/m² は地球の平均(約 0.08 W/m²)と同じ程度で妥当。火山や地熱地帯では、地温勾配が 100 K/km をこえる所もあり、その熱が地熱発電に使われている。' }] },
      { h: '実戦演習:屈折波の走時からモホ面の深さを求める', t: '震央の近くでは、地殻の中をまっすぐ伝わる地震波(直接波)が先に届きます。ところが震央から遠い所では、いったんモホ面まで下り、速いマントルの上面にそって伝わってから上がってくる【屈折波】のほうが先に届きます。走時曲線はこの切りかわりの点で折れ曲がり、その位置からモホ面の深さが分かります。\n戦略:①地殻の P波速度を V₁、マントルを V₂(V₂＞V₁)、地殻の厚さを H とします。②直接波の走時は t₁＝x/V₁。③屈折波は、臨界角 i(sin i＝V₁/V₂)でモホ面に入り、モホ面にそって進み、同じ角度で上がってきます。走時を計算すると【t₂＝x/V₂＋2H cos i/V₁】となります(グラフでは傾き 1/V₂ の直線で、t 軸を 2H cos i/V₁ で切る)。④t₁＝t₂ となる距離(折れ曲がりの点)x₀ から H を求めます。\n落とし穴:屈折波の道のりを「2H＋x」のように単純に足してしまうこと。また、走時曲線の折れ曲がる点の距離を、そのままモホ面の深さだと思いこむこと。折れ曲がる距離は、ふつう深さの5倍前後もあります。', key: '屈折波の走時は x/V₂＋2H cos i/V₁(sin i＝V₁/V₂)。直接波と等しくなる距離から H が出る。', ex: [{ q: '地殻の P波速度を 6.0 km/s、マントル最上部を 8.0 km/s とする。ごく浅い地震の走時曲線が、震央距離 160 km で折れ曲がった。(1)臨界角 i の cos i を求めよ。(2)屈折波の走時の式を導け。(3)地殻の厚さ H を求めよ。(√7≒2.65)', hint: '屈折波の道のり:斜めに下る区間 H/cos i、モホ面にそう区間 x−2H tan i、斜めに上る区間 H/cos i。', steps: ['(1) sin i＝V₁/V₂＝6.0/8.0＝0.75。cos i＝√(1−0.75²)＝√0.4375＝√7/4≒0.66。', '(2) 走時は t₂＝2×(H/cos i)/V₁＋(x−2H tan i)/V₂。1/V₂＝sin i/V₁ を使うと、tan i/V₂＝sin²i/(V₁ cos i) なので、t₂＝x/V₂＋(2H/(V₁ cos i))(1−sin²i)＝x/V₂＋2H cos i/V₁。', '(3) 折れ曲がる点 x₀ では直接波と屈折波が同時に届く:x₀/V₁＝x₀/V₂＋2H cos i/V₁。', 'x₀(1/6.0−1/8.0)＝x₀/24、2H cos i/V₁＝2H×(√7/4)/6.0＝√7 H/12。よって x₀/24＝√7 H/12、H＝x₀/(2√7)。', 'H＝160/(2×2.65)≒30 km。'], a: '(1)約 0.66(√7/4) (2)t₂＝x/V₂＋2H cos i/V₁ (3)約 30 km', check: 'H＝30 km として、x＝160 km での走時を計算すると、直接波 160/6.0≒26.7 s、屈折波 160/8.0＋2×30×0.661/6.0≒20.0＋6.6＝26.6 s とほぼ等しい。大陸の地殻の厚さ(30〜60 km 程度)としてもっともらしい。' }] }
    ],
    drill: [
      { lv: 2, q: '地温勾配が 30 K/km、岩石の熱伝導率が 2.0 W/(m·K) の地域の地殻熱流量を求めよ。また、地表 1 m² から 1 年間(3.2×10⁷ 秒とする)に流れ出る熱量を求めよ。', a: '熱流量 0.060 W/m²、1年間で 約 1.9×10⁶ J', exp: '地温勾配 30 K/km を K/m に直すと 0.030 K/m です。熱流量＝熱伝導率×地温勾配＝2.0×0.030＝0.060 W/m²。1 W は 1 秒間に 1 J なので、1 年間では 0.060×3.2×10⁷≒1.9×10⁶ J になります。これは、1 m² の地面から1年かけて出てくる熱で、水 1 kg の温度を約 450 K 上げる量ですが、同じ面積に届く太陽のエネルギーに比べるとずっと小さい値です。単位の換算(km→m)を忘れると、熱流量が 1000 倍の 60 W/m² となり、地表がとても熱くなってしまう答えになるので、桁の確認が大切です。' },
      { lv: 3, q: '地球の自転による遠心力の加速度は、赤道上でいくらか。地球の半径を 6.4×10⁶ m、自転周期を 8.6×10⁴ 秒として求め、重力加速度 9.8 m/s² の何% にあたるか答えよ。(π＝3.14)', a: '約 0.034 m/s²、約 0.35%', exp: '自転の角速度は ω＝2π/T＝6.28/8.6×10⁴≒7.3×10⁻⁵ rad/s です。遠心力の加速度は rω²＝6.4×10⁶×(7.3×10⁻⁵)²≒6.4×10⁶×5.3×10⁻⁹≒0.034 m/s²。9.8 m/s² に対して 0.034/9.8≒0.0035、約 0.35% です。この分だけ、赤道では重力が小さくなります。極では自転軸からの距離が0なので遠心力は0です。実際の重力の差(赤道約 9.78、極約 9.83 m/s²)はこれより少し大きく、それは赤道のほうが地球の中心から遠い(地球が赤道方向にふくらんでいる)ことも効いているからです。地球の形が赤道方向にふくらんでいるのも、この遠心力が原因です。' },
      { lv: 3, q: '地磁気が地球の中心に置いた棒磁石(双極子)でつくられているとすると、緯度 φ の地点の伏角 I は tan I＝2 tan φ の関係を満たす。北緯 35° の地点の伏角を求めよ。(tan 35°＝0.70、tan 54.5°＝1.40)', a: '約 54.5°', exp: 'tan I＝2×tan 35°＝2×0.70＝1.40 なので、I≒54.5° です。この式から、赤道(φ＝0)では tan I＝0 で伏角0°(磁力線が水平)、極(φ＝90°)では伏角 90°(磁力線が鉛直)になることが分かり、伏角が緯度とともに大きくなる理由を説明できます。逆に、昔の岩石に記録された伏角を測れば、その岩石ができた当時の緯度(古緯度)を推定できます。これが、大陸が移動してきたことを示す証拠(古地磁気学)の1つになりました。ただし、実際の地磁気は棒磁石とは少しずれていて、東京付近の実測の伏角は約 49° です。' }
    ],
    faq: [
      ['地球内部の熱がなくなったら、どうなるの?', '地球はゆっくり冷えていますが、内部の熱はマントルの対流や外核の流れを動かす原動力になっています。熱がなくなってマントルの対流が止まると、プレートの運動がなくなり、火山活動や大地震、山脈の形成も起こらなくなると考えられます。外核の流れが止まると地磁気もつくられなくなります。地球より小さい火星は早く冷えたため、現在は地磁気がほとんどなく、プレート運動も見られません。'],
      ['屈折波が直接波より先に届くことがあるのは、遠回りなのになぜ?', '屈折波は、地殻を斜めに下ってからモホ面にそってマントル最上部を進みます。道のりは長くなりますが、マントルの中の速さ(約 8 km/s)は地殻(約 6 km/s)より大きいので、遠くまで行くほど速い区間が長くなり、時間の差を取りもどせます。高速道路を使うと、遠回りでも目的地に早く着くのと同じです。近くでは高速道路に乗り降りする時間のほうが大きいので、直接波が先に届きます。']
    ]
  });

  add('g4_plate', {
    secs: [
      { h: 'さらに深く:海嶺が高く、古い海底ほど深いのはなぜか', t: '海底の深さは、場所によって大きくちがいます。海嶺の頂上では深さ約 2500 m ですが、海嶺から離れるにつれて深くなり、古い海底では 5000〜6000 m に達します。これは、海洋プレートが【冷えて重くなる】からです。\n海嶺でできたばかりのプレートは、高温で膨張しているので密度が小さく、アイソスタシー(浮力のつり合い)によって高く浮かんでいます。海嶺から離れるにつれてプレートは海水に熱をうばわれて冷え、縮んで密度が大きくなり、さらに下のほうも冷えて固いプレートの部分が厚くなっていきます。そのため、海底はしだいに沈んでいきます。\n調べてみると、海底の深さは、海底ができてからの年代 t のおよそ【平方根に比例して】深くなることが分かっています。おおよそ\n深さ〔m〕≒2500＋350√t(t は百万年単位)\nと表せます。例えば、できてから 25 百万年の海底は 2500＋350×5＝4250 m、100 百万年なら 2500＋350×10＝6000 m です。はじめは速く沈み、古くなるほど沈み方がゆるやかになるのは、冷え方が時間とともにゆっくりになるからです。\nこの考え方は、プレートの沈み込みとも関係します。古い海洋プレートほど冷たく重いので、海溝でマントルの中へ沈みこみやすくなります。大西洋のように海嶺の両側に大陸がついている海は広がり続け、太平洋のように周りを海溝に囲まれた海は、沈みこむプレートに引っぱられて縮んでいると考えられています。', key: '海洋プレートは冷えると縮んで重くなり、深く沈む。深さは年代の平方根にほぼ比例してふえる。', ex: [{ q: '海底の深さが「2500＋350√t〔m〕(t は百万年単位の年代)」で表されるとする。(1)深さ 5300 m の海底の年代を求めよ。(2)この海底が、海嶺から片側に年 2.0 cm の一定の速さで移動してきたとすると、海嶺から何 km 離れているか。', hint: '(1)は √t について解きます。(2)は 速さ×時間 です。', steps: ['(1) 5300＝2500＋350√t より √t＝2800/350＝8.0、t＝64。年代は 6400 万年。', '(2) 年 2.0 cm＝2.0×10⁻⁵ km/年。', '距離＝2.0×10⁻⁵×6.4×10⁷＝1.28×10³ km。', 'およそ 1300 km 離れている。'], a: '(1)約 6400 万年 (2)約 1300 km(1280 km)', check: '海嶺から 1280 km 離れるまでに 2800 m 沈んだことになる。最初の 640 km(3200 万年)で 2500＋350×√32≒4480 m と、前半のほうが速く沈む(1980 m と 820 m)。平方根の関係らしい「はじめ急、あとゆるやか」な変化になっている。' }] },
      { h: '実戦演習:ホットスポットの火山列からプレートの運動を復元する', t: 'ホットスポットはマントルの深い所に根をもち、プレートの動きとは関係なくほぼ同じ場所にあると考えられています。その上をプレートが動くと、火山島が次々にでき、プレートの動きにつれて運ばれていくので、【年代が古いものほど、プレートの進む向きに遠く】並びます。\n戦略:①いま活動している火山がホットスポットの真上。②2つの島の距離÷年代の差＝その期間のプレートの平均の速さ。③火山列の向き(古い島の方向)がプレートの進む向き。④火山列が途中で折れ曲がっていたら、その折れ曲がりの島の年代に、プレートの進む向きが変わったと読む。\n単位の換算がよく出ます。【1 km/百万年＝1 mm/年＝0.1 cm/年】を覚えておくと便利です。\n落とし穴:火山列の向きを「新しい島へ向かう向き」と読んでしまい、プレートの進む向きを逆にすること。ホットスポットは動かないので、島は「プレートに乗って、ホットスポットから遠ざかる向き」に運ばれます。', key: '古い島ほどプレートの進む向きに遠くにある。速さ＝距離÷年代差、1 km/百万年＝0.1 cm/年。折れ曲がりは向きの変化。', ex: [{ q: 'ある海洋プレート上に、ホットスポットでできた火山島の列がある。いま活動中の島 P から西北西に 1800 km の島 Q は 2000 万年前、さらに同じ向きに 2200 km(P から 4000 km)の島 R は 4500 万年前にできた。火山列は R で折れ曲がり、R から北に 1500 km の島 S は 6500 万年前にできた。(1)P−Q 間、Q−R 間、R−S 間のそれぞれの期間について、プレートの平均の速さを cm/年で求めよ。(2)プレートの進む向きは、いつ、どのように変わったか。(この問題の数値は仮想のものである)', hint: '距離〔km〕÷年代の差〔百万年〕で km/百万年が出ます。それを 0.1 倍すると cm/年です。', steps: ['(1) P−Q:1800 km÷20 百万年＝90 km/百万年＝9.0 cm/年。', 'Q−R:2200 km÷(45−20) 百万年＝88 km/百万年≒8.8 cm/年。', 'R−S:1500 km÷(65−45) 百万年＝75 km/百万年＝7.5 cm/年。', '(2) 古い島ほどプレートの進む向きに遠くにある。4500 万年前より後は、古い島が西北西にあるので、プレートは西北西に進んでいる。', '6500 万年前から 4500 万年前までは、古い S が R の北にあるので、プレートは北に進んでいた。約 4500 万年前に、北向きから西北西向きに変わった。'], a: '(1)P−Q 9.0 cm/年、Q−R 約 8.8 cm/年、R−S 7.5 cm/年 (2)約 4500 万年前に、北向きから西北西向きに変わった', check: 'ハワイ−天皇海山列も、ハワイから北西にのびたあと北へ折れ曲がっていて、太平洋プレートの運動の向きが約 4700 万年前に変わった証拠と考えられてきた(ホットスポット自体も少し動いたとする研究もある)。年 7〜9 cm は太平洋プレートの実際の速さとして妥当な大きさ。' }] }
    ],
    drill: [
      { lv: 2, q: '海底の深さが「2500＋350√t〔m〕(t は百万年単位の年代)」で表されるとする。年代 3600 万年の海底の深さを求めよ。また、海嶺の頂上(t＝0)と比べて何 m 深いか。', a: '4600 m、2100 m 深い', exp: 't＝36 百万年なので √36＝6 で、深さは 2500＋350×6＝2500＋2100＝4600 m です。海嶺の頂上(2500 m)より 2100 m 深くなっています。深さが年代の平方根に比例してふえる、というのは、海洋プレートが上から冷やされて、冷たく重い部分がしだいに厚くなることで説明できます。冷えた部分の厚さは、熱が伝わる時間の平方根にほぼ比例してふえるのです。年代を4倍の 144 百万年にしても、深さの増加は2倍(4200 m 増)にしかならず、深さは 6700 m にとどまります。実際には、非常に古い海底では、この式より浅めで頭打ちになることが知られています。' },
      { lv: 3, q: '海嶺と海嶺をつなぐトランスフォーム断層で、地震が起こるのは主に海嶺と海嶺の間の区間だけで、その外側にのびる断裂帯(海嶺の外側の延長部分)ではほとんど起こらない。その理由を説明せよ。', a: '海嶺と海嶺の間では、両側のプレートが逆向きに動いてすれちがうので断層がずれ動くが、その外側の断裂帯では、両側が同じプレートで同じ向きに動いているので、ずれが生じないから', exp: '海嶺はところどころで横にずれていて、ずれた海嶺どうしをつなぐのがトランスフォーム断層です。それぞれの海嶺からは、海洋底が両側に広がっていきます。海嶺と海嶺にはさまれた区間では、断層の片側は一方の海嶺から、もう片側は他方の海嶺から生まれたプレートで、互いに逆向きに動いているため、断層がずれ動いて地震が起こります。一方、海嶺の外側にのびる断裂帯では、両側とも同じ側に広がるプレートで、同じ向きに同じ速さで動いているので、ずれは起こりません(年代のちがう海底の段差が残るだけです)。断層の地形が続いていても、活動しているのは一部だけ、という点がこの問題の要点です。' },
      { lv: 3, q: '海洋プレートが海溝から 30° の角度で一様に沈みこんでいるとする。沈みこむプレートの上面の深さが 110 km になる所は、海溝から水平に何 km 離れているか。また、火山がその付近から陸側にだけ分布する理由を説明せよ。(tan 30°＝0.577)', a: '約 190 km。沈みこむプレートが一定の深さ(約 100 km 前後)に達した所で、プレートから出た水によってマントルが融けてマグマができるので、それより海溝側には火山ができないから', exp: '水平距離を x とすると、tan 30°＝110/x なので、x＝110/0.577≒190 km です。沈みこむプレートは、含んでいた水を深くなるにつれて放出します。その水がプレートの上のマントルに加わると、岩石の融ける温度が下がり、マグマができます。このマグマの発生が、プレートが一定の深さに達した所の上で起こるので、火山はそれより陸側に帯状に並び、海溝側には火山がありません。この境界線を【火山前線(火山フロント)】といい、海溝とほぼ平行に走ります。沈みこむ角度が浅いと、火山前線は海溝から遠くなり、角度が急だと近くなります。' }
    ],
    faq: [
      ['海溝で沈みこむのは、なぜいつも海洋プレートのほうなの?', '海洋プレートは、玄武岩質の海洋地殻とその下のマントル部分からなり、古くなるほど冷えて密度が大きくなります。一方、大陸プレートは、花こう岩質の軽い大陸地殻をもつので、マントルの中へは沈みにくいのです。そのため、海洋プレートと大陸プレートがぶつかると重い海洋プレートが沈みこみ、大陸どうしがぶつかると、どちらも沈まずにもり上がって、ヒマラヤのような大山脈ができます。'],
      ['ホットスポットは、本当にまったく動かないの?', '完全には止まっていないと考えられています。ホットスポットの根はマントルの深い所にありますが、マントル自身もゆっくり流れているので、ホットスポットも少しずつ動くことがあります。それでも、その動きはプレートの速さに比べて小さいので、「ほぼ固定された目印」として、プレートの運動を調べるのに役立ちます。最近の研究では、ハワイ−天皇海山列の折れ曲がりの一部は、ホットスポット自身の移動によるという考えもあります。']
    ]
  });

  add('g4_history', {
    secs: [
      { h: 'さらに深く:酸素の同位体が教える氷期と間氷期', t: '過去の気温を知る手がかりとして、【酸素同位体比】がよく使われます。酸素には、ふつうの ¹⁶O のほかに、中性子が2個多い重い ¹⁸O が少しふくまれています。\nしくみはこうです。海水が蒸発するとき、軽い ¹⁶O をふくむ水分子のほうが蒸発しやすいので、水蒸気や雨・雪は ¹⁶O が多くなります。【氷期】には、その雪が大陸の上に厚い氷床としてたまり、海にもどってきません。すると、海水には重い ¹⁸O が多く残ります。つまり、【氷期ほど海水の ¹⁸O の割合が大きく】なり、同時に海面は下がります。\n海にすむ有孔虫は、海水の酸素を使って炭酸カルシウムの殻をつくるので、殻には当時の海水の酸素同位体比が記録されます。また、水温が低いほど殻に ¹⁸O が多く入る性質もあり、どちらの効果も「寒いほど ¹⁸O が多い」向きにはたらきます。海底の堆積物を掘りぬいたコアの有孔虫の殻を、深さ(年代)ごとに調べると、過去の氷期と間氷期のくり返しが読み取れます。\n一方、南極やグリーンランドの氷床そのもの(もとは雪)は ¹⁶O が多く、寒い時期に降った雪ほど ¹⁸O が少なくなります。海の記録とは【逆向き】になる点に注意が必要です。\nこうした記録から、過去数十万年の間、氷期と間氷期がおよそ 10 万年の周期でくり返してきたことが分かりました。この周期は、地球の公転軌道の形や自転軸の傾きのゆっくりした変化(ミランコビッチサイクル)によって、地球が受ける日射の分布が変わることと関係していると考えられています。', key: '氷期には軽い ¹⁶O が氷床にたまり、海水と有孔虫の殻の ¹⁸O が多くなる。氷床の氷では逆に ¹⁸O が少なくなる。', ex: [{ q: '海底の堆積物のコアにふくまれる有孔虫の殻の ¹⁸O の割合を、深さごとに調べた。ある深さの層では、その上下の層に比べて ¹⁸O の割合が大きかった。(1)その層が堆積したころの気候は、氷期・間氷期のどちらと考えられるか。(2)そのころの海面の高さは、上下の層のころと比べてどうだったか。(3)同じ時期の南極の氷床の氷を調べると、¹⁸O の割合は、その前後の時期と比べてどうなっていると考えられるか。', hint: '氷床に ¹⁶O が多くたまると、海水はどうなるかを考えます。', steps: ['軽い ¹⁶O をふくむ水が蒸発しやすく、氷期にはそれが雪として氷床にたまり、海にもどらない。', '(1) 海水に ¹⁸O が多く残り、殻の ¹⁸O の割合が大きくなるので、¹⁸O が多い層は氷期にできたと考えられる(水温が低いことも同じ向きにはたらく)。', '(2) 大量の水が氷床として陸上にたくわえられるので、海面は低かった。', '(3) 氷床の氷は、もとは ¹⁶O の多い雪で、寒いほどさらに ¹⁸O が少なくなるので、前後の時期より ¹⁸O の割合が小さいと考えられる。'], a: '(1)氷期 (2)低かった (3)小さい', check: '海の記録と氷床の記録は、¹⁸O の増減が逆向きになるが、どちらも同じ時期に氷期を示すことで、互いの年代や解釈を確かめ合える。最終氷期の最盛期(約2万年前)には、海面が現在より約 120 m 低かったと考えられている。' }] },
      { h: '実戦演習:傾いた地層の走向・傾斜と、地下の深さの予測', t: '地層が傾いているとき、その向きを表すのが【走向】と【傾斜】です。走向は、地層の面と水平面が交わる線(同じ高さを結んだ線)の向き、傾斜は、地層の面が水平面となす角とその傾き下がる向きです。例えば「走向 N30°E、傾斜 20°SE」は、北から東へ 30° の向きに同じ高さの線がのび、南東へ 20° の角度で傾き下がっていることを表します。\n戦略:①同じ地層の境界の標高を、何地点かで比べます。標高が同じ地点を結んだ線が走向です。②走向に垂直な方向で、標高の差÷水平距離＝tan(傾斜角)。③予測したい地点の地層の標高を、傾き(1 m 進むと何 m 下がるか)から求めます。④その地点の地表の標高から地層の標高を引くと、地表からの深さになります。\n落とし穴:「地表からの深さ」と「地層の標高」を混同すること。地表に起伏があるときは、標高どうしで計算してから、最後に深さに直しましょう。また、走向に斜めの方向の距離をそのまま使うと、傾斜角を小さく見積もってしまいます。', key: '同じ標高を結ぶ線が走向。走向に垂直に、標高差÷水平距離＝tan(傾斜)。計算は標高で行い、最後に深さに直す。', ex: [{ q: 'ある地域の凝灰岩層(鍵層)の上面について、次のことが分かった。南北に並んだどの地点でも、上面の標高は同じだった。地点 A では上面の標高が 80 m、A の西 300 m の地点 B では 140 m だった。地層の面は平らで、一様に傾いているとする。(1)この地層の走向と、傾き下がる向きを答えよ。(2)傾斜角の tan の値を求めよ。(3)A の東 200 m の地点 C(地表の標高 90 m)では、凝灰岩層の上面は地表から何 m の深さにあるか。', hint: '西へ行くほど高いので、東へ傾き下がっています。', steps: ['(1) 南北に並んだ地点で標高が同じなので、走向は南北(N−S)。西の B が高く、東の A が低いので、地層は東へ傾き下がっている。', '(2) 東西方向(走向に垂直)に 300 m で、標高差は 140−80＝60 m。tan(傾斜角)＝60/300＝0.20(傾斜角は約 11°)。', '(3) 東へ 1 m 進むごとに 0.20 m 下がる。A から東へ 200 m の C では、上面の標高は 80−0.20×200＝40 m。', '地表の標高が 90 m なので、深さは 90−40＝50 m。'], a: '(1)走向は南北、東へ傾き下がる (2)0.20 (3)50 m', check: 'B から C までは東へ 500 m で 0.20×500＝100 m 下がり、140−100＝40 m となって(3)と一致する。走向 N−S、傾斜約 11°E のように表せる。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある地層の走向・傾斜が「N45°W、30°NE」と記録されていた。この地層について、(1)同じ高さを結んだ線はどの方向にのびているか。(2)地層はどちらの方向へ、何度の角度で傾き下がっているか。', a: '(1)北西−南東の方向 (2)北東へ 30° の角度で傾き下がっている', exp: '走向「N45°W」は、北から西へ 45° 回った方向、つまり北西の方向(反対向きの南東も同じ線)を表します。地層の面上で、この方向にはどこまで行っても高さが変わりません。傾斜「30°NE」は、走向に垂直な方向のうち北東側に、30° の角度で傾き下がることを表します。走向と傾斜の向きは必ず直角になるので、走向が N45°W なら、傾斜の向きは北東か南西のどちらかになります。地質図では、走向の線に傾斜の向きを示す短い線をつけた記号で表し、傾斜角の数字をそえます。地層の上下の判定(級化層理など)と組み合わせると、地層が逆転していないかも確かめられます。' },
      { lv: 3, q: '海底の堆積物のコアで、有孔虫の殻の ¹⁸O の割合が大きい層と小さい層が交互に現れた。¹⁸O の割合が大きい層が堆積したころ、陸上の氷床の量と海面の高さはどうだったと考えられるか。また、¹⁸O が蒸発しにくいことが、この判断にどう使われているか説明せよ。', a: '氷床が多く、海面は低かった(氷期)。¹⁸O をふくむ水は蒸発しにくいので、蒸発して雪になり氷床にたまる水は ¹⁶O が多く、氷床が大きい時期ほど海水に ¹⁸O が多く残るため', exp: '重い ¹⁸O をふくむ水分子は、軽い ¹⁶O をふくむものより蒸発しにくいので、海から蒸発する水蒸気は ¹⁶O にかたよります。氷期にはその水蒸気が雪となって大陸に氷床として積もり、海にもどってきません。そのため海水は ¹⁸O の割合が大きくなり、それを使ってつくられた有孔虫の殻も ¹⁸O が多くなります。氷床に大量の水がたくわえられるので、海面は低くなります。間氷期には氷床がとけて ¹⁶O の多い水が海にもどり、¹⁸O の割合は小さくなります。さらに、水温が低いと殻に ¹⁸O が取りこまれやすいという効果も、同じ向き(寒いほど ¹⁸O が多い)にはたらきます。' },
      { lv: 3, q: 'ある地域の地層で、下の火山灰層 X の年代は 52 万年前、その 40 m 上にある火山灰層 Y の年代は 32 万年前だった。この間の地層は一定の速さで堆積したとする。(1)堆積速度を mm/年で求めよ。(2)X の 10 m 上の層は何万年前に堆積したか。', a: '(1)0.20 mm/年 (2)47 万年前', exp: '(1)40 m の地層が 52−32＝20 万年で堆積したので、堆積速度は 40 m÷20 万年＝40000 mm÷200000 年＝0.20 mm/年です。(2)X から 10 m 上までは、10000 mm÷0.20 mm/年＝5 万年かかるので、52−5＝47 万年前になります。火山灰層は、広い範囲に一度に降り積もり、ふくまれる鉱物から放射年代を測れるので、年代の分かった「目盛り」として使えます。ただし、地層は押し固められて薄くなったり(圧密)、途中に堆積の止まった時期(不整合など)があったりするので、一定の速さという仮定がどこまで正しいかを考えることも大切です。' }
    ],
    faq: [
      ['走向と傾斜は、なぜ2つも必要なの?', '地層の面のような「平面」の向きは、1つの量だけでは決まらないからです。走向は、平面が「どの方向にのびているか(水平な線の向き)」を、傾斜は「どちらへどれだけ傾いているか」を表します。例えば走向が同じ南北でも、東へ傾くか西へ傾くか、10° か 60° かで、地下の地層の位置はまったく変わります。2つをそろえることで、離れた地点の地下で地層がどの深さにあるかを予測できます。'],
      ['氷期には、海面はどのくらい下がったの?', '最終氷期の最も寒い時期(約2万年前)には、現在より海面が約 120 m 低かったと考えられています。そのため、浅い海は陸地になり、日本列島と大陸の間や、日本の島どうしの間の一部も陸続きか、それに近い状態になって、動物が移動できたと考えられています。海面の低下は、有孔虫の殻の酸素同位体比のほか、現在は海の底にある昔の海岸の地形や、サンゴ礁の年代などからも調べられています。']
    ]
  });

  add('g4_atmos', {
    secs: [
      { h: 'さらに深く:大気が「安定」か「不安定」かは、気温減率の比べっこで決まる', t: '空気のかたまりが何かのきっかけで少し持ち上げられたとき、そのまま上昇を続けるか、もとの高さにもどるかは、【まわりの空気との温度差】で決まります。持ち上げられた空気がまわりより暖かければ軽いので上昇を続け(不安定)、冷たければ重いので押しもどされます(安定)。\n持ち上げられた空気は断熱膨張で冷えます。雲ができていない(飽和していない)空気は 100 m につき約 1.0℃(乾燥断熱減率)、雲ができている(飽和した)空気は約 0.5℃(湿潤断熱減率)の割合で温度が下がります。これを、まわりの大気の実際の気温減率 Γ と比べます。\n・Γ が 0.5℃/100 m より小さい:飽和していてもいなくても、持ち上げた空気はまわりより冷たくなる → 【絶対安定】\n・Γ が 1.0℃/100 m より大きい:どちらの空気もまわりより暖かくなる → 【絶対不安定】\n・Γ がその間(例えば 0.7℃/100 m):飽和していない空気は安定だが、飽和した空気は不安定 → 【条件つき不安定】\n具体例:地上の気温 20℃、Γ＝0.7℃/100 m のとき、1000 m 上空のまわりの気温は 13℃ です。飽和していない空気を 1000 m 持ち上げると 10℃ になり、まわりより冷たいので沈みます。飽和した空気なら 15℃ で、まわりより暖かいので上昇を続け、積乱雲のような背の高い雲に発達します。\n実際の対流圏の平均の気温減率は約 0.65℃/100 m で、条件つき不安定の範囲にあります。つまり大気は、ふだんは安定でも、湿った空気が持ち上げられて雲ができると、急に不安定になりうるのです。上空に寒気が入る(Γ が大きくなる)と大気が不安定になり、雷雨が起こりやすくなるのもこのためです。', key: 'まわりの気温減率 Γ を、乾燥(1.0)・湿潤(0.5)断熱減率と比べる。0.5＜Γ＜1.0 は条件つき不安定で、雲ができると上昇が止まらなくなる。', ex: [{ q: '地上の気温が 25℃ で、まわりの大気の気温減率が 0.80℃/100 m の日がある。(1)地上の飽和していない空気のかたまりを 500 m 持ち上げたとき、その空気とまわりの気温をそれぞれ求め、その後どう動くか答えよ。(2)飽和した空気のかたまりを 500 m 持ち上げた場合はどうか。(3)この日の大気の安定性を何というか。', hint: '持ち上げた空気は、飽和していなければ 1.0℃/100 m、飽和していれば 0.5℃/100 m で冷えます。', steps: ['500 m 上空のまわりの気温は 25−0.80×5＝21℃。', '(1) 飽和していない空気は 25−1.0×5＝20℃ になり、まわりの 21℃ より冷たく重いので、もとの高さへもどろうとする(安定)。', '(2) 飽和した空気は 25−0.5×5＝22.5℃ になり、まわりより暖かく軽いので、さらに上昇を続ける(不安定)。', '(3) 飽和していない空気には安定、飽和した空気には不安定なので、条件つき不安定。'], a: '(1)空気 20℃、まわり 21℃。もとの高さへもどる (2)空気 22.5℃ でまわりより暖かく、上昇を続ける (3)条件つき不安定', check: '0.80 は 0.5 と 1.0 の間にあるので、判定の表と一致する。もし気温減率が 1.2℃/100 m なら、飽和していない空気でも 20℃＞19℃ となって上昇し、絶対不安定になる。' }] },
      { h: '実戦演習:雲底の高さと、積乱雲が自力で発達し始める高さ', t: '湿った空気が山の斜面などで持ち上げられるとき、①どの高さで雲ができ始めるか(雲底の高さ)、②どの高さから先は持ち上げられなくても自分で上昇するか、を求める問題は、気象の計算問題の総仕上げです。\n戦略:①上昇する空気の温度は 100 m につき 1.0℃ 下がりますが、露点も、空気が膨張して水蒸気の密度が下がるので 100 m につき約 0.2℃ 下がります。両者の差は 100 m につき 0.8℃ ずつ縮まるので、【雲底の高さ≒(気温−露点)÷0.8×100 m＝125×(気温−露点) m】。②雲ができたあとは 0.5℃/100 m で冷えます。③まわりの気温と比べ、上昇する空気がまわりより暖かくなる高さを求めます。ここから上では浮力で自然に上昇するので、雲が大きく発達します。\n落とし穴:露点を一定と考えて、雲底の高さを (気温−露点)÷1.0×100 m としてしまうこと。また、雲ができる前と後で減率を切りかえ忘れることにも注意します。', key: '雲底の高さ≒125×(気温−露点) m。雲ができたら 0.5℃/100 m。まわりより暖かくなる高さから上は自力で上昇する。', ex: [{ q: '地上の気温が 25℃、露点が 17℃ の空気のかたまりが、山の斜面にそって持ち上げられた。まわりの大気の気温減率は高さによらず 0.70℃/100 m で、地上のまわりの気温も 25℃ とする。(1)雲ができ始める高さを求めよ。(2)その高さでの、空気のかたまりとまわりの気温を求めよ。(3)空気のかたまりが、まわりより暖かくなり始める高さを求めよ。', hint: '(3)では、雲ができたあと「空気のかたまり」と「まわり」の温度差が 100 m ごとにいくら縮まるかを考えます。', steps: ['(1) 気温と露点の差は 25−17＝8℃。差は 100 m につき 1.0−0.2＝0.8℃ ずつ縮まるので、8÷0.8×100＝1000 m で雲ができ始める。', '(2) 1000 m では、空気のかたまりは 25−1.0×10＝15℃(このとき露点も 17−0.2×10＝15℃ で一致)。まわりは 25−0.70×10＝18℃。', '空気のかたまりのほうが 3℃ 冷たいので、ここではまだ押し上げる力が必要。', '(3) 雲ができたあと、空気のかたまりは 0.5℃/100 m、まわりは 0.70℃/100 m で下がるので、温度差は 100 m につき 0.2℃ ずつ縮まる。3℃ の差がなくなるのは 3÷0.2×100＝1500 m 上、つまり高さ 2500 m。'], a: '(1)約 1000 m (2)空気のかたまり 15℃、まわり 18℃ (3)約 2500 m', check: '2500 m では、空気のかたまりは 15−0.5×15＝7.5℃、まわりは 25−0.70×25＝7.5℃ で等しい。これより上では空気のかたまりのほうが暖かく、強い上昇気流で積乱雲が発達できる。地上付近がより暖かく湿っているほど、この高さは低くなり、雷雨が起こりやすくなる。' }] }
    ],
    drill: [
      { lv: 2, q: 'まわりの大気の気温減率が 0.40℃/100 m のとき、大気は安定・不安定のどちらか。また、このような状態が地表付近で起こりやすいのは、どのような天気の日か。', a: '絶対安定。よく晴れて風の弱い夜から朝(放射冷却で地表付近が冷えるとき)など', exp: '0.40℃/100 m は湿潤断熱減率(約 0.5℃/100 m)より小さいので、持ち上げられた空気は、飽和していてもいなくても、まわりより冷たくなります。したがって大気は【絶対安定】で、上下の空気が混ざりにくく、背の高い雲はできにくくなります。よく晴れて風の弱い夜は、地面が赤外線を出して冷え(放射冷却)、地表付近の空気が冷たくなるので、気温減率が小さくなったり、上ほど暖かい【逆転層】ができたりします。逆転層は極端に安定な状態で、煙や排気ガスが上空へ広がらず地表付近にたまり、霧やスモッグが発生しやすくなります。' },
      { lv: 3, q: '地上の気温が 30℃、露点が 22℃ の空気が上昇するとき、雲ができ始める高さはおよそ何 m か。また、地上の露点が同じで気温が 26℃ の場合はどうか。2つを比べて、湿度と雲底の高さの関係を述べよ。', a: '30℃ のとき約 1000 m、26℃ のとき約 500 m。湿度が高い(気温と露点の差が小さい)ほど、雲底は低くなる', exp: '上昇する空気の温度は 100 m につき 1.0℃、露点は約 0.2℃ 下がるので、両者の差は 100 m につき 0.8℃ ずつ縮まります。雲底の高さはおよそ 125×(気温−露点) m です。30℃ のときは差が 8℃ なので約 1000 m、26℃ のときは差が 4℃ なので約 500 m です。気温と露点の差が小さいほど、空気は飽和に近く(湿度が高く)、少し持ち上げられただけで雲ができます。梅雨どきに雲が低くたれこめるのは、空気が非常に湿っているからです。露点を一定と考えて差÷1.0 とすると、800 m と 400 m になり、実際より低く見積もってしまいます。' },
      { lv: 3, q: '南アメリカのペルー沖では、海岸にそって南から北へ(赤道へ向かって)貿易風が吹いている。この風によって沖へ海水が運ばれ、沿岸で湧昇が起こるしくみを、地球の自転の影響にふれて説明せよ。', a: '南半球では、転向力により、風が吹き続けると海面付近の海水は全体として風の向きに対して左向き(この場合は西、つまり沖)へ運ばれる。沖へ運ばれた海水を補うように、沿岸では深い所の冷たい海水がわき上がる', exp: '風が海面を吹くと、海水は風に引きずられて動き始めますが、地球の自転による転向力を受けて、北半球では右へ、南半球では左へそれていきます。海面から深さ数十 m までの層全体で平均すると、海水は【風の向きに対して直角】の方向へ運ばれます(エクマン輸送)。ペルー沖は南半球なので、北向きの風に対して左、つまり西(沖)へ海水が運ばれます。すると沿岸では海水が不足し、深い所から栄養分に富んだ冷たい水がわき上がります(沿岸湧昇)。この栄養分がプランクトンをふやし、カタクチイワシの好漁場をつくります。エルニーニョ現象で貿易風が弱まると、湧昇も弱まって不漁になります。' }
    ],
    faq: [
      ['積乱雲が夏の午後にできやすいのはなぜ?', '夏の晴れた日は、日射で地面が強く暖められ、地表付近の空気が高温で湿った状態になります。すると地表付近の気温減率が大きくなり、大気が不安定になります。空気が上昇して雲ができると、水蒸気が凝結するときに出す潜熱で空気が暖められ、さらに上昇が強まります。午後は地面の温まりが最大になるので、条件がそろいやすく、夕立や雷雨が起こりやすいのです。上空に寒気が入ると、さらに不安定になります。'],
      ['湿潤断熱減率が乾燥断熱減率より小さいのはなぜ?', '雲ができている空気が上昇して冷えると、水蒸気がさらに凝結して水滴になります。このとき、水蒸気は蒸発するときに受け取った熱(潜熱)を放出するので、空気が暖められます。そのぶん温度の下がり方がゆるやかになり、100 m につき約 0.5℃ になるのです。気温が高いほど含まれる水蒸気が多く、出る潜熱も多いので、湿潤断熱減率は小さくなります。上空の寒い所では、乾燥断熱減率に近づきます。']
    ]
  });

  add('g4_space', {
    secs: [
      { h: 'さらに深く:連星で恒星の質量を量り、質量で寿命が決まることを知る', t: '恒星の質量は、直接はかりに乗せることはできません。そこで使われるのが【連星】です。2つの恒星がたがいのまわりを回っているとき、ケプラーの第3法則を太陽系の外まで広げると、\n【M₁＋M₂＝a³/P²】\n(a は2星の間の平均距離を天文単位 AU で、P は公転周期を年で、質量は太陽質量を単位として表す)が成り立ちます。地球と太陽(a＝1 AU、P＝1 年)を入れると 1 になり、太陽の質量 1 と合います(地球の質量は無視できる)。例えば、a＝20 AU、P＝40 年の連星なら、質量の和は 20³/40²＝8000/1600＝5 太陽質量です。\nこうして多くの主系列星の質量を調べると、【質量が大きいほど光度がずっと大きい】ことが分かりました。おおよそ光度は質量の 4 乗に比例します(質量光度関係)。質量が 2 倍なら光度は約 16 倍、10 倍なら約 1 万倍です。\nここから寿命が分かります。主系列星の寿命は「燃料の量(質量に比例)÷燃料を使う速さ(光度に比例)」なので、寿命は質量÷質量⁴＝質量⁻³ に比例します。太陽の寿命を約 100 億年とすると、10 倍の質量の星は約 1/1000 の 1000 万年ほどで燃料を使いはたします。重い星ほど燃料を多くもっていても、それ以上に激しく燃やすので、早く一生を終えるのです。\nこのことから、星団の HR 図で主系列からはずれ始める点(転向点)の星の質量を読めば、その星団の年齢が分かります。若い星団には重くて青い主系列星が残っていますが、古い星団では、それらはすでに巨星や白色矮星などになっています。', key: '連星で M₁＋M₂＝a³/P²(AU・年・太陽質量)。光度は質量の約4乗、寿命は質量の約 −3 乗に比例する。', ex: [{ q: 'ある連星は、2星の間の平均距離が 8.0 AU、公転周期が 16 年である。(1)2星の質量の和を太陽質量を単位として求めよ。(2)2星の質量が等しいとすると、1つの星の光度は太陽の約何倍か(光度は質量の4乗に比例するとする)。(3)その星の主系列での寿命は約何年か(太陽の寿命を 100 億年とする)。', hint: '(3)寿命∝質量÷光度 です。', steps: ['(1) M₁＋M₂＝a³/P²＝8.0³/16²＝512/256＝2.0 太陽質量。', '(2) 質量が等しいので、1つの星は 1.0 太陽質量。光度は 1.0⁴＝1 倍で、太陽と同じくらい。', '(3) 寿命は質量÷光度＝1.0/1.0 で、太陽と同じ約 100 億年。', '(参考)もし一方が 1.5、もう一方が 0.5 太陽質量なら、重い星の光度は 1.5⁴≒5 倍、寿命は 1.5/5≒0.3 倍の約 30 億年となる。'], a: '(1)2.0 太陽質量 (2)約1倍 (3)約 100 億年', check: '地球と太陽の組み合わせ(a＝1、P＝1)で 1 になることから、式の単位の組み合わせが正しいことを確かめられる。質量の和しか分からないので、それぞれの質量を知るには、2星が共通の重心のまわりを回る軌道の大きさの比(質量の逆比)も測る必要がある。' }] },
      { h: '実戦演習:変光星で銀河までの距離をはかり、星間吸収を補正する', t: '遠い銀河までの距離は、明るさの分かっている天体(標準光源)を使って測ります。代表が【セファイド(ケフェウス座δ型変光星)】で、変光の周期が長いほど絶対等級が明るい(周期光度関係)という性質があります。\n戦略:①観測した変光周期から、周期光度関係を使って絶対等級 M を決めます。②見かけの等級 m との差 m−M(距離指数)から、【d＝10^((m−M)/5＋1) パーセク】で距離を出します。③星と私たちの間に星間物質(ちり)があると、光が吸収されて暗く見えます(星間吸収)。吸収で暗くなった分を A 等級とすると、【m−M−A】を距離指数として使います。\n落とし穴:星間吸収を無視すると、天体が実際より暗く見えている分を「遠いから暗い」と解釈してしまい、距離を【大きく見積もり】ます。また、5 等級の差が明るさ 100 倍、距離 10 倍に対応することを使うと、計算の見当がつけやすくなります。', key: 'd＝10^((m−M)/5＋1) パーセク。星間吸収 A があれば m−M−A を使う。吸収を無視すると距離を大きく見積もる。', ex: [{ q: 'ある銀河の中に、変光周期から絶対等級が −4.0 等と分かるセファイドが見つかった。このセファイドの平均の見かけの等級は 21.0 等だった。(1)星間吸収がないとして、この銀河までの距離をパーセクで求めよ。(2)実際には、この方向の星間吸収によって 1.0 等級暗く見えていた。補正した距離を求めよ。(3)(1)の値は、正しい距離の約何倍になっていたか。(10^0.8≒6.3、1 パーセク＝3.26 光年)', hint: '(2)では m−M−A＝21.0−(−4.0)−1.0 を使います。', steps: ['(1) 距離指数は m−M＝21.0−(−4.0)＝25.0。d＝10^(25.0/5＋1)＝10^6 パーセク(約 330 万光年)。', '(2) 星間吸収を補正すると、距離で暗くなった分は 25.0−1.0＝24.0 等級。', 'd＝10^(24.0/5＋1)＝10^5.8＝10^0.8×10^5≒6.3×10^5 パーセク(約 210 万光年)。', '(3) 1.0×10^6/6.3×10^5≒1.6 倍。吸収を無視すると、距離を約 1.6 倍大きく見積もっていた。'], a: '(1)1.0×10⁶ パーセク (2)約 6.3×10⁵ パーセク (3)約 1.6 倍', check: '1 等級の差は明るさで約 2.5 倍、距離では √2.5≒1.6 倍にあたるので、(3)の結果と一致する。セファイドの周期光度関係そのものも、近くのセファイドの年周視差などで「目盛り」を決めておく必要があり、距離のはしごの各段の誤差が遠くの距離に積み重なる。' }] }
    ],
    drill: [
      { lv: 2, q: '2つの恒星からなる連星の、2星の間の平均距離が 10 AU、公転周期が 10 年だった。2星の質量の和は太陽の何倍か。', a: '10 倍', exp: 'ケプラーの第3法則を連星に使うと、a を AU、P を年で表したとき、質量の和(太陽質量を単位)は M₁＋M₂＝a³/P² です。10³/10²＝1000/100＝10 なので、質量の和は太陽の 10 倍です。この式は、太陽系の惑星について a³/P²＝1(太陽の質量)となることを、ほかの恒星にも広げたものです。万有引力が向心力になるという考え(物理の円運動)から導かれる関係で、恒星の質量を直接求められるほとんど唯一の方法です。距離 a を AU で求めるには、連星までの距離(年周視差)と、2星の見かけの離れ具合(角度)が必要です。' },
      { lv: 3, q: '主系列星の光度は質量の4乗に比例し、主系列での寿命は「質量÷光度」に比例するとする。太陽の寿命を 100 億年として、質量が太陽の 2 倍の主系列星の寿命を求めよ。また、質量が太陽の 0.5 倍の星の寿命は、現在の宇宙の年齢(約 138 億年)と比べてどうか。', a: '2倍の星は約 12.5 億年。0.5 倍の星は約 800 億年で、宇宙の年齢よりずっと長い', exp: '寿命は 質量÷光度 ∝ 質量÷質量⁴＝質量⁻³ です。質量 2 倍なら寿命は 2⁻³＝1/8 倍で、100 億年×1/8＝12.5 億年。質量 0.5 倍なら 0.5⁻³＝8 倍で、800 億年です。これは宇宙の年齢 138 億年よりはるかに長いので、宇宙が誕生してから生まれた軽い星は、まだ1つも主系列を終えていないことになります。逆に、質量が太陽の 10 倍をこえる星は、数千万年以下で一生を終え、超新星爆発を起こします。「燃料が多いほど長持ちする」と考えると逆の答えになりますが、重い星は光度が圧倒的に大きく、燃料を使う速さが質量の増え方以上に大きいのです。' },
      { lv: 3, q: 'ある銀河のスペクトル線の波長が、本来の値より 5.0% 長い方へずれていた(赤方偏移 z＝0.050)。後退速度を v＝cz(c＝3.0×10⁵ km/s)で求め、ハッブル定数を 70 km/s/Mpc として、この銀河までの距離を Mpc と光年で求めよ。(1 Mpc＝3.26×10⁶ 光年)', a: '後退速度 1.5×10⁴ km/s、距離 約 2.1×10² Mpc(約 7.0×10⁸ 光年)', exp: '赤方偏移 z は、波長のずれ÷本来の波長です。z が小さいとき、後退速度は v＝cz＝3.0×10⁵×0.050＝1.5×10⁴ km/s と近似できます。ハッブルの法則 v＝H₀d より、d＝1.5×10⁴/70≒214 Mpc、光年に直すと 214×3.26×10⁶≒7.0×10⁸ 光年です。つまり、この光は約 7 億年前にこの銀河を出発したことになります(厳密には、宇宙の膨張のため距離の定義に注意が必要です)。z が 1 に近づくと、v＝cz は使えなくなり、相対論的な扱いが必要になります。また、近くの銀河では、宇宙膨張以外の運動(銀河どうしの引力による運動)の影響が大きく、ハッブルの法則がそのまま使えないこともあります。' }
    ],
    faq: [
      ['重い星ほど寿命が短いのは、なぜ?', '重い星は自分の重力が強いので、中心部が強く押しつぶされて高温・高圧になります。核融合の反応の速さは温度に非常に敏感なので、中心温度が少し高いだけで、燃料の水素を何倍もの速さで使ってしまいます。そのため光度は質量の4乗程度に比例して大きくなります。燃料の量は質量に比例してしかふえないので、使う速さのほうが圧倒的に大きく、寿命は短くなるのです。'],
      ['銀河の赤方偏移は、救急車のサイレンのドップラー効果と同じなの?', '近くの銀河では、ドップラー効果と同じように考えて v＝cz で速度を求められます。しかし本当は、遠くの銀河の赤方偏移は、銀河が空間の中を動いているからというより、【宇宙の空間そのものが膨張し】、光が進む間に波長も引きのばされたために起こると考えられています。そのため、z が大きい遠方の銀河では、ドップラー効果の式をそのまま使うと正しい距離や速度が得られません。']
    ]
  });

  add('gb_solid', {
    secs: [
      { h: 'さらに深く:アイソスタシー ― 大地は「浮いて」いる', t: '地殻は、その下のマントルに比べて密度が小さく(地殻 約 2.7〜3.0 g/cm³、マントル 約 3.3 g/cm³)、長い時間で見ると、マントルの上に【浮いている】ようにふるまいます。マントルは固体ですが、何千年・何万年という時間をかけると、ゆっくり流れることができるからです。氷が水に浮くとき、水面から出ている部分が大きい氷ほど、水の中に沈んでいる部分も大きいのと同じように、高い山脈の下では地殻が厚く、マントルの中に深く根を張っています。このように、地殻とマントルが浮力のつり合いの状態にあることを【アイソスタシー】といいます。\nつり合いの考え方は、「ある深さより下では、どこでも上に乗っているものの重さが等しい」というものです。そのため、上に重いものが加わると地面は沈み、取り除かれると浮き上がります。\n具体例:氷河時代、北ヨーロッパのスカンジナビア半島は、厚さ 3000 m ほどの氷床(密度 約 0.9 g/cm³)におおわれていました。氷床の重さとつり合うまでマントルが押しのけられるとすると、沈む深さは 3000×0.9÷3.3≒820 m にもなります。約1万年前に氷床がとけると、重さがなくなった大地はゆっくり浮き上がり始め、いまも場所によっては1年に約 1 cm の速さで隆起が続いています。マントルが流れるのに時間がかかるので、氷がとけてもすぐにはもとにもどらないのです。\nこの考え方は、侵食によって山が削られても、そのぶん地殻が浮き上がるので、山が意外に長く残ることや、地下深くでできた岩石が地表に現れることの説明にも使われます。', key: '地殻はマントルに浮いている。重さが加わると沈み、取り除かれると浮き上がる。マントルが流れるのに時間がかかるので、変化はゆっくり進む。', ex: [{ q: '密度 0.90 g/cm³ の氷床が、厚さ 2000 m で陸地をおおっていた。アイソスタシーが成り立っているとし、マントルの密度を 3.3 g/cm³ とする。(1)氷床の重さで、陸地はおよそ何 m 沈んでいたか。(2)氷床がすべてとけたあと、陸地がこの分だけ浮き上がるとする。現在はすでに 345 m 浮き上がり、いまも年 1.0 cm の速さで浮き上がっているとすると、浮き上がり終わるまであと何年かかるか(速さは一定とする)。', hint: '氷床の重さ(厚さ×密度)と、押しのけたマントルの重さ(沈んだ深さ×密度)が等しくなります。', steps: ['(1) 氷床 1 cm² あたりの重さは、厚さ×密度に比例する:2000 m×0.90。', 'これが、押しのけたマントルの分 x〔m〕×3.3 と等しいので、x＝2000×0.90/3.3≒545 m。', '(2) あと浮き上がる量は 545−345＝200 m＝20000 cm。', '年 1.0 cm なので、20000÷1.0＝2.0×10⁴ 年。'], a: '(1)約 550 m(545 m) (2)約 2 万年', check: '氷の厚さの約 0.27 倍(0.90/3.3)だけ沈む。3000 m なら約 820 m で、本文の例と一致する。実際には、浮き上がりの速さはしだいにおそくなるので、終わるまでの時間はもっと長くかかると考えられる。' }] },
      { h: '実戦演習:2つの観測点のデータから、震源までの距離と発生時刻を決める', t: '共通テストでは、複数の観測点の P波・S波の到着時刻の表から、震源距離・地震の発生時刻・S波の速さなどを順に求めさせる問題がよく出ます。\n戦略:①大森公式 D＝kT(T は初期微動継続時間)から、各観測点の震源距離は T に比例します。②2つの観測点の「P波の到着時刻の差」は、「震源距離の差÷P波の速さ」に等しくなります。これから k が求められます。③震源距離と P波の速さから、P波が届くまでにかかった時間を出し、到着時刻から引けば発生時刻が分かります。④k＝VpVs/(Vp−Vs) の関係、または S波の到着時刻から、S波の速さも出せます。\n落とし穴:「到着時刻の差」と「初期微動継続時間」を混同すること。また、発生時刻を出すとき、到着時刻に時間を足してしまうミスもよくあります。表の数字が何の時刻・時間かを最初に整理しましょう。', key: '震源距離は初期微動継続時間に比例。P波の到着時刻の差＝距離の差÷Vp。発生時刻＝到着時刻−距離÷Vp。', ex: [{ q: 'ある地震を観測点 A と B で観測した。A では P波が 10時00分15秒に届き、初期微動継続時間は 4.0 秒だった。B では P波が 10時00分21秒に届き、初期微動継続時間は 8.0 秒だった。P波の速さを 6.0 km/s とする。(1)大森公式の比例定数 k を求めよ。(2)A と B の震源距離を求めよ。(3)地震の発生時刻を求めよ。(4)S波の速さを求めよ。', hint: 'A と B の震源距離は 4.0k と 8.0k。その差を P波が進むのに、到着時刻の差 6 秒かかります。', steps: ['(1) 震源距離は D＝kT なので、A は 4.0k、B は 8.0k。差は 4.0k。P波の到着時刻の差は 21−15＝6.0 秒なので、4.0k/6.0＝6.0、k＝9.0 km/s。', '(2) A は 4.0×9.0＝36 km、B は 8.0×9.0＝72 km。', '(3) A に P波が届くまでの時間は 36/6.0＝6.0 秒。発生時刻は 10時00分15秒の 6.0 秒前で、10時00分09秒。', '(4) A に S波が届いたのは 15＋4.0＝19 秒、つまり発生から 10 秒後。S波の速さは 36/10＝3.6 km/s。'], a: '(1)9.0 km/s (2)A 36 km、B 72 km (3)10時00分09秒 (4)3.6 km/s', check: 'k＝VpVs/(Vp−Vs)＝6.0×3.6/(6.0−3.6)＝21.6/2.4＝9.0 で(1)と一致する。B でも、P波 72/6.0＝12 秒後(21 秒)、S波 72/3.6＝20 秒後(29 秒)で、初期微動継続時間 8.0 秒と合う。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある地震で、観測点の震源距離は 50 km、震央距離は 30 km だった。震源の深さを求めよ。', a: '40 km', exp: '震源は地下の地震が起こった点、震央はその真上の地表の点です。観測点・震央・震源の3点は、震央の所が直角の直角三角形になります。震源距離が斜辺、震央距離と震源の深さが直角をはさむ2辺なので、三平方の定理より、深さ＝√(50²−30²)＝√(2500−900)＝√1600＝40 km です。3：4：5 の直角三角形になっていることに気づくと、すぐに答えが出ます。震源の深さが分かると、その地震がプレートの境界で起こったのか、沈みこむプレートの内部で起こったのか、陸のプレートの浅い所で起こったのかなどを考える手がかりになります。' },
      { lv: 3, q: '津波の速さは、水深を h〔m〕、重力加速度を g＝9.8 m/s² とすると、およそ √(gh)〔m/s〕で表される。水深 4000 m の海での津波の速さを、m/s と km/時で求めよ。また、水深 10 m の海岸近くではどうなるか。(√39200≒198、√98≒9.9)', a: '水深 4000 m で約 198 m/s(約 710 km/時)、水深 10 m で約 9.9 m/s(約 36 km/時)', exp: '水深 4000 m では √(9.8×4000)＝√39200≒198 m/s です。1 m/s＝3.6 km/時 なので、約 710 km/時で、ジェット機に近い速さです。この速さなら、4000 km はなれた所にも6時間足らずで届きます。実際、1960年のチリ地震の津波は、約1日かけて太平洋を渡り、日本にも被害をもたらしました。水深 10 m では √98≒9.9 m/s、約 36 km/時まで遅くなります。海岸に近づいて速さが遅くなると、後ろから来る波が前の波に追いつき、波の高さが急に高くなります。遅くなったといっても、人が走って逃げられる速さではないので、津波警報が出たら、すぐに高い所へ避難することが大切です。' },
      { lv: 3, q: '厚い氷床がとけて浮き上がりつつある地域では、海岸に、昔の波打ちぎわの跡(古い海岸線)が、現在の海面より高い所に何段も残っていることがある。その理由を、アイソスタシーにもとづいて説明せよ。', a: '氷床がとけて重さがなくなった大地が、マントルがゆっくり流れこむことで少しずつ浮き上がった。浮き上がる途中で波に削られてできた海岸線が、その後さらに持ち上げられたので、高い所に何段も残っている', exp: '氷床の重さで沈んでいた大地は、氷がとけると浮力のつり合いを取りもどすように浮き上がります(アイソスタシー)。しかし、マントルはとてもゆっくりしか流れないので、浮き上がりは何千年・何万年もかけて少しずつ進みます。その間、ある時期の海面の高さで波が陸地を削り、海岸線の地形がつくられます。大地がさらに浮き上がると、その海岸線は海面より高い所に取り残されます。これがくり返されると、古い海岸線が階段のように何段も残ります。いちばん高い所にあるものほど古い海岸線です。日本の海岸段丘は、主に地震にともなう隆起でできたもので、原因がちがう点に注意しましょう。' }
    ],
    faq: [
      ['津波は、海岸に近づくとなぜ高くなるの?', '津波の速さは水深の平方根にほぼ比例するので、浅くなるほど遅くなります。すると、波の先頭が遅くなる間に後ろの部分が追いつき、波の長さがちぢんで、その分だけ高さが高くなります。さらに、湾の奥のように幅がせまくなる地形では、エネルギーが集中してさらに高くなります。沖では高さ数十 cm 程度でも、海岸では数 m 以上になることがあるので、沖で小さく見えても油断できません。'],
      ['マントルは固体なのに、なぜ「浮く」という考え方ができるの?', 'マントルは、地震波(数秒〜数分の短い振動)に対してはかたい固体としてふるまいますが、何千年以上という長い時間では、とてもゆっくり流れる性質をもちます。氷河の氷やアスファルトが、長い時間で見ると少しずつ形を変えるのと似ています。そのため、長い時間で考えるときは、地殻がマントルという「流れるもの」の上に浮いているように扱えるのです。']
    ]
  });

  add('gb_rock', {
    secs: [
      { h: 'さらに深く:マグマから鉱物が出てくる順番と、色指数', t: 'マグマが冷えていくとき、すべての鉱物が同時に結晶になるわけではありません。結晶になり始める温度は鉱物ごとにちがい、高温のマグマから先に結晶になるのは、かんらん石や輝石のような、鉄やマグネシウムを多くふくむ有色鉱物と、カルシウムの多い斜長石です。温度が下がるにつれて、角閃石・黒雲母、ナトリウムの多い斜長石が結晶になり、最後に、低温まで液体として残った部分から、石英・カリ長石が結晶になります。この順番を、研究者の名前をとって【ボーエンの反応系列】ということがあります。\nこの順番を知っていると、岩石の観察結果を説明できます。玄武岩の斑晶に、かんらん石や輝石がよく見られるのは、それらが高温で早く結晶になり、マグマが地表近くで急に冷える前から、地下でゆっくり成長していたからです。一方、石英は、最後まで残った SiO₂ の多い液体から結晶になるので、花こう岩では、ほかの鉱物のすき間をうめるような形で見られることがあります。\n岩石の色を数で表すのが【色指数】(有色鉱物の体積の割合〔%〕)です。おおよそ、色指数が小さい(およそ 20 以下)ものは白っぽいケイ長質岩(流紋岩・花こう岩)、大きい(およそ 40 以上)ものは黒っぽい苦鉄質岩(玄武岩・はんれい岩)、その間が中間質岩(安山岩・閃緑岩)です。例えば、石英 25%、カリ長石 30%、斜長石 35%、黒雲母 10% の岩石の色指数は、有色鉱物が黒雲母だけなので 10 で、等粒状組織なら花こう岩と判断できます。', key: '高温で先に結晶になるのは、かんらん石・輝石・Ca の多い斜長石。最後は石英・カリ長石。色指数＝有色鉱物の体積%。', ex: [{ q: 'ある火成岩を観察した。全体は細かい粒(石基)の中に、大きな結晶(斑晶)が散らばっていた。鉱物の体積の割合は、斜長石 50%、輝石 30%、かんらん石 15%、磁鉄鉱など 5% だった(石基もふくめた割合)。(1)この岩石の色指数を求めよ(磁鉄鉱も有色鉱物にふくめる)。(2)岩石名を答えよ。(3)斑晶として見られやすい有色鉱物を答え、その理由を説明せよ。', hint: '有色鉱物は、輝石・かんらん石・磁鉄鉱です。斑状組織は火山岩の特徴です。', steps: ['(1) 有色鉱物の割合は、輝石 30＋かんらん石 15＋磁鉄鉱など 5＝50%。色指数は 50。', '(2) 色指数が大きく黒っぽいので苦鉄質岩。斑状組織なので火山岩で、玄武岩。', '(3) かんらん石や輝石は、マグマの温度が高いうちに早く結晶になり始める鉱物である。', 'マグマが地下にある間に、ゆっくり大きく成長して斑晶となり、その後マグマが地表付近で急に冷えて、残りの部分が細かい石基になった。'], a: '(1)50 (2)玄武岩 (3)かんらん石・輝石。高温で早く結晶になり始め、地下でゆっくり成長したから', check: '同じ鉱物の組み合わせで、全体が大きな結晶だけからなる等粒状組織なら、はんれい岩になる。石英がふくまれていないことも、SiO₂ が少ない苦鉄質のマグマであることと合っている。' }] },
      { h: '実戦演習:露頭のスケッチから地史を組み立てる', t: '共通テストの地学基礎では、地層・断層・不整合・貫入岩・化石が組み合わさった露頭の図から、できごとの順番を答える問題がよく出ます。\n戦略:①【地層累重の法則】:下の地層ほど古い(ただし地層の逆転がないことを級化層理などで確かめる)。②【切った・切られたの関係】:断層や貫入岩(岩脈)は、それが切っている地層より新しい。断層や岩脈を「切っている」地層や不整合面があれば、それはさらに新しい。③【不整合】:不整合面の下の地層が堆積したあと、隆起して陸になり、侵食され、再び沈降して上の地層が堆積した。下の地層が傾いていれば、傾いたのは侵食より前。④【接触変成】:貫入岩の周りの地層が変成していれば、貫入はその地層の堆積より後。⑤化石で地質時代を決める。\n落とし穴:断層が上の地層まで切っているかどうかを見落とすこと。また、不整合1つに「隆起→侵食→沈降」の3つのできごとがふくまれることを忘れて、順番を数えまちがえることにも注意しましょう。', key: '下ほど古い。切ったものは切られたものより新しい。不整合には「隆起・侵食・沈降」がふくまれる。', ex: [{ q: 'ある露頭で、次のことが観察された。\n・最も下に、傾いた砂岩と泥岩の互層 A があり、フズリナの化石をふくむ。\n・A の上に、でこぼこの面をはさんで、水平な砂岩層 B がある。面のすぐ上には A の岩石のれきをふくむれき岩がある。B からはアンモナイトの化石が見つかった。\n・断層 F が A と B を切っているが、B の上に水平に重なる火山灰層 C は切っていない。\n・岩脈 D が A・B・C のすべてを貫いており、D に接する部分の地層は硬く焼きしまっていた。\n(1)次のできごとを古い順に並べよ。ア:A の堆積 イ:A の傾斜 ウ:B の堆積 エ:断層 F の活動 オ:C の堆積 カ:D の貫入 キ:隆起と侵食(不整合面の形成)\n(2)A と B が堆積した地質時代をそれぞれ答えよ。', hint: 'でこぼこの面と、その上のれき岩は不整合の証拠です。断層 F と岩脈 D が何を切っているかを見ます。', steps: ['A が最も下にあり、最初に堆積した(ア)。A は傾いており、その上の B は水平なので、A が傾いた(イ)あとに、隆起して侵食され不整合面ができた(キ)。', '不整合面の上に、A のれきをふくむ基底れき岩をともなって B が堆積した(ウ)。', '断層 F は A・B を切るが C を切らないので、F の活動(エ)は B の堆積より後で、C の堆積(オ)より前。', '岩脈 D は C までも貫き、周りの地層を接触変成させているので、D の貫入(カ)は最後。', '(2) フズリナは古生代の、アンモナイトは中生代の示準化石。'], a: '(1)ア→イ→キ→ウ→エ→オ→カ (2)A は古生代、B は中生代', check: '「イとキの順」は、傾いた A が不整合面で水平に削られていることから決まる(傾斜不整合)。A と B の間には、古生代末から中生代までの長い時間の空白があると読める。' }] }
    ],
    drill: [
      { lv: 2, q: 'ある深成岩の鉱物の体積の割合は、斜長石 55%、角閃石 25%、黒雲母 10%、石英 10% だった。この岩石の色指数を求め、岩石名として最も適当なものを、花こう岩・閃緑岩・はんれい岩から選べ。', a: '色指数 35、閃緑岩', exp: '有色鉱物は角閃石と黒雲母なので、色指数は 25＋10＝35 です。斜長石と石英は無色鉱物なので数えません。色指数 35 は、白っぽいケイ長質岩(花こう岩、およそ 20 以下)と黒っぽい苦鉄質岩(はんれい岩、およそ 40 以上)の中間にあたるので、中間質の深成岩である閃緑岩が最も適当です。主な鉱物が斜長石と角閃石であることも、閃緑岩の特徴と合います。同じ組成のマグマが地表付近で急に冷えれば、斑状組織の安山岩になります。色指数の境界の値は教科書によって少しちがうので、鉱物の組み合わせ(石英やカリ長石が多いか、かんらん石があるか)もあわせて判断しましょう。' },
      { lv: 3, q: '流紋岩の斑晶には石英が見られることがあるが、玄武岩の斑晶に石英はほとんど見られない。一方、玄武岩の斑晶にはかんらん石がよく見られる。この違いを、マグマから鉱物が結晶になる順番と、マグマの SiO₂ の量にふれて説明せよ。', a: '玄武岩質マグマは SiO₂ が少なく高温で、まずかんらん石や輝石などが結晶になるので、それらが斑晶になる。SiO₂ に富む石英はできにくい。流紋岩質マグマは SiO₂ が多く比較的低温で、石英ができる条件になるので、斑晶にも石英が現れうる', exp: '鉱物が結晶になる順番は、高温ではかんらん石・輝石・Ca の多い斜長石、低温では石英・カリ長石です。玄武岩質マグマは温度が高く(約 1100〜1200℃)、SiO₂ の量が少ないので、地下でゆっくり冷える間に、まずかんらん石や輝石が結晶になって斑晶になります。SiO₂ の少ないマグマでは、石英として結晶になるほどの SiO₂ が余らないので、石英はほとんどできません。流紋岩質マグマは SiO₂ が多く、温度も比較的低い(約 800〜900℃)ので、地下でも石英やカリ長石が結晶になることができ、斑晶として見られることがあります。逆に、流紋岩にかんらん石がほとんど見られないのは、SiO₂ が多いマグマでは、かんらん石が安定に存在できないからです。' },
      { lv: 3, q: '花こう岩は、高温多湿の地域では「まさ土」とよばれる砂のようなものにくずれやすい。石灰岩の地域では、地下に鍾乳洞ができることがある。この2つの現象は、それぞれどのような風化によるものか説明せよ。', a: '花こう岩のまさ土は、温度変化による鉱物ごとの膨張・収縮の差でばらばらになる物理的風化と、長石などが水と反応して粘土鉱物に変わる化学的風化が組み合わさって起こる。鍾乳洞は、二酸化炭素を溶かした雨水や地下水が、石灰岩(炭酸カルシウム)を溶かす化学的風化(溶食)でできる', exp: '花こう岩は、石英・長石・黒雲母など、色も膨張のしかたもちがう鉱物が組み合わさっています。昼夜の温度変化で鉱物ごとに膨張・収縮の大きさがちがうので、鉱物の境目にすき間ができ、ばらばらになります(物理的風化)。さらに、高温多湿の環境では、長石が水と反応して粘土鉱物に変わる化学的風化が進み、粒どうしの結びつきが弱まります。こうしてできたまさ土は、大雨のときに崩れやすく、土砂災害の原因になることがあります。石灰岩は、CO₂ を溶かして弱い酸性になった水と反応して溶けます(CaCO₃＋H₂O＋CO₂→Ca(HCO₃)₂)。地下で長い時間をかけて溶かされると鍾乳洞ができ、溶けた成分が再び沈殿すると鍾乳石や石筍ができます。' }
    ],
    faq: [
      ['石灰岩とチャートは見た目が似ているけれど、どう見分けるの?', 'もっとも簡単なのは、うすい塩酸をかけてみることです。石灰岩は炭酸カルシウムでできているので、二酸化炭素の泡を出して溶けますが、チャートは SiO₂ でできているので反応しません。また、チャートは非常にかたく、くぎで傷をつけようとしても傷がつきませんが、石灰岩は比較的やわらかく、くぎで傷がつきます。石灰岩はサンゴや有孔虫など、チャートは放散虫などの生物の殻が集まってできたものが多いです。'],
      ['地下深くでできた深成岩や変成岩が、地表で見られるのはなぜ?', '地殻が長い時間をかけて隆起し、その上をおおっていた岩石が侵食で削り取られたからです。地表が削られて軽くなると、アイソスタシーによって地殻がさらに浮き上がり、その分また削られる、ということがくり返されます。こうして、数 km〜十数 km の深さでできた岩石も、何千万年もかけて地表に現れます。花こう岩でできた山が多いのも、このような隆起と侵食のくり返しの結果です。']
    ]
  });

  add('gb_atmos', {
    secs: [
      { h: 'さらに深く:雲粒はなぜ雨粒になるのか ― 冷たい雨と暖かい雨', t: '雲は小さな水滴や氷の粒の集まりですが、雲ができてもすぐに雨が降るとはかぎりません。雲粒はとても小さく(直径 0.01 mm 程度)、空気の抵抗が大きいので、落ちる速さはとても小さく(1秒に約 1 cm)、わずかな上昇気流で支えられてしまうからです。雨粒(直径 1〜2 mm 程度)になるには、雲粒の直径が 100 倍以上、体積では 100 万倍(100×100×100)以上に成長する必要があります。その成長のしかたは、主に2つあります。\n①【冷たい雨】:日本のような中緯度の雨の多くはこのしくみです。雲の上部では気温が 0℃ より低く、0℃ 以下でもこおらない水滴(過冷却の水滴)と、氷の粒(氷晶)がまじっています。同じ温度では、氷に対する飽和水蒸気量のほうが水に対するより小さいので、水滴にとってはちょうど飽和の空気が、氷晶にとっては過飽和になります。そのため、水滴から蒸発した水蒸気が氷晶にくっついて、氷晶がどんどん成長します。大きくなった氷の粒(雪)が落ちる途中でとければ雨、とけなければ雪になります。\n②【暖かい雨】:熱帯の、0℃ 以下にならない背の低い雲でも雨が降ります。大きめの雲粒が落ちる途中で、小さな雲粒とぶつかって合体(併合)しながら大きくなるしくみです。\n雲粒ができるためには、空気中の小さな粒(凝結核)が必要でしたが、雨になるためには、このように雲粒をさらに大きく育てるしくみが必要なのです。', key: '雨粒は雲粒の体積の約 100 万倍。冷たい雨は「氷晶が水滴の水蒸気をうばって成長」、暖かい雨は「雲粒どうしの合体」で育つ。', ex: [{ q: '直径 0.02 mm の雲粒が集まって、直径 2 mm の雨粒が1つできるとする。(1)雨粒1つをつくるのに、雲粒はおよそ何個必要か。(2)0℃ 以下の雲の中で、過冷却の水滴と氷晶がまじっているとき、氷晶が成長し水滴が小さくなっていく理由を説明せよ。', hint: '(1)体積は直径の3乗に比例します。', steps: ['(1) 直径の比は 2/0.02＝100 倍。', '体積は直径の3乗に比例するので、100³＝1×10⁶ 倍。雲粒が約 100 万個必要。', '(2) 同じ温度では、氷に対する飽和水蒸気量は、水に対する飽和水蒸気量より小さい。', 'そのため、水滴にとってちょうど飽和している空気は、氷晶にとっては過飽和になり、水蒸気が氷晶の表面に昇華してくっつく。空気中の水蒸気が減ると、水滴から水が蒸発して補われるので、水滴は小さくなり、氷晶は大きくなっていく。'], a: '(1)約 100 万個 (2)氷に対する飽和水蒸気量のほうが小さいので、空気は氷晶にとって過飽和になり、水滴から蒸発した水蒸気が氷晶にくっついて成長するから', check: '(1)は「直径が 100 倍なら体積は 100 倍」とするまちがいに注意。(2)のしくみは、人工降雨で、ヨウ化銀などをまいて氷晶をつくり、雨や雪を降りやすくする方法の原理にもなっている。' }] },
      { h: '実戦演習:台風の右側が危険な理由と、高潮の大きさ', t: '台風の問題では、風向の変化から台風の通った位置を推理するだけでなく、「なぜ進行方向の右側で風が強いか」「高潮はどれくらいになるか」を考えさせる問題が出ます。\n戦略:①北半球の台風の周りでは、風は中心に向かって反時計回りに吹きこみます。②台風自体が移動していると、地面から見た風は「回転の風＋台風の移動の速さ」になります。進行方向の【右側】では回転の風と移動の向きがそろうので強くなり、左側では打ち消し合って弱くなります。③高潮は、気圧が下がって海面が吸い上げられる効果(1 hPa につき約 1 cm)と、強い風で海水が岸に吹き寄せられる効果の和です。湾の口に向かって風が吹きこむ地形では、吹き寄せの効果が特に大きくなります。\n落とし穴:台風の右側・左側を、地図の東側・西側と固定して考えてしまうこと。右・左は【台風の進む向き】に対して決まります。北へ進む台風なら東側が右側ですが、北東へ進む台風なら南東側が右側です。', key: '進行方向の右側は「回転の風＋移動の速さ」で強い。高潮＝吸い上げ(1 hPa で約 1 cm)＋吹き寄せ。', ex: [{ q: '中心気圧 950 hPa の台風が、北に向かって時速 36 km で進んでいる。中心から 50 km の所では、台風の回転による風(中心のまわりを反時計回りに回る風)の速さが 40 m/s だった。周りの気圧は 1010 hPa とする。(1)中心から 50 km の東側と西側で、地上から見た風の速さはそれぞれいくらか。(2)台風の中心付近で、気圧の低下による海面の吸い上げはおよそ何 cm か。(3)南に開いた湾の西側を、この台風が北上して通過した。湾では高潮の危険が大きいか小さいか、理由とともに答えよ。', hint: '時速 36 km は 10 m/s。北半球の反時計回りでは、中心の東側で風は北向きに吹きます。', steps: ['(1) 台風の移動の速さは 36 km/時＝10 m/s で北向き。反時計回りの回転の風は、中心の東側では北向き、西側では南向き。', '東側は北向き 40＋北向き 10＝50 m/s、西側は南向き 40−北向き 10＝30 m/s。', '(2) 周りとの気圧差は 1010−950＝60 hPa。1 hPa につき約 1 cm 吸い上げられるので、約 60 cm。', '(3) 台風が湾の西側を北上するので、湾は台風の進行方向の右側(東側)に入り、強い南寄りの風が吹く。', '南に開いた湾の奥へ向かって強い風が吹きこみ、海水が湾の奥に吹き寄せられるので、吸い上げとあわせて高潮の危険が大きい。'], a: '(1)東側 50 m/s、西側 30 m/s (2)約 60 cm (3)大きい。湾が台風の右側に入り、強い南風で海水が湾の奥に吹き寄せられ、気圧低下の吸い上げも加わるから', check: '実際の高潮では、吹き寄せの効果は湾の形や水深によって数 m に達することもあり、吸い上げより大きいことが多い。満潮と重なるとさらに危険になる。1959年の伊勢湾台風では、南に開いた伊勢湾の西側を台風が北上し、大きな高潮被害が出た。' }] }
    ],
    drill: [
      { lv: 2, q: '気温 20℃ の空気 1 m³ に 10.4 g の水蒸気がふくまれている。20℃ の飽和水蒸気量を 17.3 g/m³、25℃ の飽和水蒸気量を 23.1 g/m³ とする。(1)この空気の相対湿度を求めよ。(2)水蒸気の量を変えずに 25℃ に暖めると、相対湿度はいくらになるか。', a: '(1)約 60% (2)約 45%', exp: '相対湿度は「ふくまれている水蒸気量÷その気温での飽和水蒸気量×100」です。(1)10.4÷17.3×100≒60%。(2)水蒸気の量は 10.4 g/m³ のままで、飽和水蒸気量が 23.1 g/m³ に増えるので、10.4÷23.1×100≒45% になります。水蒸気の量が同じでも、気温が上がると相対湿度は下がります。冬に暖房をつけた部屋が乾燥するのはこのためです。逆に、気温が下がると相対湿度は上がり、飽和水蒸気量が 10.4 g/m³ になる温度(露点、約 12℃)まで下がると、水滴ができ始めます。「湿度が下がった＝水蒸気が減った」とは限らない点に注意しましょう(厳密には、暖めると空気が膨張して 1 m³ あたりの量も少し減りますが、ここでは無視しています)。' },
      { lv: 3, q: '地球の大気を、太陽の光は素通りさせ、地表からの赤外線はすべて吸収する1枚の層と考える(単純な温室効果のモデル)。大気の層は、吸収したエネルギーを上向きと下向きに半分ずつ放射する。大気がない場合の地表の放射平衡温度を 255 K とすると、このモデルでの地表の温度はいくらか。(⁴√2≒1.19)', a: '約 303 K(約 30℃)', exp: '大気がないとき、地表は太陽から受けるエネルギー S と同じだけを放射して、温度 255 K でつり合います。大気の層があると、層は宇宙へ S を放射しなければならない(地球全体として、受け取る分と出す分がつり合う)ので、層は上向きに S、下向きにも S を放射します。すると地表は、太陽からの S と大気からの S の合計 2S を受け取り、2S を放射してつり合います。放射の強さは絶対温度の4乗に比例する(シュテファン・ボルツマンの法則)ので、地表の温度は 255×⁴√2≒255×1.19≒303 K です。実際の地表の平均気温は約 288 K(15℃)で、このモデルより低いのは、実際の大気は赤外線を一部しか吸収せず、対流や水の蒸発でも熱を運んでいるからです。' },
      { lv: 3, q: '0℃ より低い雲の中で、過冷却の水滴だけがあり、氷晶がほとんどないと、雲があってもなかなか雨や雪が降らないことがある。このような雲に、氷晶の核になる物質をまくと、雨や雪が降りやすくなるのはなぜか。', a: '氷晶ができると、氷に対する飽和水蒸気量が水に対するものより小さいため、氷晶が水滴から水蒸気をうばって急速に成長し、落下できる大きさの雪の粒になるから', exp: '雲粒は小さすぎて落ちてこないので、雨や雪になるには、粒を大きく成長させるしくみが必要です。0℃ 以下でも、水滴は氷になるきっかけ(氷晶核)がないと、こおらずに過冷却の状態のままでいます。そこに氷晶の核になる物質(ヨウ化銀やドライアイスなど)をまくと、氷晶ができます。同じ温度では、氷の表面のほうが水蒸気がくっつきやすい(氷に対する飽和水蒸気量が小さい)ので、水滴から蒸発した水蒸気が氷晶にくっつき、氷晶は急速に大きくなります。大きくなった氷の粒は落下し、途中でとければ雨、とけなければ雪になります。これが人工降雨の考え方で、冷たい雨のしくみを利用しています。' }
    ],
    faq: [
      ['雲は水や氷の粒なのに、なぜ落ちてこないの?', '雲粒は直径 0.01 mm 程度と非常に小さく、重さに比べて空気の抵抗が大きいので、落ちる速さは1秒に約 1 cm しかありません。雲の中には、これより速い上昇気流があることが多いので、雲粒は支えられて浮いているように見えます。また、雲の下の乾いた空気に落ちると、すぐに蒸発してしまいます。雨粒のように大きくなると、落ちる速さが1秒に数 m になり、上昇気流に逆らって落ちてくるようになります。'],
      ['高潮と津波は、どちらも海面が高くなるけれど、何がちがうの?', '原因がちがいます。高潮は、台風や発達した低気圧による気圧の低下(海面の吸い上げ)と強風(吹き寄せ)で、数時間かけて海面が高くなる現象です。津波は、海底の地震などで海底が急に動き、その上の海水全体が持ち上げられて生じる波で、海の深い所まで動きをともない、非常に長い波長で伝わります。津波は遠くの地震でも、天気に関係なく突然やってきます。どちらも、海岸から離れた高い所へ避難することが大切です。']
    ]
  });

  add('gb_space', {
    secs: [
      { h: 'さらに深く:ハビタブルゾーンの位置は、恒星の明るさで決まる', t: '惑星の表面に液体の水が存在できる、恒星からの距離の範囲を【ハビタブルゾーン】といいます。太陽系では、ほぼ地球の軌道付近にあたります。では、太陽とは明るさのちがう恒星では、ハビタブルゾーンはどこにあるのでしょうか。\n惑星が受け取る恒星の光の強さは、恒星の光度 L に比例し、距離 d の2乗に反比例します(光は球面に広がるので、距離が2倍なら面積は4倍になり、強さは 1/4 になる)。惑星の温度は、受け取る光の強さで決まります。したがって、地球と同じ強さの光を受ける距離は、L/d² が太陽と地球の場合と等しくなる所、つまり\n【d＝√L】(d は AU、L は太陽の光度を 1 とした値)\nです。光度が太陽の 4 倍の恒星なら √4＝2 AU、1/100 の暗い恒星(赤色矮星)なら √0.01＝0.1 AU がハビタブルゾーンの目安になります。\nまた、惑星の温度は、受け取る光の強さの 1/4 乗に比例します(放射の強さは絶対温度の4乗に比例するため)。光の強さは 1/d² に比例するので、反射率が同じなら、惑星の温度は 1/√d に比例します。地球(1 AU)の放射平衡温度を約 255 K とすると、火星(約 1.5 AU)では 255/√1.5≒208 K になります。\n赤色矮星は宇宙で最も数の多い恒星で、ハビタブルゾーンが恒星のすぐ近くにあるので、そこを回る惑星は公転周期が短く、トランジット法(惑星が恒星の前を横切って恒星が暗くなるのを測る方法)などで見つけやすいため、生命の探査の重要な対象になっています。', key: '地球と同じ光を受ける距離は d＝√L(AU と太陽光度の単位)。惑星の温度は 1/√d に比例。', ex: [{ q: '(1)光度が太陽の 9 倍の恒星と、0.25 倍の恒星について、地球と同じ強さの光を受ける距離を AU で求めよ。(2)反射率が地球と同じ惑星が、光度が太陽と同じ恒星から 4 AU の所を回っているとき、その放射平衡温度を求めよ(地球の放射平衡温度を 255 K とする)。', hint: '(1)d＝√L。(2)温度は 1/√d に比例します。', steps: ['(1) 9 倍の恒星:d＝√9＝3 AU。', '0.25 倍の恒星:d＝√0.25＝0.5 AU。', '(2) 4 AU では、受け取る光の強さは 1/4²＝1/16。温度は光の強さの 1/4 乗に比例するので (1/16)^(1/4)＝1/2 倍。', 'これは 1/√4＝1/2 倍と同じで、温度は 255×1/2≒128 K。'], a: '(1)9 倍の恒星は 3 AU、0.25 倍の恒星は 0.5 AU (2)約 128 K', check: '(2)は、太陽系では木星(約 5.2 AU)の少し内側にあたり、実際の木星の温度(雲の上端で約 120〜130 K)と同じくらいの大きさになる。木星は内部からも熱を出しているため、単純な比較には注意が必要。' }] },
      { h: '実戦演習:太陽の寿命を、核融合のエネルギーから見積もる', t: '太陽の寿命が約 100 億年であることは、中学・高校で教わる「数字」ですが、それを自分で計算で確かめる問題は、エネルギー・質量・時間の換算を総合的に使う良い練習になります。\n戦略:①太陽が使える燃料の量を決めます。核融合が起こるのは中心部だけなので、太陽の全質量のうち、およそ 10% の水素が燃料になると考えます。②水素がヘリウムになるとき、質量の約 0.7% がエネルギーに変わる(E＝mc²)。③太陽が出しているエネルギーの割合(光度、約 3.8×10²⁶ W＝J/s)で割ると、使いきるまでの時間(秒)が出ます。④秒を年に直します(1 年≒3.15×10⁷ 秒)。\n落とし穴:10% と 0.7% の両方をかけ忘れること、c² の計算で 3.0×10⁸ を2乗し忘れること、秒と年の換算をまちがえることです。また、指数の計算は「仮数」と「10 の何乗か」を分けて計算すると、ミスが減ります。', key: '寿命＝(燃料の質量×0.007×c²)÷光度。燃料は全質量の約 10%。秒→年は 3.15×10⁷ で割る。', ex: [{ q: '太陽の質量を 2.0×10³⁰ kg、光度を 3.8×10²⁶ W とする。太陽の全質量の 10% が水素の核融合に使われ、そのとき使われた質量の 0.70% がエネルギーに変わるとする。(1)核融合で生じる全エネルギーを求めよ。(2)太陽が現在の光度で輝き続けるとすると、何年輝けるか。(c＝3.0×10⁸ m/s、1 年＝3.15×10⁷ 秒)', hint: 'エネルギーに変わる質量は 2.0×10³⁰×0.10×0.0070 kg です。', steps: ['(1) エネルギーに変わる質量は 2.0×10³⁰×0.10×0.0070＝1.4×10²⁷ kg。', 'E＝mc²＝1.4×10²⁷×(3.0×10⁸)²＝1.4×10²⁷×9.0×10¹⁶≒1.26×10⁴⁴ J。', '(2) 1 秒間に 3.8×10²⁶ J ずつ使うので、使いきるまで 1.26×10⁴⁴÷3.8×10²⁶≒3.3×10¹⁷ 秒。', '年に直すと 3.3×10¹⁷÷3.15×10⁷≒1.05×10¹⁰ 年、約 100 億年。'], a: '(1)約 1.3×10⁴⁴ J (2)約 1×10¹⁰ 年(約 100 億年)', check: '太陽が毎秒失う質量は 3.8×10²⁶÷(3.0×10⁸)²≒4.2×10⁹ kg で、本文の「毎秒約 400 万トン」と一致する。この割合で 100 億年たっても、失う質量は太陽全体の約 0.07% にすぎない。' }] }
    ],
    drill: [
      { lv: 2, q: '地球の放射平衡温度を 255 K とする。火星は太陽から約 1.5 AU の所を回っている。反射率が地球と同じだとすると、火星の放射平衡温度はおよそ何 K か。(√1.5≒1.22)', a: '約 209 K', exp: '惑星が受け取る太陽の光の強さは距離の2乗に反比例し、放射平衡温度は受け取る光の強さの 1/4 乗に比例するので、温度は距離の平方根に反比例します。火星の温度は 255÷√1.5≒255÷1.22≒209 K(約 −64℃)です。実際の火星は、反射率が地球より小さく、大気がうすくて温室効果が弱いので、平均気温は約 210 K 前後で、この計算に近い値です。距離が 1.5 倍だから温度も 1/1.5 倍(170 K)としてしまうのがよくあるまちがいです。「光の強さは 1/d²、温度は光の強さの 1/4 乗」という2段階を順にたどると、1/√d になることが分かります。' },
      { lv: 3, q: '光度が太陽の 0.040 倍、質量が太陽の 0.30 倍の赤色矮星がある。(1)地球と同じ強さの光を受ける距離を AU で求めよ。(2)その距離を円軌道で回る惑星の公転周期は約何日か。ケプラーの第3法則 a³/P²＝M(a は AU、P は年、M は太陽質量を単位とした恒星の質量)を使え。(√0.0267≒0.163、1 年＝365 日)', a: '(1)0.20 AU (2)約 60 日', exp: '(1)地球と同じ強さの光を受ける距離は d＝√L＝√0.040＝0.20 AU です。(2)P²＝a³/M＝0.20³/0.30＝0.0080/0.30≒0.0267、P≒0.163 年≒60 日です。赤色矮星のハビタブルゾーンは恒星にとても近いので、惑星は約2か月で1周します。公転周期が短いと、トランジット法で惑星が恒星の前を何度も横切るのを、短い観測期間で確かめられるので、見つけやすくなります。一方、恒星に近いと潮汐力によっていつも同じ面を恒星に向ける(自転と公転の周期が一致する)ようになりやすく、恒星の活動(フレア)の影響も強く受けるので、本当に生命に適しているかは研究が続いています。' },
      { lv: 3, q: 'ある恒星の前を惑星が横切ったとき(トランジット)、恒星の明るさが 1.0% だけ暗くなった。恒星の半径が太陽と同じ(地球の半径の約 109 倍)だとすると、この惑星の半径は地球の約何倍か。', a: '約 11 倍', exp: '惑星が恒星の前を横切ると、恒星の円盤の一部が惑星の円盤でかくされ、その面積の割合だけ暗くなります。暗くなる割合＝(惑星の半径/恒星の半径)² なので、(惑星の半径/恒星の半径)²＝0.010、惑星の半径/恒星の半径＝0.10 です。惑星の半径は 109×0.10≒11 倍で、木星(地球の約 11 倍)と同じくらいの大きさになります。地球のような小さな惑星なら、(1/109)²≒0.0084% しか暗くならないので、とても精密な観測が必要です。トランジット法では、暗くなる割合から惑星の大きさが、くり返しの周期から公転周期が分かります。恒星のふらつき(ドップラー効果)で質量も測れれば、平均密度から、岩石の惑星かガスの惑星かを推定できます。' }
    ],
    faq: [
      ['太陽は、いつか地球をのみこんでしまうの?', '太陽は、およそ 50 億年後に中心部の水素を使いはたすと、赤色巨星になって大きくふくらみ、半径が現在の地球の軌道付近まで大きくなると考えられています。ただし、そのころ太陽は質量を大量に放出して重力が弱まり、地球の軌道も外側へ広がると考えられるので、地球が実際にのみこまれるかどうかは、研究者の間でも見方が分かれています。いずれにしても、それよりずっと前に、太陽が明るくなることで地球の海は蒸発してしまうと考えられています。'],
      ['太陽系の外の惑星(系外惑星)は、どうやって見つけるの?', '惑星は恒星に比べてとても暗いので、直接写すのはむずかしく、主に間接的な方法で見つけます。①トランジット法:惑星が恒星の前を横切るとき、恒星がわずかに暗くなるのを測る。②ドップラー法(視線速度法):惑星の引力で恒星がわずかにふらつき、光のスペクトルが周期的に赤方偏移・青方偏移するのを測る。1995年にドップラー法で太陽に似た恒星を回る惑星が初めて見つかり、現在までに数千個以上の系外惑星が発見されています。']
    ]
  });

})(WPS.LESSONS);
